#include <stdlib.h>

char* multi_string_alloc_and_copy(const char** in)
{
    int len = 0;
    while (in[len]) {
        len++;
    }
    char* chr = malloc(len + 2);
    for (int i = 0; i < len; ++i) {
        chr[i] = in[i];
    }
    return chr;
}

