    struct tx *txs;
    size_t num_txs;
    uint32_t min_sent;
    uint64_t max_wtsum;
    uint64_t metrictxid;
    double metric;
};

// Function to filter transactions based on age, number of transactions in the past 3 seconds, and weighted sum
void *txnet777_filteriterator(struct kv777 *kv, void *_ptr, void *key, int32_t keysize, void *value, int32_t valuesize)
{
    double metric;
    int32_t r;
    struct txnet777_txfilter *filter = _ptr;
    struct tx *tx = value;

    // Check if the transaction is within the desired age range and has not been sent too many times
    if ((filter->oldest == 0 || tx->in.timestamp >= filter->oldest) && (filter->latest == 0 || tx->in.timestamp < filter->latest)) {
        // Check if the transaction has not been sent too many times
        if (tx->H.sent < 3 || (filter->TXNET->ACCT.nxt64bits % 3) == 0 || filter->numitems < sizeof(filter->txids)/sizeof(*filter->txids)) {
            // Add the transaction to the list of filtered transactions
            filter->txids[filter->numitems % 3] = tx->H.sig.txid;
            filter->timestamps[filter->numitems % 3] = tx->in.timestamp;
        }
    }

    // Update the metrics for the filtered transactions
    if (0 && tx->H.wtsum < filter->TXNET->CONFIG.wtsum_threshold) {
        r = (uint32_t)filter->TXNET->ACCT.nxt64bits;
        if (tx->H.sent < filter->minsent || (r % 13) == 0) {
            filter->minsent = tx->H.sent;
            filter->minsenttxid = tx->H.sig.txid;
        }
        metric = tx->H.wtsum / (tx->H.sent + 1);
        if (filter->maxwttxid == filter->minsenttxid || (rand() % 17) == 0) {
            filter->maxwtsum = metric;
            filter->maxwttxid = tx->H.sig.txid;
        }
    }

    // Update the maximum weighted sum and corresponding transaction ID
    if (filter->maxitems != 0 && filter->numitems >= filter->maxitems) {
        return KV777_ABORTITERATOR;
    }
    return 0;
}
