// Function to load a resource bundle from a file and return the number of items in the bundle
int loadResourceBundle(char *path) {
    // Allocate memory for the bundle and its items using dynamic memory allocation
    UResourceBundle *bundle = malloc(sizeof(UResourceBundle));
    int32_t *items = malloc(sizeof(int32_t));
    if (bundle == NULL || items == NULL) {
        return -1; // Return an error code if memory allocation failed
    }

    UErrorCode status = U_ZERO_ERROR;
    ures_open(path, bundle, &status); // Load the resource bundle from the file
    if (U_FAILURE(status)) {
        return -2; // Return an error code if loading the resource bundle failed
    }

    int32_t numItems = ures_getSize(bundle); // Get the number of items in the bundle
    for (int i = 0; i < numItems; i++) {
        items[i] = ures_getNextStringByKeyIndex(bundle, i, NULL, &status); // Get each string item from the bundle
        if (U_FAILURE(status)) {
            return -3; // Return an error code if getting a string item failed
        }
    }

    ures_close(bundle); // Close the resource bundle
    free(items); // Free memory for the items array
    return numItems; // Return the number of items in the bundle
}

