#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define maximum size of strings and string counts
#define MAX_STRING_SIZE 256
#define MAX_COUNT_SIZE 100

// Function to process a text file, ignoring empty lines and comment lines, and extracting strings and string counts from the remaining lines.
int ProcessTextFile(char* filePath)
{
    // Open the file for reading
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filePath);
        return -1;
    }

    // Allocate memory to store the extracted strings and string counts
    char* strings[MAX_COUNT_SIZE];
    int stringCount = 0;
    int stringLengths[MAX_COUNT_SIZE];
    int countLengths = 0;

    // Read each line of the file
    char line[MAX_STRING_SIZE];
    while (fgets(line, MAX_STRING_SIZE, file) != NULL) {
        // Remove trailing newline and whitespace characters from the end of the line
        int length = strlen(line);
        if (length > 0 && line[length - 1] == '\n') {
            line[length - 1] = '\0';
        }
        while (isspace((unsigned char)line[length - 1])) {
            line[--length] = '\0';
        }

        // Check if the line is empty or a comment
        if (line[0] == '\0') {
            continue;
        } else if (line[0] == '#') {
            continue;
        }

        // Extract the string and count from the line
        char* string = strtok(line, " '");
        char* count = strtok(NULL, " '");
        if (string == NULL || count == NULL) {
            printf("Error parsing line: %s\n", line);
            return -1;
        }

        // Add the string and count to the arrays
        strings[stringCount] = string;
        stringLengths[stringCount] = strlen(strings[stringCount]);
        countLengths[countLengths++] = atoi(count);
    }

    // Close the file
    fclose(file);

    // Print the extracted strings and counts
    for (int i = 0; i < stringCount; i++) {
        printf("%s\n", strings[i]);
        for (int j = 0; j < countLengths[i]; j++) {
            printf("!%d %s\n", i, strings[i]);
        }
    }

    // Return the number of strings and counts found in the file
    return stringCount;
}

int main()
{
    char* filePath = "test.txt";
    int count = ProcessTextFile(filePath);
    printf("Found %d strings and counts.\n", count);
    return 0;
}

