// Struct to represent an array.
struct njs_array_t {
    uint32_t start;
    uint32_t size;
    uint32_t length;
    void *data;
};

// Function to dynamically allocate memory for an array and copy a given input array into the allocated memory.
njs_int_t njs_array_expand(struct njs_vm_t *vm, struct njs_array_t *array, uint32_t prepend, uint32_t append) {
    // Calculate the number of free elements before and after the array.
    uint32_t free_before = array->start - array->data;
    uint32_t free_after = array->size - array->length - free_before;

    // If there is enough space before and after the array, return without doing anything.
    if (free_before >= prepend && free_after >= append) {
        return NJS_OK;
    }

    // Calculate the new size of the array.
    uint64_t size = (uint64_t) prepend + array->length + append;
    if (size < 16) {
        size *= 2;
    } else {
        size += size / 2;
    }

    // Check for overflow.
    if (size > (UINT32_MAX / sizeof(njs_value_t))) {
        goto memory_error;
    }

    // Allocate new memory for the array.
    void *start = njs_mp_align(vm->mem_pool, sizeof(njs_value_t), size * sizeof(njs_value_t));
    if (start == NULL) {
        goto memory_error;
    }

    // Copy the old array data to the new memory.
    memcpy(start + prepend, array->data + array->start, array->length * sizeof(njs_value_t));

    // Update the array size and start pointer.
    array->size = size;
    array->start = start + prepend;

    return NJS_OK;

memory_error:
    njs_memory_error(vm);
    return NJS_ERROR;
}

