struct list_node {
    void *data;
    struct list_node *next;
};

typedef struct list_node list_t;

void init_list(list_t **head) {
    (*head)->data = NULL;
    (*head)->next = NULL;
}

void *allocate_array_pointers(size_t size, int *num_elements) {
    void *ptr = malloc(size * sizeof(*ptr));
    if (ptr == NULL) {
        return NULL;
    }
    memset(ptr, 0, size);
    *num_elements = size;
    return ptr;
}

