    void *ptr = allocate_array_pointers(10, &num_elements);
    if (ptr == NULL) {
        return 1;
    }

    for (int i = 0; i < num_elements; i++) {
        head->data = ptr + i * sizeof(*ptr);
        head->next = malloc(sizeof(*head));
        head = head->next;
    }

