#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct {
    char *hostname;
    int port;
} Server;

Server* get_servers(const char* str) {
    // Parse the input string and extract the hostnames and ports
    const char* current = str;
    size_t count = 0;
    while (*current != '\0') {
        if (*current == ',') {
            count++;
        }
        current++;
    }
    // Allocate memory for the server list
    Server* servers = (Server*)malloc(count * sizeof(Server));
    assert(servers != NULL);
    // Initialize the server list
    const char* hostname = strtok(str, ",");
    int port = atoi(strchr(hostname, ':') + 1);
    for (size_t i = 0; i < count; i++) {
        servers[i].hostname = malloc(strlen(hostname) + 1);
        strcpy(servers[i].hostname, hostname);
        servers[i].port = port;
        hostname = strtok(NULL, ",");
        if (hostname != NULL) {
            port = atoi(strchr(hostname, ':') + 1);
        }
    }
    return servers;
}

int main() {
    const char* str = "localhost:11108, localhost:11109";
    Server* servers = get_servers(str);
    // Print the server list
    for (size_t i = 0; i < sizeof(servers) / sizeof(Server); i++) {
        printf("%s:%d\n", servers[i].hostname, servers[i].port);
    }
    // Free the memory allocated for the server list
    for (size_t i = 0; i < sizeof(servers) / sizeof(Server); i++) {
        free(servers[i].hostname);
    }
    free(servers);
    return 0;
}

