#include <string.h>

int is_rotation(const char* s1, const char* s2) {
    size_t len_s1 = strlen(s1);
    size_t len_s2 = strlen(s2);
    if (len_s1 != len_s2)
        return 0;

    int result = 0;
    while (*s1 && *s2) {
        result |= *s1 ^ *s2;
        s1++;
        s2++;
    }

    // If the strings are equal, len_s1 should be equal to len_s2 at this point,
    // and both *s1 and *s2 should be '\0'.
    return (result | *s1 | *s2);
}

