#include <string.h>

// Define the cipher and secret key
const char *cipher = "AES-256";
const char *secret_key = "This is a secret key.";

int encrypt(void *buf, size_t buf_len, int in_len, int *pout_len) {
    // Initialize the cipher and request structures
    struct crypto_skcipher *tfm = ceph_crypto_alloc_cipher();
    SKCIPHER_REQUEST_ON_STACK(req, tfm);
    
    // Setup the scatter-gather table and preallocated SG element
    struct sg_table sgt;
    struct scatterlist prealloc_sg;
    setup_sgtable(&sgt, &prealloc_sg, buf, in_len);
    
    // Set the cipher key and IV
    crypto_skcipher_setkey((void *)tfm, secret_key, strlen(secret_key));
    char iv[AES_BLOCK_SIZE];
    memcpy(iv, aes_iv, AES_BLOCK_SIZE);
    
    // Set the request structure and encrypt/decrypt the data block
    skcipher_request_set_tfm(req, tfm);
    skcipher_request_set_callback(req, 0, NULL, NULL);
    skcipher_request_set_crypt(req, sgt.sgl, sgt.sgl, in_len, iv);
    if (encrypt) {
        ret = crypto_skcipher_encrypt(req);
    } else {
        ret = crypto_skcipher_decrypt(req);
    }
    skcipher_request_zero(req);
    
    // Check for errors and return the encrypted/decrypted data block
    if (ret) {
        fprintf(stderr, "Error: %s\n", strerror(-ret));
        teardown_sgtable(&sgt);
        crypto_free_skcipher(tfm);
        return ret;
    }
    
    // Set the output length and free the resources
    if (encrypt) {
        *pout_len = in_len + AES_BLOCK_SIZE - 1;
    } else {
        *pout_len = in_len - AES_BLOCK_SIZE;
    }
    teardown_sgtable(&sgt);
    crypto_free_skcipher(tfm);
    return 0;
