/* Get the IP address of a DNS name */
pj_status_t get_ip(const pj_str_t *name, struct in_addr *ip)
{
    /* Convert the DNS name to lowercase */
    char *lower_name = strdup(name->ptr);
    for (int i = 0; i < name->slen; i++) {
        if ('A' <= lower_name[i] && lower_name[i] <= 'Z')
            lower_name[i] += 'a' - 'A';
    }
    
    /* Get the IP address from the DNS name */
    struct hostent *host = gethostbyname(lower_name);
