        free(lower_name);
        return PJLIB_UTIL_EDNSINNAMEPTR;
    }

    /* Convert the IP address to octal format */
    char *ip_str = inet_ntoa(*(struct in_addr *)host->h_addr_list[0]);
    strcpy(ip->s_addr, ip_str);
    
    free(lower_name);
    return PJ_SUCCESS;
}

