// Function definitions
void init_buffers(char **buffers, int num_buffers)
{
    for (int i = 0; i < num_buffers; i++)
        memset(buffers[i], 0, sizeof(char) * 1024);
}

void allocate_memory(int *sizes, char *buffer[], int num_buffers)
{
    for (int i = 0; i < num_buffers; i++)
        buffer[i] = malloc(sizeof(char) * sizes[i]);
}

void print_dimensions(int *sizes, char *buffer[], int num_buffers)
{
    for (int i = 0; i < num_buffers; i++)
        syslog(LOG_DEBUG, "Buffer %d: %dx%d array", i, sizes[i], sizeof(char));
}

