// Structure to store line buffering mechanism state
typedef struct {
    char *buffer;
    int buffer_size;
    int buffer_length;
    int file_position;
} LineBuffer;

// Initialize the line buffer with a given size
void initLineBuffer(LineBuffer *lb, int size) {
    lb->buffer = malloc(sizeof(char) * size);
    if (lb->buffer == NULL) {
        printf("Failed to allocate memory for line buffer\n");
        exit(1);
    }
    lb->buffer_size = size;
    lb->buffer_length = 0;
    lb->file_position = 0;
}

// Push a line into the buffer, overwriting any existing lines if necessary
void pushLineBuffer(LineBuffer *lb, char *line) {
    int len = strlen(line);
    if (len > lb->buffer_size) {
        printf("Line is too long to fit in buffer\n");
        exit(1);
    }
    memcpy(lb->buffer, line, len + 1); // include null terminator
    lb->buffer_length = len;
}

// Retrieve the next line from the buffer, or NULL if the end of file has been reached
char *nextLineBuffer(LineBuffer *lb) {
    if (lb->file_position >= lb->buffer_length) {
        return NULL;
    }
    char *line = malloc(sizeof(char) * (lb->buffer_length - lb->file_position + 1));
    if (line == NULL) {
        printf("Failed to allocate memory for line\n");
        exit(1);
    }
    memcpy(line, &lb->buffer[lb->file_position], lb->buffer_length - lb->file_position + 1); // include null terminator
    lb->file_position = lb->buffer_length;
    return line;
}

// Free the memory associated with the line buffer
void freeLineBuffer(LineBuffer *lb) {
    free(lb->buffer);
    lb->buffer = NULL;
    lb->buffer_size = 0;
    lb->buffer_length = 0;
    lb->file_position = 0;
}

