    pushLineBuffer(&lb, "This is a test line");
    char *line = nextLineBuffer(&lb);
    if (line != NULL) {
        printf("Read line: %s\n", line);
        free(line);
        line = NULL;
    }
    pushLineBuffer(&lb, "This is another test line");
    line = nextLineBuffer(&lb);
    if (line != NULL) {
        printf("Read line: %s\n", line);
        free(line);
        line = NULL;
    }
    freeLineBuffer(&lb);
    return 0;
}

