#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct card {
	int type;
	char name[20];
} card_t;

typedef struct cardStack {
	card_t *data;
	struct cardStack *next;
} cardStack_t;

void shuffle(card_t* cards, int numCards) {
	for (int i = 0; i < numCards - 1; i++) {
		int j = rand() % (numCards - i) + i;
		swap(&cards[i], &cards[j]);
	}
}

void swap(card_t* a, card_t* b) {
	card_t temp = *a;
	*a = *b;
	*b = temp;
}

int main() {
	const int CARD_NUM_CARDS = 52;
	card_t cards[CARD_NUM_CARDS];
	for (int i = 0; i < CARD_NUM_CARDS; i++) {
		cards[i].type = i % 4;
		strcpy(cards[i].name, "Card");
