#include <openssl/evp.h>
#include <string.h>

// Define constants for AES-256-CBC cipher and SHA-1 hash function
#define CRYPT_CIPHER EVP_aes_256_cbc()
#define CRYPT_HASH EVP_sha1()

// Define fixed lengths for IV and key
#define CRYPT_IV_SIZE 16
#define CRYPT_KEY_SIZE 32

// Define variables to hold cipher context, IV, and encryption key
EVP_CIPHER_CTX *crypt_cipher = NULL;
uint8_t crypt_iv[CRYPT_IV_SIZE];
uint8_t crypt_key[CRYPT_KEY_SIZE];

// Define function to initialize AES-256-CBC cipher with given password
void init_crypt(const char *password) {
  // Check if password is valid
  if (!password || !*password)
    return;

  // Initialize cipher context and set IV length and key length to fixed values
  crypt_cipher = EVP_CIPHER_CTX_new();
  EVP_CIPHER_CTX_set_iv_length(crypt_cipher, CRYPT_IV_SIZE);
  EVP_CIPHER_CTX_set_key_length(crypt_cipher, CRYPT_KEY_SIZE);

  // Derive encryption key from password using SHA-1 hash function
  uint8_t salt[CRYPT_IV_SIZE];
  memset(salt, 0, sizeof(salt));
  EVP_BytesToKey(crypt_cipher, CRYPT_HASH, salt, (uint8_t*) password, strlen(password), 16, crypt_key, NULL);

  // Set IV to all zeros and enable cipher
  memset(crypt_iv, 0, sizeof(crypt_iv));
  EVP_CipherInit_ex(crypt_cipher, CRYPT_CIPHER, NULL, crypt_key, crypt_iv, true);
}

// Define function to clean up and disable AES-256-CBC cipher when it is no longer needed
void unload_crypt() {
  // Disable cipher and free cipher context
  EVP_CIPHER_CTX_free(crypt_cipher);
  crypt_cipher = NULL;
}
