#include <stdlib.h>
#include <string.h>
#include <glob.h>

static int count_files(char *pattern) {
    glob_t gg;
    int count = 0;

    if (glob(pattern, 0, NULL, &gg)) {
        return -1;
    }

    for (int i = 0; i < gg.gl_pathc; i++) {
        if (!mp_path_isdir(gg.gl_pathv[i])) {
            count++;
        }
    }

    globfree(&gg);

    return count;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <pattern>\n", argv[0]);
        return 1;
    }

    int count = count_files(argv[1]);

    if (count == -1) {
        puts("Error: Invalid pattern");
    } else {
        printf("%d files found\n", count);
    }

    return 0;
}

