int countFiles(const char *path, const char *format) {
    DIR *pdir;
    struct dirent *dp;
    int count = 0;

    if ((pdir = opendir(path)) == NULL) {
        fprintf(stderr, "opendir error: %s\n", path);
        return -1;
    }

    while ((dp = readdir(pdir)) != NULL) {
        if (strcmp(dp->d_name, ".") == 0 || strcmp(dp->d_name, "..") == 0) {
            continue;
        }

        char fullPath[256];
        snprintf(fullPath, sizeof(fullPath), "%s/%s", path, dp->d_name);

        if (isDir(fullPath)) {
            count += countFiles(fullPath, format);
        } else {
            if (strstr(dp->d_name, format) != NULL) {
                ++count;
            }
        }
    }

    closedir(pdir);
    return count;
}
