#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Definition of a configuration structure
typedef struct {
	char *passphrase;
	int standard_mode;
} config_t;

// Function to initialize the library with a specified passphrase.
void init_library(const char *passphrase) {
	printf("Initializing the library with the passphrase: %s\n", passphrase);
}

int main(int argc, char **argv) {
	// Initialize default configuration values
	config_t config = {.passphrase = "default_passphrase", .standard_mode = 1};

	// Parse command line arguments and update the configuration structure accordingly
	for (int i = 1; i < argc; ++i) {
		if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
			usage(0);
		} else if (!strcmp(argv[i], "-s") || !strcmp(argv[i], "--standard")) {
			config.standard_mode = 1;
		} else if (!strcmp(argv[i], "-i") || !strcmp(argv[i], "--inverted")) {
			config.standard_mode = 0;
		} else if (i + 1 < argc) {
			if (!strcmp(argv[i], "KEYFILE")) {
				config.passphrase = argv[i+1];
				++i;
			}
		} else {
			usage(1);
		}
	}

	// Print a version number and message to the console
	printf("Version : 2.3\n");
	printf("Usage : %s [-h | --help] FILE [-s | --standard | -i | --inverted] [KEYFILE]\n", argv[0]);

	// Call the function to initialize the library with the specified passphrase
	init_library(config.passphrase);

	return 0;
}

void usage(int status) {
	FILE *dest = (status == 0) ? stdout : stderr;

	if (status == 0) {
		fprintf(dest, "Usage: %s [-h | --help] FILE [-s | --standard | -i | --inverted] [KEYFILE]\n", argv[0]);
	} else {
		fprintf(dest, "Options:\n  -h --help :\tfurther help\n  -s --standard :\tput the scrambler off\n  -i --inverted :\tinverts the coding/decoding process\n  KEYFILE :\tpath to a keyfile that scrambles the substitution's tables and choose they order instead of the PRNG only\n");
	}

	exit(status);
}

