#include <stdlib.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <time.h>

int main() {
    // Set the dimensions of the matrices A and B
    int m = 3, k = 4;
    
    // Allocate memory on the host for the matrices A and B
    double *A = (double *)malloc(m * k * sizeof(double));
    double *B = (double *)malloc(k * k * sizeof(double));
    
    // Initialize the matrices A and B with random values
    for (int i = 0; i < m * k; i++) {
        A[i] = rand() / (double)RAND_MAX;
    }
    for (int i = 0; i < k * k; i++) {
        B[i] = rand() / (double)RAND_MAX;
    }
    
    // Allocate memory on the device for the matrices A, B and C
    double *dA, *dB, *dC;
    cudaMalloc((void **)&dA, m * k * sizeof(double));
    cudaMalloc((void **)&dB, k * k * sizeof(double));
    cudaMalloc((void **)&dC, m * k * sizeof(double));
    
    // Copy the host matrices A and B to the device
    cudaMemcpy(dA, A, m * k * sizeof(double), cudaMemcpyHostToDevice);
    cudaMemcpy(dB, B, k * k * sizeof(double), cudaMemcpyHostToDevice);
    
    // Create a handle for CUBLAS
    cublasHandle_t handle;
    cublasCreate(&handle);
    
    // Set the pointers mode to host
    cublasSetPointerMode(handle, CUBLAS_POINTER_MODE_HOST);
    
    // Perform the matrix multiplication
    cublasDgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N, m, k, k, 1.0, dA, m, dB, k, 0.0, dC, m);
    
    // Copy the result back to the host
    cudaMemcpy(C, dC, m * k * sizeof(double), cudaMemcpyDeviceToHost);
    
    // Free memory on the device and host
    cudaFree(dA);
    cudaFree(dB);
    cudaFree(dC);
    free(A);
    free(B);
    
    // Destroy the handle
    cublasDestroy(handle);
    return 0;
}

