#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include "nvlist_lookup_uint64.h"

int cdfs_read_path_table(cdfs_t *cdfs, iso_volume_descriptor_t *vd) {
	block_dev_cache_t *cache;
	unsigned char *pt;
	int ptblk;
	int ptlen;
	int ptpos;
	int n;
	iso_pathtable_record_t *pathrec;
	int namelen;
	int reclen;
	char name[128];
	char path[128];

	/* Determine size and location of path table and allocate buffer */
	ptlen = cdfs_isonum_733(vd->path_table_size);
	ptblk = cdfs_isonum_731(vd->type_l_path_table);
	cdfs->path_table_buffer = sysmalloc(ptlen);
	if (!cdfs->path_table_buffer) {
		return -ENOMEM;
	}

	/* Read the path table into the buffer */
	cache = block_dev_cache_get(cdfs->block_dev, ptblk);
	pt = cache->data + (ptblk * 2048);
	memcpy(cdfs->path_table_buffer, pt, ptlen);

	/* Extract the parity level from the device's configuration */
	nvlist_lookup_uint64(vd->configuration, "parity", &cdfs->parity_level);

	/* Concat the path with the parity level */
	strcpy(path, cdfs->path);
	if (cdfs->parity_level > 0) {
		sprintf(name, "%d", cdfs->parity_level);
		strcat(path, name);
	}

	/* Return the path with the parity level included */
	return path;
}

