typedef struct {
  int id;
  char label[10];
} Vertex;

typedef struct {
  int src, dest;
} Edge;

typedef struct {
  int num_vertices;
  int num_edges;
  Vertex* vertices;
  Edge* edges;
} Graph;

void create_graph(Graph* g) {
  int i, j;

  // Initialize vertices and edges
  g->num_vertices = 0;
  g->num_edges = 0;
  g->vertices = NULL;
  g->edges = NULL;

  // Accept user input for vertex modifications
