int retrieve_file(char *filename, char *ipaddr, int mode) {
    // Create a socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        perror("socket");
        return -1;
    }

    // Establish the connection with the remote server
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, ipaddr, &serv_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("connect");
        close(sock);
        return -1;
    }

    // Send a request packet to the remote server
    char *request = "GET /%s HTTP/1.0\r\nHost: %s\r\nConnection: close\r\n\r\n";
    int len = strlen(request) + strlen(filename) + strlen(ipaddr);
    char buffer[len];
    sprintf(buffer, request, filename, ipaddr);
    if (send(sock, buffer, len, 0) < 0) {
        perror("send");
        close(sock);
        return -1;
    }

    // Receive a response packet from the remote server
    char response[BUFSIZE];
    int bytes_received = recv(sock, response, BUFSIZE, 0);
    if (bytes_received < 0) {
        perror("recv");
        close(sock);
        return -1;
    }

    // Close the socket and check for errors
    close(sock);
    if (strncmp(response, "HTTP/1.0 200 OK", 14) != 0) {
        printf("Error: %s\n", response);
        return -1;
    }

    // Open the local file for writing
    FILE *out_file = fopen(filename, "wb+");
    if (out_file == NULL) {
        perror("fopen");
        return -1;
    }

    // Read and write the file data to the local file
    int bytes_written = 0;
    while ((bytes_received = recv(sock, response, BUFSIZE, 0)) > 0) {
        fwrite(response, sizeof(char), bytes_received, out_file);
        bytes_written += bytes_received;
    }

    // Close the local file and check for errors
    fclose(out_file);
    if (bytes_written == 0) {
        perror("fwrite");
        return -1;
    }

    printf("Successfully retrieved %s\n", filename);
    return 0;
}

