int exponential_backoff_with_jitter(MQTTContext *context) {
    // Check if the connection was successful
    int status = context->connect();
    if (status != 0) {
        return status;
    }

    // Implement an exponential backoff strategy with jitter
    int retry_count = 1;
    while (retry_count <= MAX_RETRIES) {
        // Generate a random number for the jitter component using rand()
        int jitter = rand() % JITTER_RANGE;

        // Calculate the backoff delay based on the retry count and jitter
        int backoff_delay = (retry_count * BACKOFF_DELAY) + jitter;
        printf("Backing off for %d seconds...\n", backoff_delay);

        // Sleep for the calculated delay
        sleep(backoff_delay);

        // Try connecting again
        status = context->connect();
        if (status == 0) {
            break;
        }

        // Increment the retry count and try again
        retry_count++;
    }

    return status;
}

