static const char* parse_access_token(const char *json_string, const char *secret_key) {
    /* Create a grpc_exec_ctx object to execute the function */
    grpc_exec_ctx exec_ctx = GRPC_EXEC_CTX_INIT;

    /* Create a grpc_credentials_md_store object to store the token metadata */
    grpc_credentials_md_store *token_md = NULL;

    /* Create a gpr_timespec object to store the token lifetime */
    gpr_timespec token_lifetime;

    /* Create a grpc_httpcli_response object to store the HTTP response */
    grpc_httpcli_response response = http_response(200, json_string);

    /* Parse the JSON string and store the parsed data in token_md and token_lifetime */
    if (grpc_oauth2_token_fetcher_credentials_parse_server_response(&exec_ctx, &response, &token_md, &token_lifetime) == GRPC_CREDENTIALS_ERROR) {
        /* If there was an error parsing the JSON string, return NULL */
        grpc_http_response_destroy(&response);
        grpc_exec_ctx_finish(&exec_ctx);
        return NULL;
