typedef uint32_t MD4_LONG;
typedef uint8_t MD4_HASH[16];

// Structure to hold the state of the algorithm
typedef struct {
    MD4_LONG A, B, C, D;
    MD4_LONG Nl, Nh;
    MD4_LONG data[64];
    unsigned int num;
} MD4_CTX;

// Initializes the algorithm's state
int MD4_Init(MD4_CTX *ctx) {
    ctx->A = 0x67452301;
    ctx->B = 0xefcdab89;
    ctx->C = 0x98badcfe;
    ctx->D = 0x10325476;
    ctx->Nl = ctx->Nh = 0;
    ctx->num = 0;
    return 1;
}

// Updates the algorithm's state with a new message block
int MD4_Update(MD4_CTX *ctx, const void *data, size_t len) {
    // Initialize the variables for the current block
    unsigned long W[64];
    unsigned long A = ctx->A;
    unsigned long B = ctx->B;
    unsigned long C = ctx->C;
    unsigned long D = ctx->D;

    // Copy the message block into the state buffer
    memcpy(ctx->data + ctx->num, data, len);
    ctx->num += len;

    // Process each 64-byte chunk of the message block
    for (int i = 0; i < ctx->num; i += 64) {
        // Initialize the variables for this chunk
        unsigned long W[16];
        memcpy(W, ctx->data + i, 64);

        // Perform the hash operation on this chunk
        MD4_Transform(ctx, W);
    }

    return 1;
}

// Finalizes the algorithm's state and produces the final hash value
int MD4_Final(MD4_HASH *md, MD4_CTX *ctx) {
    // Initialize the variables for the final block
    unsigned long W[64];
    memcpy(W, ctx->data + ctx->num, 64);

    // Process the final block of the message
    MD4_Transform(ctx, W);

    // Copy the hash value into the output buffer
    memcpy(md, &ctx->A, 16);

    return 1;
}

// Performs a single transformation step on a 64-byte message block
void MD4_Transform(MD4_CTX *ctx, const unsigned char *data) {
    // Initialize the variables for this chunk
    unsigned long A = ctx->A;
    unsigned long B = ctx->B;
    unsigned long C = ctx->C;
    unsigned long D = ctx->D;

    // Perform the hash operation on this chunk
    MD4_Transform(ctx, data);
}
