    if (new_filename == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    
    // Determine number of digits and file type based on original filename
    num_digits = count_digits(filename);
    file_type = determine_file_type(filename);
    
    // Create new filename using sprintf and strcat functions
