    return new_filename;
}

int count_digits(const char *str) {
    int count = 0;
    while (*str != '\0') {
        if (isdigit(*str)) {
            count++;
        }
        str++;
    }
    return count;
}

char determine_file_type(const char *filename) {
    // Determine file type based on characters in original filename
    switch (*(filename + strlen(filename) - 1)) {
        case 't':
            return 't';
        case 'x':
            return 'x';
        default:
            return 'u';
    }
}

