using namespace std;
class RobotClient {
private:
	struct Connection {
		char* pcIp;
		char* pcName;
		int nPort;
		int nSocket;
	} m_oConnection;
public:
	RobotClient() {
		m_oConnection.pcIp = "192.168.0.1";
		m_oConnection.pcName = "cart";
		m_oConnection.nPort = 1234;
		m_oConnection.nSocket = -1;
	}
	void initialize() {
		m_oConnection.nSocket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
		if (m_oConnection.nSocket == -1) {
			cout << "Error creating socket" << endl;
		}
		struct sockaddr_in oServerAddress;
		oServerAddress.sin_family = AF_INET;
		oServerAddress.sin_port = htons(m_oConnection.nPort);
		inet_pton(AF_INET, m_oConnection.pcIp, &(oServerAddress.sin_addr));
		if (connect(m_oConnection.nSocket, (struct sockaddr*)&oServerAddress, sizeof(oServerAddress)) == -1) {
			cout << "Error connecting to server" << endl;
		}
	}
	void sendCommand(string sCommand) {
		if (m_oConnection.nSocket != -1) {
			send(m_oConnection.nSocket, sCommand.c_str(), sCommand.length() + 1, 0);
		}
	}
	string receiveResponse() {
		char buffer[1024];
		if (m_oConnection.nSocket != -1) {
			recv(m_oConnection.nSocket, buffer, sizeof(buffer), 0);
		}
		return string(buffer);
	}
};
