#include <iostream>
#include <map>
#include <string>
#include <cstdio>
using namespace std;

struct Page {
	int id;
	char* data;
};

class PagePool {
public:
	PagePool();
	~PagePool();
	Page* createFromFile(const string& path, int pid);
	Page* getPage(int pid);
	void deletePage(int pid);
private:
	map<int, Page*> mp;
};

PagePool::PagePool() {
}

PagePool::~PagePool() {
	for (auto& p : mp) {
		delete[] p.second->data;
		delete p.second;
	}
}

Page* PagePool::createFromFile(const string& path, int pid) {
	char buffer[50];
	sprintf(buffer, "%s/%d.page", path.c_str(), pid);
	auto p = new Page();
	p->id = pid;
	p->data = new char[1024]; // assuming page size is 1KB
	FILE* f = fopen(buffer, "r");
	if (f == nullptr) {
		delete[] p->data;
		delete p;
		return nullptr;
	}
	fread(p->data, sizeof(char), 1024, f);
	fclose(f);
	mp.insert(make_pair(pid, p));
	return p;
}

Page* PagePool::getPage(int pid) {
	auto it = mp.find(pid);
	if (it == mp.end()) {
		return nullptr;
	}
	return it->second;
}

void PagePool::deletePage(int pid) {
	auto it = mp.find(pid);
	if (it != mp.end()) {
		delete[] it->second->data;
		delete it->second;
		mp.erase(it);
	}
}
