    int numKeys; // Number of keys in the table
    KeyInfo *keys; // Array of key information structures
} TableInfo;

// Function to load data into a database using a configurable number of keys, and commits the changes after each key is loaded, while ensuring that the file size does not exceed a minimum block reusing file size.
int loadData(TableInfo *table, int numKeys) {
    // Check if the number of keys provided is valid
    if (numKeys < 0 || numKeys > table->numKeys) {
        fprintf(stderr, "Invalid number of keys provided.\n");
        return -1;
    }

    // Initialize variables for sorting
    int keyIndex = 0; // Index to keep track of the current key being sorted
    KeyInfo *key = NULL; // Pointer to the current key being processed
    char *data = NULL; // Data buffer to hold the data to be loaded
    int dataSize = 0; // Size of the data buffer
    char *sortedData = NULL; // Sorted data buffer to hold the sorted data
    int sortedDataSize = 0; // Size of the sorted data buffer

    // Loop through each key in the table
    while (keyIndex < numKeys) {
        // Get the next key to be processed
        key = &table->keys[keyIndex];

        // Check if the current key has a valid type and block size
        if (key->type == HA_KEYTYPE_TEXT || key->type == HA_KEYTYPE_BINARY) {
            // Calculate the size of the data buffer needed for the current key
            dataSize = key->blockSize * numKeys;

            // Allocate memory for the data buffer
            data = (char *)malloc(dataSize);
            if (!data) {
                fprintf(stderr, "Memory allocation failed.\n");
                return -1;
            }
        } else {
            // Invalid key type, skip this key and continue with the next one
            keyIndex++;
            continue;
        }

        // Load data into the data buffer for the current key
        if (loadDataForKey(table, key->name, data, dataSize) < 0) {
            fprintf(stderr, "Failed to load data for key %s.\n", key->name);
            free(data);
            return -1;
        }

        // Sort the data buffer for the current key
        sortedData = sortData(key->type, data, dataSize, &sortedDataSize);
        if (!sortedData) {
            fprintf(stderr, "Failed to sort data for key %s.\n", key->name);
            free(data);
            return -1;
        }

        // Load the sorted data into the database using a configurable number of keys
        if (loadSortedData(table, key->name, sortedData, sortedDataSize) < 0) {
            fprintf(stderr, "Failed to load sorted data for key %s.\n", key->name);
            free(data);
            return -1;
        }

        // Free the memory allocated for the data buffer and sorted data buffer
        free(data);
        free(sortedData);

        // Increment the key index to move on to the next key in the table
        keyIndex++;
    }

    return 0;
}

