std::vector<int> generateIndices(const std::vector<int>& points) {
    // allocate memory for the indices using new
    std::vector<int>* indices = new std::vector<int>();

    // copy the input array into the newly allocated memory
    *indices = points;

    // increment a counter for the number of primitives used in the wireframe representation
    int numPrimitives = 0;

    // generate indices for points, lines, faces, and lines in the wireframe representation
    std::vector<int>* pointsIndices = new std::vector<int>();
    std::vector<int>* linesIndices = new std::vector<int>();
