template<typename ContainerType>
class PartitionedStorage {
public:
    virtual size_t n_unique_kmers() const = 0;
};

template<typename T, typename StorageType>
struct PartitionedStorageTemplate : public PartitionedStorage<T> {
private:
    std::vector<std::shared_ptr<StorageType>> partitions;

public:
    size_t n_unique_kmers() const override {
        size_t count = 0;
        for (auto& partition : partitions) {
            count += partition->n_unique_kmers();
        }
        return count;
    }
};

template<typename T, typename StorageType>
std::vector<size_t> get_partition_counts(const std::vector<std::shared_ptr<PartitionedStorageTemplate<T, StorageType>>>& partitions) {
    std::vector<size_t> counts;
    for (auto& partition : partitions) {
        counts.push_back(partition->n_unique_kmers());
    }
    return counts;
}

template<typename T, typename StorageType>
void * get_partition_counts_as_buffer(const std::vector<std::shared_ptr<PartitionedStorageTemplate<T, StorageType>>>& partitions) {
    size_t count = 0;
    for (auto& partition : partitions) {
        count += partition->n_unique_kmers();
    }

