/* Structure for 2D array of float values */
typedef struct {
    int rows;
    int cols;
    float** data;
} Array;

/* Function to allocate memory for the 2D array and read the values into it */
Array* read_array(const char* filename) {
    /* Open file in binary mode */
    FILE* f = fopen(filename, "rb");
    if (!f) {
        perror("Error opening file");
        return NULL;
    }

    /* Read the dimensions of the array from the first 2 bytes of the file */
    int rows, cols;
    fread(&rows, sizeof(int), 1, f);
    fread(&cols, sizeof(int), 1, f);

    /* Allocate memory for the array */
    Array* arr = malloc(sizeof(Array));
    if (!arr) {
        perror("Error allocating memory");
        return NULL;
    }

    /* Initialize the rows and cols members of the Array structure */
    arr->rows = rows;
    arr->cols = cols;

    /* Allocate memory for the data member of the Array structure */
    double** data = malloc(sizeof(double*) * rows);
    if (!data) {
        perror("Error allocating memory");
        return NULL;
    }

    /* Initialize the data member of the Array structure */
    for (int i = 0; i < rows; ++i) {
        double* row = malloc(sizeof(double) * cols);
        if (!row) {
            perror("Error allocating memory");
            return NULL;
        }
        data[i] = row;
    }

    /* Read the values into the array */
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            double value;
            fread(&value, sizeof(double), 1, f);
            data[i][j] = value;
        }
    }

    /* Close the file */
    fclose(f);

    /* Set the data member of the Array structure to point to the allocated memory */
    arr->data = data;

    return arr;
}

/* Function to print the dimensions of the array and free the memory */
void print_array(Array* arr) {
    printf("Dimensions: %d x %d\n", arr->rows, arr->cols);
    for (int i = 0; i < arr->rows; ++i) {
        double* row = arr->data[i];
        for (int j = 0; j < arr->cols; ++j) {
            printf("%f ", row[j]);
        }
    }
}
