#include <stdio.h>

static char *itoa(int value, char *str, int base)
{
    // Check for invalid input
    if (base < 2 || base > 36) {
        fprintf(stderr, "Error: Invalid base\n");
        return NULL;
    }

    // Handle negative values
    int isNegative = value < 0;
    if (isNegative) {
        value *= -1;
    }

    // Construct the string from least significant digit to most significant digit
    char buffer[32];
    int i = 0;
    do {
        buffer[i++] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[value % base];
        value /= base;
    } while (value > 0);

    // Add a negative sign if necessary
    if (isNegative) {
        buffer[i++] = '-';
    }

    // Reverse the string and copy it to the output buffer
    int j = 0;
    while (i > 0) {
        str[j++] = buffer[--i];
    }
    str[j] = '\0';

    return str;
}

