#include <GL/glew.h>
#include <GLFW/glfw3.h>

void readPixelsAndVerify(int width, int height, unsigned char* pixels, GLenum format, GLenum type) {
    // Initialize the framebuffer
    glBindFramebuffer(GL_FRAMEBUFFER, 0);
    
    // Clear the buffer bits
    glClearColor(1.0f, 1.0f, 1.0f, 1.0f);
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
    
    // Read the pixels from the framebuffer
    glReadPixels(0, 0, width, height, format, type, pixels);
    
    // Verify that the result matches the expected output
    const int kBytesPerPixel = 4;
    unsigned char* expected_pixels = new unsigned char[width * height * kBytesPerPixel];
    for (int i = 0; i < width * height * kBytesPerPixel; ++i) {
        expected_pixels[i] = static_cast<unsigned char>(1);
    }
    
    EXPECT_EQ(0, memcmp(expected_pixels, pixels, width * height * kBytesPerPixel));
}

