#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>

// Data structure for storing information in different formats.
struct Data {
	std::string xml;
	std::string binary;
	std::string collada;
};

// Function to save the data in three different formats.
void saveData(const std::vector<Data>& data, const std::string& filename) {
	// Open a file stream for writing in binary mode.
	std::ofstream outFileStream(filename, std::ios::binary);

	// Check if the file was opened successfully.
	if (!outFileStream.is_open()) {
		std::cout << "Error: Unable to open file " << filename << " for writing." << std::endl;
		return;
	}

	// Save the data in XML format.
	outFileStream << "<data>" << std::endl;
	for (const auto& item : data) {
		outFileStream << "\t<item>" << std::endl;
		outFileStream << "\t\t<xml>" << item.xml << "</xml>" << std::endl;
		outFileStream << "\t\t<binary>" << item.binary << "</binary>" << std::endl;
		outFileStream << "\t\t<collada>" << item.collada << "</collada>" << std::endl;
		outFileStream << "\t</item>" << std::endl;
	}
	outFileStream << "</data>" << std::endl;

	// Save the data in binary format.
	for (const auto& item : data) {
		outFileStream.write(reinterpret_cast<const char*>(&item), sizeof(Data));
	}

	// Save the data in COLLADA Physics 1.4.1 format.
	std::string collada;
	for (const auto& item : data) {
		collada += "<data>";
		collada += "\t<item>";
		collada += "\t\t<xml>" + item.xml + "</xml>";
		collada += "\t\t<binary>" + item.binary + "</binary>";
		collada += "\t\t<collada>" + item.collada + "</collada>";
		collada += "\t</item>";
		collada += "</data>";
	}
	outFileStream << collada;

	// Close the file stream.
	outFileStream.close();

	std::cout << "Data saved to file " << filename << " in XML, binary, and COLLADA Physics 1.4.1 formats." << std::endl;
}

int main() {
	// Initialize the data structure.
	std::vector<Data> data = { {"XML", "Binary", "COLLADA"} };

