class TCPServer {
private:
	int port;
	std::queue<std::string> messageQueue;
	std::mutex mtx;
public:
	TCPServer(int port) : port(port) {}
	void start() {
		while (true) {
			std::cout << "Waiting for incoming connections..." << std::endl;
			int sfd = socket_create(port);
			if (sfd < 0) {
				perror("socket_create()");
				continue;
			}

			struct sockaddr_in saddr;
			socklen_t addrlen = sizeof(saddr);
			int client_fd = accept(sfd, (struct sockaddr*)&saddr, &addrlen);
			if (client_fd < 0) {
				perror("accept()");
				socket_close(sfd);
				continue;
			}

			std::cout << "Connection established!" << std::endl;
			handle_connection(client_fd, saddr.sin_addr);
			socket_close(client_fd);
			socket_close(sfd);
		}
	}

private:
	void handle_connection(int client_fd, std::string ip) {
		while (true) {
			std::cout << "Waiting for incoming messages..." << std::endl;
			char buffer[1024];
			int n = recv(client_fd, buffer, sizeof(buffer), 0);
			if (n < 0) {
				perror("recv()");
				break;
			}

			std::cout << "Received message: " << std::string(buffer, n) << std::endl;
			mtx.lock();
			messageQueue.push(std::string(buffer, n));
			mtx.unlock();
		}
	}
