#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to generate an SQL INSERT command by concatenating strings.
char* gen_insert_cmd(const char* table_name, const char* geom_col_name,
                     const char* fid_col_name, int num_fields, ...)
{
    // Allocate memory for the SQL command string
    char* cmd = (char*)malloc(1024);

    // Initialize the SQL command string with the INSERT INTO clause
    sprintf(cmd, "INSERT INTO %s(", table_name);

    // Add the geometry column name if provided
    if (geom_col_name != NULL)
        strcat(cmd, geom_col_name);

    // Add the FID column name if provided
    if (fid_col_name != NULL)
    {
        if (geom_col_name != NULL)
            strcat(cmd, ",");
        strcat(cmd, fid_col_name);
    }

    // Add the field names and values to the SQL command string
    va_list fields;
    va_start(fields, num_fields);
    for (int i = 0; i < num_fields; i++)
    {
        const char* field_name = va_arg(fields, const char*);
        const char* field_value = va_arg(fields, const char*);
        if (!field_name || !field_value)
            continue;
        strcat(cmd, ",");
        strcat(cmd, field_name);
        strcat(cmd, "=");
        strcat(cmd, field_value);
    }
    va_end(fields);

    // Add the closing parentheses to the SQL command string
    strcat(cmd, ") VALUES (");
    for (int i = 0; i < num_fields; i++)
        strcat(cmd, "?,");
    cmd[strlen(cmd) - 1] = ')';

    return cmd;
}

