#include <cstdlib>
#include <cstring>

size_t triggerAccessViolation(char* mem) {
    // Allocate memory dynamically and set it to a known value.
    char *alloc = new char[4096];
    ::memset(alloc, 0, 4096);

    // Find the beginning of a page in the allocation.
    char* page_start = reinterpret_cast<char*>(((reinterpret_cast<uintptr_t>(alloc) + 4095) / 4096) * 4096);

    // Protect the page so that memcmp will produce an access violation when reading from it.
    DWORD oldProtect;
    if (!VirtualProtect(page_start, 4096, PAGE_READONLY, &oldProtect)) {
        return -1;
    }

    // Attempt to compare the memory to a different value using memcmp.
    size_t bytesRead = memcmp(mem, page_start, 4096);

    // Restore the original protection of the page.
    if (!VirtualProtect(page_start, 4096, oldProtect, &oldProtect)) {
        return -1;
    }

    return bytesRead;
}

