std::vector<std::vector<uint8_t>> loadDescriptors(const std::vector<std::string>& filePaths, bool includeAlpha) {
	std::vector<std::vector<uint8_t>> descriptors;

	for (const auto& filePath : filePaths) {
		// Open the training file and read its contents
		std::ifstream file(filePath);
		std::stringstream buffer;
		buffer << file.rdbuf();
		std::string contents = buffer.str();

		// Split the contents of the file into lines
		std::vector<std::string> lines = split(contents, "\n");

		for (const auto& line : lines) {
			// Split the line into tokens based on whitespace characters
			std::vector<std::string> tokens = split(line, " \t\r\n");

			if (tokens.size() != 2 && !includeAlpha) {
				continue;
			}

			// Convert the token to a uint8_t value and store it in the descriptors matrix
			std::vector<uint8_t> descriptor(tokens.size());
			for (int i = 0; i < tokens.size(); ++i) {
				descriptor[i] = static_cast<uint8_t>(std::stoi(tokens[i]));
			}
			descriptors.push_back(descriptor);
		}
	}

	return descriptors;
}

// Function to split a string into tokens based on a delimiter character
std::vector<std::string> split(const std::string& str, const char* delim) {
	std::vector<std::string> tokens;
	char *token = NULL;
	char *strCopy = new char[str.length() + 1];
	strcpy(strCopy, str.c_str());

	// Split the string into tokens based on the delimiter character
