```c
#include <stdio.h>
#include <stdlib.h>
#define MAX_NODES 100

int buildGraph(char** edges, int numEdges) {
    // Initialize graph with all nodes disconnected
    int adjMatrix[MAX_NODES][MAX_NODES] = {{0}};

    for (int i = 0; i < numEdges; ++i) {
        char* edge = edges[i];
        int src = edge[0] - 'A';
        int dest = edge[2] - 'A';
        adjMatrix[src][dest] = 1;
    }

    // Mark all nodes as unvisited
    bool visited[MAX_NODES] = {false};

    // Count connected components
    int numComponents = 0;
    for (int i = 0; i < MAX_NODES; ++i) {
        if (!visited[i]) {
            numComponents++;
            dfs(&adjMatrix, visited, i);
        }
    }

    return numComponents;
}

void dfs(int adjMatrix[][MAX_NODES], bool* visited, int node) {
    // Mark current node as visited
    visited[node] = true;

    // Recursively visit all unvisited neighbors
    for (int i = 0; i < MAX_NODES; ++i) {
        if (!visited[i] && adjMatrix[node][i]) {
            dfs(adjMatrix, visited, i);
        }
    }
}
