// Function to convert a HostAddress object to a string representation of the IP address.
std::string host_address_to_string(const HostAddress& address) {
    if (address.isV6()) {  // Check if the address is an IPv6 address
        if (address.isValid()) {  // Check if the address is valid
            std::string qs;
            qs.append("[");
            for (int i = 0; i < 8; ++i) {
                qs.append(std::to_string(ntohs(address.shorts[i])));
                if (i != 7) {
                    qs.append(":");
                }
            }
            qs.append("]");

            return qs;
        } else {  // Invalid address, return empty string
            return "";
        }
    } else {  // IPv4 address
        uint32_t ipv4 = ntohl(address.hash[3]);  // Convert to big-endian format
        std::string qs;
        for (int i = 0; i < 4; ++i) {
            qs.append(std::to_string((ipv4 >> (24 - i * 8)) & 0xFF));
            if (i != 3) {
                qs.append(".");
            }
        }
        return qs;
    }
}
