#include <iostream>
#include <random>
using namespace std;

class DynamicEmbeddingLayer {
private:
    int embedding_size;
    int label_width;
    int num_label_types;
    float* trainable_weights;
public:
    DynamicEmbeddingLayer(int embedding_size, int label_width, int num_label_types) : embedding_size(embedding_size), label_width(label_width), num_label_types(num_label_types) {
        trainable_weights = new float[embedding_size * label_width * num_label_types];
        for (int i = 0; i < embedding_size * label_width * num_label_types; i++) {
            trainable_weights[i] = 0;
        }
    }
    
    float* init_trainable_weights(float stddev) {
        random_device rd;
        mt19937 gen(rd());
        uniform_real_distribution<> dis(-stddev, stddev);
        for (int i = 0; i < embedding_size * label_width * num_label_types; i++) {
            trainable_weights[i] = dis(gen);
        }
        return trainable_weights;
    }
};

int main() {
    int embedding_size = 100;
    int label_width = 50;
    int num_label_types = 10;
    DynamicEmbeddingLayer layer(embedding_size, label_width, num_label_types);
    float* trainable_weights = layer.init_trainable_weights(0.1f);
    for (int i = 0; i < embedding_size * label_width * num_label_types; i++) {
        cout << trainable_weights[i] << " ";
    }
    return 0;
}

