int getUniqueIdentifier(int x, int y, int rows, int cols) {
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dis(0, 1);

    if (x < 0 || x >= cols || y < 0 || y >= rows) return -1;

