#include <iostream>
#include <vector>
#include <string>

int extractTokens(std::string buffer, std::string delimiter, std::vector<std::string> &tokens) {
    // Initialize variables
    int num_tokens = 0;
    size_t start = 0;
    size_t end = 0;

    // Iterate over the buffer and extract tokens
    while (start != std::string::npos) {
        // Find the next token in the buffer
        start = buffer.find(delimiter);
        
        // If a token is found, add it to the list of tokens
        if (start != std::string::npos) {
            end = start - 1;
            tokens.push_back(buffer.substr(0, end));
            buffer = buffer.substr(end + 1);
            num_tokens++;
        }
    }

    return num_tokens;
}

int main() {
    // Test the function with a sample input
    std::string buffer = "this is a test string";
    std::string delimiter = " ";
    std::vector<std::string> tokens;
    int num_tokens = extractTokens(buffer, delimiter, tokens);
    
    // Print the number of tokens and the list of tokens
    std::cout << "Number of tokens: " << num_tokens << std::endl;
    for (int i = 0; i < num_tokens; i++) {
        std::cout << "Token " << i + 1 << ": " << tokens[i] << std::endl;
    }
    
    return 0;
}

