            vfIncluded[i] = true;
            if (nTotal >= nTargetValue) {
                fReachedTarget = true;
                if (nTotal < nBest) {
                    nBest = nTotal;
                    vfBest = vfIncluded;
                }
                nTotal -= vValue[i];
                vfIncluded[i] = false;
            }
        }
    }
    
