#include <vector>

std::vector<std::string> get_files_in_directory(const std::string& directory_path, const bool sort = false)
{
    WIN32_FIND_DATA find_data;
    HANDLE hFind;

    // Check if the path is empty or not
    int len = directory_path.length();
    if (len == 0) {
        return {};
    }

    // Add a trailing backslash to the path if it doesn't have one already
    std::string bufname = directory_path + "\\";

    hFind = FindFirstFileA(bufname.c_str(), &find_data);
    if (hFind == INVALID_HANDLE_VALUE) {
        return {};
    }

    std::vector<std::string> file_list;
    do {
        // Check if the current entry is a file or not
        if ((find_data.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) == 0) {
            file_list.push_back(find_data.cFileName);
        }
    } while (FindNextFileA(hFind, &find_data));

    // Close the handle to the search directory
    FindClose(hFind);

    if (sort) {
        std::sort(file_list.begin(), file_list.end());
    }

    return file_list;
}

