bool is_certificate_valid(const ParsedCertificate* certificate, const ParsedCertificate* issuer_certificate) {
  const EVP_MD* type = nullptr;
  switch (id.hash_algorithm) {
    case DigestAlgorithm::Md2:
    case DigestAlgorithm::Md4:
    case DigestAlgorithm::Md5:
      // Unsupported.
      return false;
    case DigestAlgorithm::Sha1:
      type = EVP_sha1();
      break;
    case DigestAlgorithm::Sha256:
      type = EVP_sha256();
      break;
    case DigestAlgorithm::Sha384:
      type = EVP_sha384();
      break;
    case DigestAlgorithm::Sha512:
      type = EVP_sha512();
  }

  if (type == nullptr) {
    // Hash algorithm not supported.
    return false;
  }

  unsigned char* cert_hash = NULL;
  int hash_len = 0;
  if (!EVP_Digest(certificate->data, certificate->length, cert_hash, &hash_len, type, NULL)) {
    // Error computing hash.
    return false;
  }

  unsigned char* issuer_hash = NULL;
  int issuer_hash_len = 0;
  if (!EVP_Digest(issuer_certificate->data, issuer_certificate->length, issuer_hash, &issuer_hash_len, type, NULL)) {
    // Error computing hash.
    return false;
  }

  if (memcmp(cert_hash, issuer_hash, hash_len) != 0) {
    // Hashes do not match.
    return false;
  }

  // Hashes match. Certificate is valid.
  return true;
}

