#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <locale.h>

char *read_file(const char *path) {
    // Check if the file exists and is readable
    struct stat st;
    if (stat(path, &st) != 0 || !S_ISREG(st.st_mode)) {
        return NULL;
    }

    // Open the file
    FILE *fp = fopen(path, "r");
    if (!fp) {
        return NULL;
    }

    // Determine the length of the file
    fseek(fp, 0, SEEK_END);
    long len = ftell(fp);
    rewind(fp);

    // Allocate memory for the contents of the file
    char *contents = malloc((len + 1) * sizeof(char));
    if (!contents) {
        fclose(fp);
        return NULL;
    }

    // Read the contents of the file into the allocated memory
    size_t read = fread(contents, sizeof(char), len, fp);
    if (read < 0) {
        free(contents);
        fclose(fp);
        return NULL;
    }

    // Null-terminate the string and close the file
    contents[len] = '\0';
    fclose(fp);

    return contents;
}

int main() {
    char *contents = read_file("test.txt");
    if (contents) {
        printf("%s", contents);
        free(contents);
    } else {
        perror("Error reading file");
    }
    return 0;
}

