const char *TOKEN_DELIMS = " ,\n";

// Function to parse a multiline string and extract a list of tokens
char **parse_tokens(const char *str, size_t *num_tokens) {
    // Allocate memory for the token list
    char **token_list = malloc(sizeof(char *) * strlen(str));
    if (!token_list) {
        return NULL;
    }

    // Initialize variables for parsing
    const char *l_ptr = str;
    bool l_error = false;
    size_t l_count = 0;
    char *l_tok = NULL;
    char *l_last_tok = NULL;

    while ((!l_error) && (l_tok != NULL)) {
        // Skip leading whitespace
        while (isspace(*l_ptr)) {
            l_ptr++;
        }

        // Check if we have reached the end of the string
        if (*l_ptr == '\0') {
            break;
        }

        // Get the next token
        l_tok = strtok(l_ptr, TOKEN_DELIMS);
        if (l_tok != NULL) {
            // Check if the token is a digit or minus sign
            if ((isdigit(*l_tok) || (*l_tok == '-')) && !isspace(*l_last_tok)) {
                // Add the token to the list
                token_list[l_count++] = l_tok;
            } else if (*l_tok == '"') {
                // Handle quoted strings
                l_ptr += strlen(l_tok) + 1;
            } else if (*l_tok == ',') {
                // Handle commas
                l_ptr++;
            } else {
                // Ignore other tokens
                continue;
            }
        }
    }

    *num_tokens = l_count;
    return token_list;
}
