#include <string>
#include <tuple>

std::tuple<std::string, std::string> parse_and_validate_server_name(const std::string& server_name) {
    // Split the server name into host and port parts
    size_t colon_pos = server_name.find(':');
    if (colon_pos == std::string::npos) {
        return {server_name, ""};
    }

    std::string host = server_name.substr(0, colon_pos);
    std::string port = server_name.substr(colon_pos + 1);

    // Validate the host part of the server name
    if (host[0] == '[' && host[-1] != ']') {
        throw std::invalid_argument("Mismatched [...] in server name");
    }

    // Validate the port part of the server name
    char* endptr;
    long port_num = strtol(port.c_str(), &endptr, 10);
    if (*endptr != '\0' || port_num < 1 || port_num > 65535) {
        throw std::invalid_argument("Invalid server name");
    }

    return {host, port};
}

int main() {
    // Example usage of the parse_and_validate_server_name function
    try {
        auto [host, port] = parse_and_validate_server_name("localhost:80");
        std::cout << "Host: " << host << ", Port: " << port << '\n';
    } catch (const std::invalid_argument& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }

    return 0;
}

