#include <iostream>
#include <string>
using namespace std;

struct Option {
    string name;
    string value;
};

void parse_kv(string input, vector<Option> &options) {
    size_t pos = 0;
    while (pos != string::npos) {
        // find the next comma
        pos = input.find(',', pos);
        if (pos == string::npos)
            break;
        // get the key-value pair before the next comma
        string pair = input.substr(0, pos);
        // split the pair into two parts based on the equal sign
        size_t eq_pos = pair.find('=');
        if (eq_pos == string::npos) {
            cout << "Error: malformed key-value pair" << endl;
            return;
        }
        string key = pair.substr(0, eq_pos);
        string value = pair.substr(eq_pos + 1);
        // add the option to the vector
        Option opt;
        opt.name = key;
        opt.value = value;
        options.push_back(opt);
        // move past the comma and start searching for the next pair
        pos++;
    }
}

