void initOpenGLApplication(const char* title, int majorVersion, int minorVersion) {
  // Set the OpenGL version to be used by the application
  glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, majorVersion);
  glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, minorVersion);
  
  // Create a window and its context using GLFW
  GLFWwindow* window = glfwCreateWindow(640, 480, title, NULL, NULL);
  if (!window) {
    std::cout << "Failed to create GLFW window" << std::endl;
    glfwTerminate();
    return;
  }

  // Make the context current and set up OpenGL function pointers
  glfwMakeContextCurrent(window);
  if (!gladLoadGLLoader((GLADloadproc)glfwGetProcAddress)) {
    std::cout << "Failed to initialize GLAD" << std::endl;
    return;
  }

  // Set the clear color and depth value for the screen
  glClearColor(0.2f, 0.2f, 0.2f, 0.0f);
  glClearDepth(1.0f);
}

