#include <cstdlib>
#include <iostream>

using namespace std;

float** allocate2DArray(int lLBytes, int height)
{
	// Allocate memory for the 2D array
	float **array = new float*[lLBytes];
	for (int i = 0; i < lLBytes; ++i) {
		array[i] = new float[height];
	}
	return array;
}

void computeDifferences(float **array, int lLBytes, int height)
{
	// Compute differences between neighboring elements in the array for all possible directions (N, S, W, E, NE, SE, SW, NW) using standard library functions.
	for (int i = 1; i < lLBytes - 1; ++i) {
		for (int j = 1; j < height - 1; ++j) {
			array[i][j] = array[i-1][j-1] + array[i-1][j+1] + array[i+1][j-1] + array[i+1][j+1] - 4 * array[i][j];
		}
	}
}

