void linearRegression(const vector<double>& x, const vector<double>& y) {
	// Calculate the sum of the x and y values
	double sumX = 0;
	double sumY = 0;
	for (int i = 0; i < x.size(); i++) {
		sumX += x[i];
		sumY += y[i];
	}

