    memcpy(output, buffer, fullness);
    output[fullness] = '\0';

    return output;
}

int IsTimeout(struct timeval start_time, int read_timeout, int total_timeout) {
    struct timeval current_time;
    gettimeofday(&current_time, NULL);

    long seconds = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_usec - start_time.tv_usec) / 1000000;

    return read_timeout <= seconds || total_timeout <= seconds;
}
