int* reduce_list(int *input, int length, int (*comp)(const void*, const void*)) {
    // allocate memory for the resulting list
    int* output = malloc(length * sizeof(int));

    // create a set to keep track of unique entries
    int* set = malloc((length + 1) * sizeof(int));
    int* next_free = &set[0];

    for (int i = 0; i < length; i++) {
        // check if the current entry is already in the set
        int found = 0;
        for (int j = 0; j < *next_free && !found; j++) {
            if (comp(&input[i], &set[j]) == 0) {
                found = 1;
            }
        }

        // if the entry is not in the set, add it to the output list and the set
        if (!found) {
            *next_free++ = input[i];
            output[*next_free - 1] = i;
        }
    }

    // sort the output list using the provided comparison function
    qsort(output, length, sizeof(int), comp);

    // free memory for the set and return the number of unique entries
    free(set);
    return output;
}

