};

class Filter {
public:
    Filter(int num_candidate_blocks, int ola_window_size, int ola_hop_size, int channels)
        : _num_candidate_blocks(num_candidate_blocks),
          _ola_window_size(ola_window_size),
          _ola_hop_size(ola_hop_size),
          _channels(channels) {}

    unique_ptr<AudioBus> createFilters() {
        // Create and initialize the filters.
