#include <iostream>
#include <thread>
#include <vector>
#include <algorithm>
#include <functional>

struct Color {
    int r;
    int g;
    int b;
};

class Camera {
public:
    unsigned int GetWidth() { return width; }
    unsigned int GetHeight() { return height; }
    Color GetPixelColor(unsigned int x, unsigned int y) { return {x * 256 / width, y * 256 / height, (x + y) * 128 / (width + height)}; }
private:
    unsigned int width = 1024;
    unsigned int height = 768;
};

class View {
public:
    std::pair<unsigned int, unsigned int> GetResolution() { return resolution; }
    Color GetPixelColor(unsigned int x, unsigned int y) { return {x * 256 / resolution.first, y * 256 / resolution.second, (x + y) * 128 / (resolution.first + resolution.second)}; }
private:
    std::pair<unsigned int, unsigned int> resolution = {1024, 768};
};

class ThreadPool {
public:
    ThreadPool(unsigned int num_threads) : pool_(num_threads) {}
    void AddTask(std::function<void()> task) { tasks_.push_back(task); }
    void WaitAll() {
        for (auto& thread : pool_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }
private:
    std::vector<std::thread> pool_;
    std::vector<std::function<void()>> tasks_;
};

class Renderer {
public:
    void Render(Camera* camera, View* view) {
        ThreadPool pool(std::thread::hardware_concurrency());
        Color* matrix = new Color[view->GetResolution().second * view->GetResolution().first];
        for (unsigned int x = 0; x < camera->GetWidth(); ++x) {
            for (unsigned int y = 0; y < camera->GetHeight(); ++y) {
                pool.AddTask([this, x, y]() { RenderPixelTask(x, y); });
            }
        }
        pool.WaitAll();
        std::cout << "Rendering completed" << std::endl;
    }
