        unsigned int sum = 0;
        if (x > 0) {
            sum += c.r * power;
        }
        if (y > 0) {
            sum += c.g * power;
        }
        matrix_[x + y * view_->GetResolution().first] = {sum, sum / 2, sum / 3};
    }

    Camera* camera_;
    View* view_;
    Color* matrix_;
};

