                values.push_back(static_cast<int32_t>(rand() % 100));
            break;
        case MatrixElementTypes.Float:
            for (int i = 0; i < rows * cols; ++i)
                values.push_back(static_cast<float>(rand() % 100));
            break;
        case MatrixElementTypes.Double:
            for (int i = 0; i < rows * cols; ++i)
                values.push_back(static_cast<double>(rand() % 100));
            break;
        default:
            throw std::invalid_argument("Invalid matrix element type");
    }
    return Matrix<T>(values, rows, cols);
}
