						i != queue.end(); ++i)
					{
						cached_piece_info* cp = 0;
						std::vector<cached_piece_info>::iterator cpi = std::find_if(pieces.begin(), pieces.end()
							, bind(&cached_piece_info::piece, _1) == i->piece_index);
						if (cpi != pieces.end()) cp = &*cpi;

						out << to_string(i->piece_index, 4) << ": [";
