// Function to parse a binary file and extract the number of blocks and their indices
int parse_binary_file(char *filename, int **indices) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) return -1;

    // Read the first line of the file to get the number of blocks
    char *line = malloc(256);
    if (fgets(line, 256, fp) == NULL) {
        free(line);
        fclose(fp);
        return -1;
    }
    int num_blocks = atoi(line);

    // Allocate memory for the indices array
    *indices = malloc(num_blocks * sizeof(int));
    if (*indices == NULL) {
        free(line);
        fclose(fp);
        return -2;
    }

    // Read each line of the file and extract the block indices
    int i, index;
    for (i = 0; i < num_blocks; i++) {
        if (fscanf(fp, "%d", &index) != 1) break;
        (*indices)[i] = index;
    }

    // Check for errors in the malloc call and return -2 if there is an error
    if (ferror(fp)) {
        free(*indices);
        fclose(fp);
        return -2;
    }

    // Close the file and return the number of blocks
    fclose(fp);
    return num_blocks;
}
