// Function to apply Gaussian filter to an image represented as a 2D array of uchar pixels
void gaussian_filter(const std::vector<std::vector<uchar>>& input, std::vector<std::vector<uchar>>& output,
                     const float coef[][3], int size_x, int size_y, int width, int height) {
    // Initialize the output image with zeros
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            output[i][j] = 0;
        }
    }
    
    // Apply the Gaussian filter to each pixel in the image
    for (int i = size_y/2; i < height - size_y/2; ++i) {
        for (int j = size_x/2; j < width - size_x/2; ++j) {
            float sum = 0;
            for (int k = -size_y/2; k <= size_y/2; ++k) {
                for (int l = -size_x/2; l <= size_x/2; ++l) {
                    int m = i + k, n = j + l;
                    sum += input[m][n] * coef[k+size_y/2][l+size_x/2];
                }
            }
            output[i][j] = round(sum);
        }
    }
}

