#include <utility>

template <typename... T>
class variant {
public:
    variant() : type_index_(0), data_(nullptr) {}

    template <typename V>
    variant(V&& v) : type_index_(meta::index_of<V, T...>::value),
                     data_(new V(std::forward<V>(v))) {
        static_assert(type_index_ < n_elements,
            "type does not exist in variant");
    }

    ~variant() { delete_if_not_empty(); }

    template <typename V>
    variant& operator=(std::auto_ptr<V>&& rhs) {
        int const new_index = meta::index_of<V, T...>::value;
        static_assert(new_index < n_elements,
            "type does not exist in variant");

        delete_if_not_empty();
        type_index_ = new_index;
        data_ = rhs.release();
        return *this;
    }

    template <typename V>
    variant& operator=(V&& rhs) {
        int const new_index = meta::index_of<V, T...>::value;
        static_assert(new_index < n_elements,
            "type does not exist in variant");

        delete_if_not_empty();
        type_index_ = new_index;
        data_ = new V(std::forward<V>(rhs));
        return *this;
    }

private:
    void delete_if_not_empty() {
        if (data_) {
            delete reinterpret_cast<void*>(data_);
            data_ = nullptr;
        }
    }

    std::size_t type_index_;
    std::uintptr_t data_;
};

