typedef struct {
	uint16_t width;
	uint16_t height;
	uint8_t  bpp;
} Texture2DParams;

void* createTexture2D(const Texture2DParams& params, bool filtering, uint32_t flags) {
	// Allocate memory for the texture
	void* mem = malloc(params.width * params.height * params.bpp);
	if (!mem) return NULL;

	uint8_t* rgba = (uint8_t*)mem;

	// Fill the texture data with a charset filling function
	charsetFillTexture(vga8x8, rgba, 8, params.width * params.bpp, params.bpp);
	charsetFillTexture(vga8x16, &rgba[8 * params.width * params.bpp], 16, params.width * params.bpp, params.bpp);

	// Create a texture object using the memory and parameters
	return createTexture2D(params.width, params.height, filtering, flags, TextureFormat::R8,
		BGFX_TEXTURE_MIN_POINT | BGFX_TEXTURE_MAG_POINT | BGFX_TEXTURE_MIP_POINT
		| BGFX_TEXTURE_U_CLAMP | BGFX_TEXTURE_V_CLAMP);
}

void* charsetFillTexture(const void* data, uint8_t* rgba, int width, int height, int bpp) {
	// Fill the texture data with the given character set
	for (int i = 0; i < width * height * bpp; ++i) {
		rgba[i] = ((uint8_t*)data)[i];
