#include <stdbool.h>
#include <string.h>
#include <stdio.h>
#include <stdarg.h>

bool has_format_string(char* buffer, const char* format) {
    bool modified = false;
    if (buffer != NULL && format != NULL) {
        // Copy the contents of the buffer to an auxiliary buffer
        char *auxiliary_buffer = malloc(strlen(buffer) + 1);
        strcpy(auxiliary_buffer, buffer);

        // Compare the original buffer with the auxiliary buffer at the end to determine if the format string has been modified
        size_t len = strlen(buffer);
        for (size_t i = 0; i < len; i++) {
            if (buffer[i] != auxiliary_buffer[i]) {
                modified = true;
                break;
            }
        }

        // Free the auxiliary buffer
        free(auxiliary_buffer);
    } else {
        modified = false;
    }
    return modified;
}

