#include <ctime>
#include <vector>
using namespace std;

class LinearSolverInterface {
public:
    virtual void GiveMatrixToSolver(bool new_matrix, vector<vector<int>>& sym_A) = 0;
};

class ScalingFactorCalculator {
public:
    double scaling_factor;
    bool use_scaling;

    void CalculateScalingFactors(vector<double>& v, vector<int>& dim) {
        if (use_scaling) {
            scaling_factor = 1.0 / v[dim - 1];
        }
    }
};

class TimingStatisticsModule {
public:
    double LinearSystemScaling() {
        return rand() % 10 + 1;
    }
};

class IpData {
public:
    TimingStatisticsModule TimingStats;
    ScalingFactorCalculator ScalingFactors;
};

void SolveSystemOfLinearEquations(vector<vector<int>>& sym_A, vector<double>& rhsV, LinearSolverInterface* solver) {
    int dim = (int)rhsV.size();
    bool new_matrix = true;
    double scaling_factor;

    for (int irhs=0; irhs<dim; irhs++) {
        rhsV[irhs] *= IpData().ScalingFactors.scaling_factor;
    }

    if (new_matrix || IpData().ScalingFactors.use_scaling) {
        GiveMatrixToSolver(true, sym_A);
        new_matrix = true;
    }

    double time_taken = IpData().TimingStats.LinearSystemScaling();
    cout << "Time taken for scaling the matrix: " << time_taken << endl;
}

