#include <vector>
using namespace std;
bool checkOverlap(vector<pair<int, int>> memoryBlocks, pair<int, int> newMemoryBlock) {
    for (auto existingMemoryBlock : memoryBlocks) {
        // Check if the new memory block overlaps with any existing memory blocks
        if (!(newMemoryBlock.first + newMemoryBlock.second - 1 < existingMemoryBlock.first || existingMemoryBlock.first + existingMemoryBlock.second - 1 < newMemoryBlock.first)) {
            return false;
        }
    }
    return true;
}

bool allocateMemory(vector<pair<int, int>>& memoryBlocks, pair<int, int> newMemoryBlock) {
    // Check if the new memory block can be allocated without overlapping with any existing memory blocks
    if (!checkOverlap(memoryBlocks, newMemoryBlock)) {
        return false;
    }
    
    // Add the new memory block to the vector of memory blocks
    memoryBlocks.push_back(newMemoryBlock);
    return true;
}

