void split(list<int>& first, list<int>& second, const list<int>& sorted) {
	list<int>::iterator mid = sorted.begin();
	advance(mid, sorted.size() / 2);
	first.splice(first.end(), sorted, sorted.begin(), mid);
	second.splice(second.end(), sorted, mid, sorted.end());
}

