using UnityEngine;

public class GameObjectCreator : MonoBehaviour
{
    public static int count = 0;

    public GameObject[] materials;

    private float timeSinceLastSpawn = 0;
    private float spawnRate = 1f;

    void Update()
    {
        // Calculate the time since last spawn
        timeSinceLastSpawn += Time.deltaTime;

        // Check if it's time to spawn a new game object
        if (timeSinceLastSpawn > spawnRate)
        {
            count++;

            // Create a new instance of the game object and assign it a random position, rotation, and material
            GameObject newGameObject = Instantiate(gameObject, Random.insideUnitSphere * 10f, Quaternion.identity);
            newGameObject.transform.rotation = Random.rotation;
            newGameObject.GetComponent<MeshRenderer>().material = materials[Random.Range(0, materials.Length)];

            // Reset the timer and increment the count
            timeSinceLastSpawn = 0;
        }
    }
}

