#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <string>
using namespace std;

void addSite(string directoryPath, string siteName)
{
    // Check if a web.config file exists in the directory before adding the site.
    if (!fileExists(directoryPath + "/web.config")) {
        return nullptr;
    }

    // Start the website using the Process class and take the directory path and site name as inputs.
    Process process = new Process();
    process.StartInfo.FileName = "dotnet";
    process.StartInfo.Arguments = directoryPath + "/" + siteName + ".dll";
    process.StartInfo.UseShellExecute = false;
    process.StartInfo.RedirectStandardOutput = true;
    process.StartInfo.CreateNoWindow = true;
    process.Start();
}

bool fileExists(string path)
{
    ifstream infile(path);
    return infile.good();
}

