```csharp
using System;
using System.IO;
using System.Xml;

public static class FontLoader
{
    public static Font CreateFont(Device device, string fontName)
    {
        using (var stream = Assembly.GetManifestResourceStream("font.xml"))
        {
            var xmlDocument = new XmlDocument();
            xmlDocument.Load(stream);

            var rootElement = xmlDocument.DocumentElement;
            if (rootElement == null)
                throw new InvalidOperationException("Invalid XML file");

            var fontSizeElement = rootElement.SelectSingleNode("/Font/Size");
            int size = Convert.ToInt32(fontSizeElement.InnerText);

            var fontWidthElement = rootElement.SelectSingleNode("/Font/Width");
            int width = Convert.ToInt32(fontWidthElement.InnerText);

            var fontHeightElement = rootElement.SelectSingleNode("/Font/Height");
            int height = Convert.ToInt32(fontHeightElement.InnerText);

            return new Font(device, fontName, size, width, height);
        }
    }
}
