using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
#endregion

namespace PlumbingGrid {
    public class Tank {
        private int _id;
        private bool _isSink;
        private List<Tank> _outputs = new List<Tank>();
        private List<Tank> _inputs = new List<Tank>();
        
        public Tank(int id, bool isSink) {
            _id = id;
            _isSink = isSink;
        }
        
        public int Id { get => _id; set => _id = value; }
        public bool IsSink { get => _isSink; set => _isSink = value; }
        public List<Tank> Outputs { get => _outputs; set => _outputs = value; }
        public List<Tank> Inputs { get => _inputs; set => _inputs = value; }

        public void ConnectTo(Tank tank) {
            if (!_isSink && !tank.IsSink) {
                _outputs.Add(tank);
                tank._inputs.Add(this);
            }
        }
    }
}

namespace PlumbingGrid {
    public class Grid {
        private Tank[,] _board;
        
        public Grid(int width, int height) {
            _board = new Tank[width, height];
        }
        
        public void AddTank(Tank tank, int x, int y) {
            _board[x, y] = tank;
