namespace MSBuildExpander
{
    public static class ExpanderExtensions
    {
        /// <summary>
        /// Expands the specified string in-place, using the provided XmlAttribute as context.
        /// </summary>
        /// <param name="expander">The expander.</param>
        /// <param name="value">The value to expand.</param>
        /// <param name="xmlAttribute">The XML attribute used as context for expansion.</param>
        public static void ExpandInPlace(this Expander expander, string value, XmlAttribute xmlAttribute)
        {
            // If the input string is a literal, we don't want to use it. Instead, we create a new string with the same value as the input string. This ensures that neither the input string nor the expanded string are interned, which is important for this test.
            if (value == null)
            {
                value = String.Empty;
            }

            // Create a new string with the same value as the input string.
            var newValue = new StringBuilder(value);

            // Expand the string in-place using the provided XmlAttribute as context.
            expander.ExpandInPlaceLeaveEscaped(newValue, xmlAttribute);
        }
    }
}

