using System;
using System.IO;
using System.Diagnostics;

namespace FileEditor
{
    class Program
    {
        static void Main(string[] args)
        {
            if (args.Length != 1)
            {
                Console.WriteLine("Usage: FileEditor <file_path>");
                return;
            }

            string filePath = args[0];

            // Check if the file exists and is a valid path
            if (!File.Exists(filePath))
            {
                Console.WriteLine($"The file '{filePath}' does not exist.");
                return;
            }

            // Open the file in write mode to modify its contents
            using (StreamWriter writer = new StreamWriter(filePath, false))
            {
                // Modify the file's contents here
                writer.WriteLine("This is a modified version of the original file.");
            }

            // Open the file in read mode to display its contents
            using (StreamReader reader = new StreamReader(filePath))
            {
                Console.WriteLine(reader.ReadToEnd());
            }

            // Get the default associated application for the file type
            string appName = GetDefaultApplicationForFileType(Path.GetExtension(filePath));

            // Launch the default associated application to open the modified file
            ProcessStartInfo startInfo = new ProcessStartInfo()
            {
                FileName = appName,
                Arguments = filePath,
                UseShellExecute = true
            };
            Process.Start(startInfo);
        }

        private static string GetDefaultApplicationForFileType(string extension)
        {
            // Get the default associated application for the given file type from the registry
            using (RegistryKey key = Registry.ClassesRoot.OpenSubKey(extension))
            {
                return (string)key.GetValue("");
            }
        }
    }
}
