using System;
using System.Diagnostics;
using System.Threading.Tasks;

public static ProcessResult ExecuteProcessAsync(string fileName, string arguments, string workingDir)
{
    var p = new Process();

    // Redirect standard output to a stream that is read asynchronously
    p.StartInfo.UseShellExecute = false;
    p.StartInfo.RedirectStandardOutput = true;
    p.StartInfo.FileName = fileName;
    p.StartInfo.Arguments = arguments;
    p.StartInfo.WorkingDirectory = workingDir;
    p.Start();

    // Read standard output asynchronously
    using (var streamReader = new StreamReader(p.StandardOutput))
    {
        var outputTask = Task.Factory.StartNew(() => streamReader.ReadToEnd());
        var exitCodeTask = Task.Factory.StartNew(() => p.ExitCode);

        // Wait for the process to exit and read the standard output
        await Task.WhenAll(outputTask, exitCodeTask);

        return new ProcessResult(outputTask.Result, "", exitCodeTask.Result);
    }
}
