public class UpdateElementHtmlContentService
{
    private readonly IRepository _repository;

    public UpdateElementHtmlContentService(IRepository repository)
    {
        _repository = repository;
    }

    [HttpPut]
    public ActionResult Put(int pageSectionId, int elementId, string htmlContent)
    {
        var pageSection = _repository.GetPageSectionById(pageSectionId);
        var element = pageSection?.Elements?.FirstOrDefault(e => e.Id == elementId);

        if (element != null)
