using Microsoft.AspNetCore.Mvc;
using MyApp.Models;
using MyApp.Data;

namespace MyApp.Controllers
{
    public class PurchaseOrdersController : Controller
    {
        private readonly ApplicationDbContext _context;

        public PurchaseOrdersController(ApplicationDbContext context)
        {
            _context = context;
        }

        [HttpGet]
        [Route("purchase-orders/create")]
        [Authorization(Scope = "purchase-orders.edit")]
        public IActionResult Create()
        {
            return View();
        }

        [HttpPost]
        [Route("purchase-orders/create")]
        [Authorization(Scope = "purchase-orders.edit")]
        public IActionResult Create(CreatePurchaseOrderViewModel viewModel)
        {
            if (!_context.Stores.Any(s => s.Id == viewModel.StoreId))
            {
                return Error("Store not found.");
            }

            if (viewModel.WalletId == null)
            {
                return Error("Wallet ID is required.");
            }

            var purchaseOrder = new PurchaseOrder()
            {
                StoreId = viewModel.StoreId,
                WalletId = viewModel.WalletId,
                DateCreated = DateTime.Now,
                Status = "Pending",
            };

            _context.PurchaseOrders.Add(purchaseOrder);
            _context.SaveChanges();

            return View("~/Views/Inventory/PurchaseOrders/PurchaseOrderEdit.cshtml", purchaseOrder);
        }
    }
}

