﻿using System;
using System.Data;
using System.Data.Common;

namespace SqlCommandExecution
{
    public static class SqlExecutor
    {
        public static IDataReader ExecuteReader(string connectionString, CommandType cmdType, string cmdText, params IDbDataParameter[] commandParameters)
        {
            using (IDbConnection conn = DbFactory.CreateDbConnection(connectionString))
            {
                using (IDbCommand cmd = DbFactory.CreateDbCommand())
                {
                    try
                    {
                        PrepareCommand(cmd, conn, null, cmdType, cmdText, commandParameters);
                        return cmd.ExecuteReader(CommandBehavior.CloseConnection);
                    }
                    catch (Exception)
                    {
                        conn.Close();
                        cmd.Dispose();
                        throw;
                    }
                }
            }
        }

        private static void PrepareCommand(IDbCommand cmd, IDbConnection conn, IDbTransaction trans, CommandType cmdType, string cmdText, params IDbDataParameter[] commandParameters)
        {
            if (conn.State != ConnectionState.Open)
            {
                conn.Open();
            }

            cmd.CommandType = cmdType;
            cmd.CommandText = cmdText;

            if (commandParameters != null)
            {
                cmd.Parameters.AddRange(commandParameters);
            }
        }
    }
}

