using System;
using System.IO;
using System.Xml.Linq;
using System.Xml.XPath;

class ConfigFileUpdater
{
    private XDocument _xmlFile;

    public ConfigFileUpdater(XDocument xmlFile)
    {
        _xmlFile = xmlFile;
    }

    public XDocument UpdateXmlFile(string xpathToExistingSection, string newSectionXml, string xpathToInsertAfter)
    {
        var existingSectionNode = _xmlFile.XPathSelectElement(xpathToExistingSection);
        if (existingSectionNode == null)
        {
            throw new ArgumentException("The specified section does not exist in the configuration file.");
        }

        var newSectionNode = XDocument.Parse(newSectionXml).Root;
        existingSectionNode.AddAfterSelf(newSectionNode);

        return _xmlFile;
    }
}
