private List<TravelItem> GetGeocacheCoordinatesFromHtml(string htmlFilePath)
{
    var travelItems = new List<TravelItem>();

    // Read HTML file from embedded resource
    Assembly assembly = Assembly.GetExecutingAssembly();
    using (StreamReader textStreamReader = new StreamReader(assembly.GetManifestResourceStream(htmlFilePath)))
    {
        string htmlContent = textStreamReader.ReadToEnd();

        // Parse HTML to extract geocache coordinates
        var doc = new HtmlAgilityPack.HtmlDocument();
        doc.LoadHtml(htmlContent);
        var nodes = doc.DocumentNode.SelectNodes("//*[@class='gc-coord']");
        foreach (var node in nodes)
        {
            var geocacheCode = node.Attributes["data-gc"].Value;
            var lat = double.Parse(node.Attributes["data-lat"].Value);
            var lon = double.Parse(node.Attributes["data-lon"].Value);

            travelItems.Add(new TravelItem()
            {
                GeocacheCode = geocacheCode,
                Lat = lat,
                Lon = lon
            });
        }
    }

    return travelItems;
}

