using System.Data;
using System.Collections.Generic;
namespace CodeSamples
{
    public class SqlParameterization
    {
        private string _connectionString;
        private IDbConnection _dbConnection;
        private string _sqlCommand;
        private Dictionary<string, object> _parameters;
        public IDataReader Query(List<object> values, string connectionString, string sqlCommand)
        {
            InitializeMembers(values, connectionString, sqlCommand);
            return ExecuteQuery();
        }
        private void InitializeMembers(List<object> values, string connectionString, string sqlCommand)
        {
            _parameters = new Dictionary<string, object>();
            for (int i = 0; i < values.Count; i++)
            {
                _parameters.Add($"@Param{i}", values[i]);
            }
            _connectionString = connectionString;
            _sqlCommand = sqlCommand;
        }
        private IDataReader ExecuteQuery()
        {
            using (_dbConnection = new SqlConnection(_connectionString))
            {
                _dbConnection.Open();
                SqlCommand dbcommand = new SqlCommand(_sqlCommand, _dbConnection);
                foreach (KeyValuePair<string, object> param in _parameters)
                {
                    dbcommand.Parameters.AddWithValue(param.Key, param.Value).DbType = DbType.String;
                }
                return dbcommand.ExecuteReader();
            }
        }
    }
}

