CREATE PROCEDURE CreateQueueAndService(@queueName VARCHAR(50), @serviceName VARCHAR(50))
AS
BEGIN
    -- Check if queue already exists
    IF NOT EXISTS (SELECT * FROM sys.objects WHERE name = @queueName AND type = 'U')
        CREATE QUEUE [dbo].[@queueName] WITH STATUS = ON;

    -- Check if service already exists
    IF NOT EXISTS (SELECT * FROM sys.services WHERE name = @serviceName)
        CREATE SERVICE [dbo].[@serviceName] ON QUEUE [dbo].[@queueName];

    -- Subscribe service to PostQueryNotification on queue
    EXEC sp_postqueuenotification [dbo].[@queueName], 'INSERT, UPDATE, DELETE';
END;

