using System;
using System.Collections.Generic;
using System.Xml;

public class Configuration {
    private Dictionary<string, string> _config = new Dictionary<string, string>();

    public Configuration(string configFile) {
        XmlDocument doc = new XmlDocument();
        try {
            doc.Load("file://" + configFile);
        } catch (XmlException e) {
            throw new ConfigurationException("XML Syntax error in: " + configFile, e);
        }

        //build tokens
        XmlNode tokensNode = doc.SelectSingleNode("//tokens");
        if (tokensNode == null) {
            throw new ConfigurationException("No tokens supplied!");
        }
        XmlNodeList tokenNodeList = tokensNode.SelectNodes("./token");

        foreach (XmlNode token in tokenNodeList) {
            string key = token.Attributes["name"].Value;
            string value = token.InnerText;
            _config[key] = value;
        }
    }

    public string GetSetting(string key) {
        try {
            return _config[key];
        } catch (KeyNotFoundException) {
            return null;
        }
    }
}
