public static void ExecuteExternalCommand()
{
    // Use Process class to execute external command-line utility
    Process p = new Process();
    p.StartInfo.UseShellExecute = false;
    p.StartInfo.RedirectStandardOutput = true;
    p.StartInfo.FileName = "externalCommand.exe";
    p.StartInfo.CreateNoWindow = true;
    p.StartInfo.Arguments = "-param1 -param2";
    p.Start();

    // Redirect standard input, output, and error streams
    using (StreamWriter sw = new StreamWriter(p.StandardInput.BaseStream))
    {
        sw.WriteLine("This is the standard input stream");
    }

    using (StreamReader sr = new StreamReader(p.StandardOutput.BaseStream))
    {
        string output = sr.ReadToEnd();
        Console.WriteLine("Standard Output: " + output);
    }

    // Wait for the utility to exit before checking its exit code and throwing an exception if necessary
    p.WaitForExit();

    if (p.ExitCode != 0)
    {
        throw new Exception($"External command failed with exit code {p.ExitCode}");
    }
}

