                new Resource { MimeType = "image/png", Data = File.ReadAllBytes("path/to/file.png") }
            };
            var hashedResources = ComputeMd5Hash(resources);
        }

        static List<Resource> ComputeMd5Hash(List<Resource> resources)
        {
            var hashedResources = new List<Resource>();
            foreach (var resource in resources)
            {
                using (var md5 = MD5.Create())
                {
                    var hashBytes = md5.ComputeHash(resource.Data);
                    var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
                    resource.Hash = hashString;
                }
                hashedResources.Add(resource);
            }
            return hashedResources;
        }
    }

    class Resource
    {
        public string MimeType { get; set; }
        public byte[] Data { get; set; }
        public string Hash { get; set; }
    }
}

