using System;
using System.Diagnostics;
using System.Threading.Tasks;

public class ProcessExecutor
{
    public static ProcessResult ExecuteProcess(string fileName, string arguments = null, string workingDir = null)
    {
        var p = new Process();
        p.StartInfo.UseShellExecute = false;
        p.StartInfo.RedirectStandardOutput = true;
        if (arguments != null) { p.StartInfo.Arguments = arguments; }
        if (workingDir != null) { p.StartInfo.WorkingDirectory = workingDir; }

        var outputReaderTask = Task.Factory.StartNew(() => p.StandardOutput.ReadToEnd());
        var errorReaderTask = Task.Factory.StartNew(() => p.StandardError.ReadToEnd());
        var processWaiterTask = Task.Factory.StartNew(() => p.WaitForExit());

        Task.WaitAll(outputReaderTask, errorReaderTask, processWaiterTask);

        if (p.ExitCode != 0)
        {
            throw new Exception($"Process {fileName} exited with non-zero exit code: {p.ExitCode}");
        }

        return new ProcessResult(outputReaderTask.Result, errorReaderTask.Result);
    }
}
