public class XmlValidation
{
    public static void Validate(string xml, string xsd)
    {
        // Create a new XML reader settings object
        var settings = new XmlReaderSettings();

        // Set the validation type to schema
        settings.ValidationType = ValidationType.Schema;

        // Add the schema to the reader settings
        settings.Schemas.Add(XmlSchema.Read(XmlReader.Create(new StringReader(xsd)), null));

        // Create a new XML reader using the specified XML and reader settings
