using System;
using System.Diagnostics;
using System.IO;

namespace RedirectProcessOutput
{
    public class ProcessRedirector
    {
        private readonly string _executablePath;
        private readonly string _arguments;
        private readonly bool _redirectStdOut;
        private readonly bool _redirectStdErr;
        private StreamWriter _stdOutStreamWriter;
        private StreamWriter _stdErrStreamWriter;

        public ProcessRedirector(string executablePath, string arguments, bool redirectStdOut = false, bool redirectStdErr = false)
        {
            _executablePath = executablePath;
            _arguments = arguments;
            _redirectStdOut = redirectStdOut;
            _redirectStdErr = redirectStdErr;

            if (_redirectStdOut)
            {
                _stdOutStreamWriter = new StreamWriter(Console.OpenStandardOutput());
            }

            if (_redirectStdErr)
            {
                _stdErrStreamWriter = new StreamWriter(Console.Error);
            }
        }

        public void RedirectProcess()
        {
            using (var process = new Process())
            {
                process.StartInfo.FileName = _executablePath;
                process.StartInfo.Arguments = _arguments;

                if (_redirectStdOut)
                {
                    process.StartInfo.RedirectStandardOutput = true;
                    process.OutputDataReceived += (sender, args) =>
                    {
                        _stdOutStreamWriter.WriteLine(args.Data);
                        _stdOutStreamWriter.Flush();
                    };
                }

                if (_redirectStdErr)
                {
                    process.StartInfo.RedirectStandardError = true;
