using System;
using System.Text;
using System.Security.Cryptography;

public string EncryptString(string data, string key)
{
    // Use a MD5 hash of the key to generate the encryption key and initialization vector.
    byte[] keyBytes = Encoding.UTF8.GetBytes(key);
    byte[] ivBytes = new MD5CryptoServiceProvider().ComputeHash(keyBytes);

    // Create a symmetric encryption algorithm with the generated key and initialization vector.
    RijndaelManaged rijndael = new RijndaelManaged();
    rijndael.Key = keyBytes;
    rijndael.IV = ivBytes;

    // Encrypt the data using the symmetric encryption algorithm.
    ICryptoTransform encryptor = rijndael.CreateEncryptor();
    byte[] encryptedData = encryptor.TransformFinalBlock(Encoding.UTF8.GetBytes(data), 0, Encoding.UTF8.GetBytes(data).Length);

    // Write the encrypted data to a memory stream.
    MemoryStream ms = new MemoryStream();
    ms.Write(encryptedData, 0, encryptedData.Length);

    // Return the encrypted data as a string.
    return Convert.ToBase64String(ms.ToArray());
}

