    Node *root = parse(contents);
    cout << root->toString() << endl;
  } else {
    cerr << "Unknown command: " << command << endl;
    return 1;
  }
}
vector<string> tokenize(const string &s) {
  istringstream iss(s);
  vector<string> tokens;
  for (auto &&token : iss) {
    tokens.push_back(token);
  }
  return tokens;
}
Node* parse(const string &s) {
  Node *root = new Node();
  root->setType("program");
  auto nodes = tokenize(s);
  for (auto &&node : nodes) {
    root->addChild(new Node(node));
  }
  return root;
}
class Node {
public:
  string type;
  vector<Node*> children;
  Node() {}
  Node(const string &type) : type(type) {}
  void setType(const string &type) { this->type = type; }
  string toString() {
    return "[" + this->type + ", " + (this->children.empty() ? "" : this->children[0]->toString()) + "]";
  }
  void addChild(Node *node) { this->children.push_back(node); }
};

