using System;
using System.Xml.Linq;

public static class XmlUpdater
{
    public static string UpdateXml(string xmlFilePath, XPathExpression xpathToRemove, XPathExpression xpathToInsertAfter)
    {
        XDocument xmlDoc = XDocument.Load(xmlFilePath);

        // Remove the element at the specified XPath location
        XElement removedElement = xmlDoc.XPathSelectElement(xpathToRemove);
        if (removedElement != null)
        {
            removedElement.Remove();
        }

        // Insert the removed element after the specified XPath location
        XElement insertAfterElement = xmlDoc.XPathSelectElement(xpathToInsertAfter);
        if (insertAfterElement != null)
        {
            insertAfterElement.AddAfterSelf(removedElement);
        }

        return xmlDoc.ToString();
    }
}
