{
    try
    {
        // Remove any padding from the key
        decryptKey = Utils.GetSubString(decryptKey, 8, "");

        // Pad the key with spaces if it's less than 8 characters long
        decryptKey = decryptKey.PadRight(8, ' ');

        // Convert the key to a byte array using UTF-8 encoding
        byte[] bytes = Encoding.UTF8.GetBytes(decryptKey);

        // Get the DES encryption keys from the DESCryptoServiceProvider class
        byte[] keys = Keys;

        // Convert the input string to a byte array using Base64 encoding
        byte[] buffer = Convert.FromBase64String(decryptString);

        // Create a new instance of the DESCryptoServiceProvider class
        DESCryptoServiceProvider provider = new DESCryptoServiceProvider();

        // Create a new MemoryStream object to store the decrypted data
        MemoryStream stream = new MemoryStream();

        // Create a new CryptoStream object using the MemoryStream and the DES encryption provider, and set it to write mode
        CryptoStream stream2 = new CryptoStream(stream, provider.CreateDecryptor(bytes, keys), CryptoStreamMode.Write);

        // Write the encrypted data to the CryptoStream
        stream2.Write(buffer, 0, buffer.Length);

        // Flush any remaining data in the CryptoStream and finalize the decryption operation
        stream2.FlushFinalBlock();

        // Return the decrypted string
