public void RemoveAndAddConfigurationNode(string key)
{
    // load XML document
    XmlDocument xmlDoc = new XmlDocument();
    xmlDoc.Load("configuration.xml");

    // get root node
    XmlElement rootNode = xmlDoc.DocumentElement;

    // find configuration node with the given key
