											Node id2 = optionAttrs2.getNamedItem("id"); //$NON-NLS-1$
											Node value = optionAttrs2.getNamedItem("value"); //$NON-NLS-1$
											cfg.setOption(id2.getNodeValue(), value.getNodeValue());
