private void PopulatePropertyWithXml(XmlDocument xmlDocument, PropertyInfo propertyInfo)
{
    // Get the XmlizedPropertyAttribute from the PropertyInfo object
    var propertyAttribute = (XmlizedPropertyAttribute)propertyInfo.GetCustomAttributes(typeof(XmlizedPropertyAttribute), false).FirstOrDefault();

    if (propertyAttribute != null)
    {
        string elementName = propertyAttribute.ElementName ?? propertyInfo.Name;
        string elementPath = propertyAttribute.Path == null ? $@"{DefaultPath}/{elementName}" : $@"{propertyAttribute.Path}/{elementName}";

        // Get the XmlNode for the specified element path
        var xmlNode = xmlDocument.SelectSingleNode(elementPath);

        if (xmlNode != null)
        {
            // Check if the property implements IExportToXmlable interface
            if (propertyInfo.PropertyType.GetInterface("IExportToXmlable", true) == typeof(IExportToXmlable))
            {
                // Get the value of the property as an IImportFromXmlable object
                var importFromXmlable = (IImportFromXmlable)propertyInfo.GetValue(this, null);

                if (importFromXmlable != null)
                    importFromXmlable.ImportFromXml(xmlNode.OuterXml);
            }
            else
            {
                // Assign the value of the XmlNode to the property
                propertyInfo.SetValue(this, xmlNode.InnerText);
            }
        }
    }
}

