import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class GaussianMutator {

    private final double low;
    private final double high;

    public GaussianMutator(double low, double high) {
        this.low = low;
        this.high = high;
    }

    public double mutatedValue(Random rng, double value, double stdDevFactor) {
        if (value < this.low || value > this.high) {
            throw new IllegalArgumentException("Input value is out of range.");
        }
        double r = rng.nextGaussian() * stdDevFactor;
        return this.low + r * (this.high - this.low);
    }

    public List<Double> getDiscreteValues() {
