public <T> T getRandomValue(Class<T> type, Class<?>[] options) {
    Random random = new Random();
    T result;
    int index = random.nextInt(options.length);
    try {
        switch (type.getName()) {
            case "java.lang.Long":
                result = (T) (Object) new Long(options[index].getMethod("getValue").invoke(null));
                break;
            case "java.util.Random":
                result = (T) options[index];
                break;
            case "java.lang.Double":
                result = (T) (Object) new Double(options[index].getMethod("getValue").invoke(null));
                break;
            case "java.lang.String":
                result = (T) options[index].getDeclaredMethod("getValue").invoke(options[index]);
                break;
            default:
                throw new UnsupportedOperationException("Unsupported type: " + type.getName());
        }
    } catch (IllegalAccessException | InvocationTargetException | NoSuchMethodException e) {
        throw new RuntimeException(e);
    }
    return result;
}

public static <T> T getRandomValueFromOptions(Class<T> type, Class<?>... options) {
    return getRandomValue(type, options)[new Random().nextInt(options.length)];
