public class JsonGenerator {

    public static String generateJson(Object obj) {
        JSONObject jsonObject;
        if (obj instanceof Map) { // Object
            jsonObject = new JSONObject();
            jsonObject.put("first_name", ((Map<String, Object>) obj).get("first_name"));
            jsonObject.put("last_name", ((Map<String, Object>) obj).get("last_name"));
            jsonObject.put("ssn", ((Map<String, Object>) obj).get("ssn"));
            for (Map.Entry<String, Object> entry : ((Map<String, Object>) obj).entrySet()) {
                if (!entry.getKey().equals("first_name") && !entry.getKey().equals("last_name") && !entry.getKey().equals("ssn")) {
