    public static void movePair(List<Pair> pairs, double percentage) {
        int totalIterations = pairs.size();
        int processedIterations = 0;

        while (processedIterations < totalIterations * percentage) {
            int currentIndex = random.nextInt(totalIterations);
            Pair currentPair = pairs.get(currentIndex);

            if (currentIndex == totalIterations - 1) {
                System.out.println("Last pair: " + currentPair);
            } else {
                int previousIndex = random.nextInt(currentIndex);
                Pair previousPair = pairs.get(previousIndex);

                swap(pairs, currentIndex, previousIndex);
                System.out.println("Swapped pair at index " + currentIndex + " with pair at index " + previousIndex);
            }

            processedIterations++;
        }
    }

    private static void swap(List<Pair> pairs, int i, int j) {
        Pair temp = pairs.get(i);
        pairs.set(i, pairs.get(j));
        pairs.set(j, temp);
    }

    static class Pair {
        int integer;
        boolean booleanValue;

        Pair(int integer, boolean booleanValue) {
            this.integer = integer;
            this.booleanValue = booleanValue;
        }

        @Override
        public String toString() {
            return "(" + integer + ", " + booleanValue + ")";
        }
    }
}
