        metricRegistry = new MetricRegistry();
        this.graphiteReporter = GraphiteReporter.forRegistry(metricRegistry)
                .convertDurationsTo(TimeUnit.SECONDS)
                .filter(MetricFilter.ALL)
                .build(graphite);
        this.metricMap = new HashMap<>();
    }

    public static MetricNotificationService getInstance() {
        return instance;
    }

    public void registerMetric(String name, MetricGauge metric) {
        this.metricMap.put(name, metric);
        metricRegistry.register(name, metric);
    }
}
