import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.FileAttribute;
import java.util.Random;

public class RandomFileGenerator {

    private static final int MIN_WRITE_LENGTH = 1;
    private static final int MAX_ARRAY_WRITE_LENGTH = 1024;

    public static Path generateRandomFile(Path folder, String fileName, int fileLength, FileSystem fs) throws IOException {
        Random rnd = new Random();
        byte[] data = new byte[fileLength];

        try (FSDataOutputStream stream = createTestStream(fs, folder, fileName)) {
            for (int i = 0; i < fileLength; ) {
                if (rnd.nextBoolean()) {
                    stream.write(data[i++]);
                } else {
                    int len = rnd.nextInt(Math.min(fileLength - i, MAX_ARRAY_WRITE_LENGTH)) + MIN_WRITE_LENGTH;
                    stream.write(data, i, len);
                    i += len;
                }
            }
            return closeAndGetResult(stream);
        }
    }

    private static FSDataOutputStream createTestStream(FileSystem fs, Path folder, String fileName) throws IOException {
        FileAttribute<Set<PosixFilePermission>> permissions = PosixFilePermission.asSet(PosixFilePermission.OWNER_READ, PosixFilePermission.OWNER_WRITE, PosixFilePermission.GROUP_READ, PosixFilePermission.OTHERS_READ);
        return fs.open(folder.resolve(fileName), createFileOptions(), permissions);
    }

    private static FileDescriptor closeAndGetResult(FSDataOutputStream stream) throws IOException {
        try {
            stream.close();
        } finally {
            return stream.getFD();
        }
    }

    private static FileChannel.OpenFlag[] createFileOptions() {
        return new FileChannel.OpenFlag[] { FileChannel.MapMode.READ_WRITE, FileChannel.MapMode.RANDOM_ACCESS };
    }
}
