public class ArrayTransformer {
    public static <T, U> U[] transformArray(T[] inputArray, Function<T, U> transformFunction) {
        if (inputArray == null || inputArray.length == 0) {
            return new U[0];
        }

        U[] outputArray = new U[inputArray.length];
        for (int i = 0; i < inputArray.length; i++) {
            outputArray[i] = transformFunction.apply(inputArray[i]);
        }
        return outputArray;
    }
}

@FunctionalInterface
interface Function<T, U> {
    U apply(T t);
}
