private static SortedBinaryDocValues compareIndexFieldData(Random random, LeafReaderContext context, IndexFieldData<?> left, IndexFieldData<?> right, Preprocessor pre) throws Exception {
    Object leftData = random.nextBoolean() ? left.load(context) : left.loadDirect(context);
    Object rightData = random.nextBoolean() ? right.load(context) : right.loadDirect(context);

    Class<?> leftType = leftData.getClass();
    Class<?> rightType = rightData.getClass();

    if (leftType != rightType) {
        throw new IllegalArgumentException("IndexFieldData objects must have the same data type.");
    }

    SortedBinaryDocValues leftValues = (SortedBinaryDocValues) leftData;
    SortedBinaryDocValues rightValues = (SortedBinaryDocValues) rightData;

    int numDocs = context.reader().maxDoc();
    SortedBinaryDocValues resultValues = new SortedBinaryDocValues(numDocs, leftValues.getComparableClass());

    for (int i = 0; i < numDocs; i++) {
        leftValues.setDocument(i);
        rightValues.setDocument(i);
        Object leftValue = leftValues.valueAt(i);
        Object rightValue = rightValues.valueAt(i);

        if (leftValue instanceof Byte) {
            byte leftByte = (Byte) leftValue;
            byte rightByte = (Byte) rightValue;
            resultValues.add(i, pre.compare((Byte) leftValue, (Byte) rightValue) < 0 ? leftByte : rightByte);
        } else if (leftValue instanceof Short) {
            short leftShort = (Short) leftValue;
            short rightShort = (Short) rightValue;
            resultValues.add(i, pre.compare((Short) leftValue, (Short) rightValue) < 0 ? leftShort : rightShort);
        } else if (leftValue instanceof Integer) {
            int leftInt = (Integer) leftValue;
            int rightInt = (Integer) rightValue;
            resultValues.add(i, pre.compare((Integer) leftValue, (Integer) rightValue) < 0 ? leftInt : rightInt);
        } else if (leftValue instanceof Long) {
            long leftLong = (Long) leftValue;
            long rightLong = (Long) rightValue;
            resultValues.add(i, pre.compare((Long) leftValue, (Long) rightValue) < 0 ? leftLong : rightLong);
        } else if (leftValue instanceof Float) {
            float leftFloat = (Float) leftValue;
            float rightFloat = (Float) rightValue;
            resultValues.add(i, pre.compareFloat((Float) leftValue, (Float) rightValue) < 0 ? leftFloat : rightFloat);
