            double leftDouble = (Double) leftValue;
            double rightDouble = (Double) rightValue;
            resultValues.add(i, pre.compareDouble((Double) leftValue, (Double) rightValue) < 0 ? leftDouble : rightDouble);
        } else {
            throw new UnsupportedOperationException("Unsupported data type: " + leftType.getName());
        }
    }

    return resultValues;
}
