import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.CountDownLatch;

public class GraphTraversalWithThreads {

    private static final int NUM_VERTICES = 10;
    private static final int NUM_EDGES = 15;
    private static final int NUM_THREADS = 5;

    static class GraphVertex {
        int id;
        AtomicInteger degree = new AtomicInteger(0);

        GraphVertex(int id) {
            this.id = id;
        }

        void addEdge(GraphThread thread) {
            degree.getAndIncrement();
            thread.completedEdges.getAndIncrement();
        }
    }

    static class GraphThread extends Thread {
        int startVertex;
        GraphVertex[] graphVertices = new GraphVertex[NUM_VERTICES];
        AtomicInteger vertices = new AtomicInteger(0);
        AtomicInteger edges = new AtomicInteger(0);
        AtomicInteger completedThreads = new AtomicInteger(0);

        GraphThread(int startVertex) {
            this.startVertex = startVertex;
            for (int i = 0; i < NUM_VERTICES; i++) {
                graphVertices[i] = new GraphVertex(i);
            }
        }

        @Override
        public void run() {
            for (int i = startVertex; i < NUM_VERTICES; i += NUM_THREADS) {
                GraphVertex currentVertex = graphVertices[i];
                for (int j = 0; j < NUM_EDGES; j++) {
                    int neighbor = i + (j % NUM_THREADS) + 1;
                    if (neighbor < NUM_VERTICES) {
                        graphVertices[neighbor].addEdge(this);
                    }
                }
                vertices.getAndAdd(1);
                edges.getAndAdd(NUM_EDGES);
            }
            completedThreads.getAndIncrement();
            System.out.println("Completed threads: " + completedThreads.get());
        }

        AtomicInteger completedEdges = new AtomicInteger(0);
    }

    public static void main(String[] args) throws InterruptedException {
