import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class CommandExecutor {
    public void executeCommand(String command) {
        File fileToDelete = Paths.get("path/to/file").toFile();
        if (fileToDelete.exists()) {
            Files.delete(fileToDelete.toPath());
        }

        String[] cmdArray;
        Process proc;
        try {
            cmdArray = command.split("\\s+");
            proc = Runtime.getRuntime().exec(cmdArray, null, null);
        } catch (Exception e) {
            System.err.println("Error executing command: " + e.getMessage());
            return;
        }

        BufferedReader inputReader = new BufferedReader(new InputStreamReader(proc.getInputStream()));
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(proc.getErrorStream()));

        String inputLine;
        String errorLine;

        try {
            while ((inputLine = inputReader.readLine()) != null) {
                System.out.println("Output: " + inputLine);
            }
            while ((errorLine = errorReader.readLine()) != null) {
                System.err.println("Error: " + errorLine);
            }
        } catch (IOException e) {
            System.err.println("Error reading streams: " + e.getMessage());
        }

