public class JsonGenerator {

    @Nonnull
    public static String toJson(@Nonnull Object object) {
        if (object instanceof String) {
            return new JSONObject().put("type", "string").put("value", (String) object).toString();
        } else if (object instanceof Number) {
            return new JSONObject().put("type", "number").put("value", object.toString()).toString();
        } else if (object instanceof Boolean) {
            return new JSONObject().put("type", "boolean").put("value", object.toString()).toString();
        } else if (object instanceof Object[]) {
            JSONArray jsonArray = new JSONArray();
            for (Object element : (Object[]) object) {
                jsonArray.put(toJson(element));
            }
            return jsonArray.toString();
        } else if (object instanceof Map) {
            JSONObject jsonObject = new JSONObject();
            for (Object key : ((Map<Object, Object>) object).keySet()) {
                jsonObject.put(toJson(key), toJson(object.get(key)));
            }
            return jsonObject.toString();
        }
        throw new UnsupportedOperationException("Unsupported object type: " + object.getClass().getName());
    }

    private JsonGenerator() {}
}
