import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.Random;

public class WeightedItemsNormalizer<E, T> {

    private final Function<E, T> elemFunc;
    private final Function<E, Double> weightFunc;
    private final List<E> weightedItems;
    private final Map<T, Double> normalized;
    private final Random rnd = new Random();

    public WeightedItemsNormalizer(Function<E, T> elemFunc, Function<E, Double> weightFunc, List<E> weightedItems) {
        this.elemFunc = elemFunc;
        this.weightFunc = weightFunc;
        this.weightedItems = weightedItems;
        this.normalized = new LinkedHashMap<>();
    }

    public Map<T, Double> normalize() {
        double sum = 0.0;

        for (E e : weightedItems) {
            sum += weightFunc.apply(e);
        }

        for (E e : weightedItems) {
            normalized.put(elemFunc.apply(e), weightFunc.apply(e) / sum);
        }
        return normalized;
    }
}
