import java.util.DisjointSet;
import java.util.Timer;
import java.util.TimerTask;

public static int countDisjointPairs(int[] arr) {
    DisjointSet disjointSet = new DisjointSet();
    int pairs = 0;
    long totalTime = 0;

    for (int i = 0; i < arr.length; i++) {
        int j = i + 1;
        long startTime = System.nanoTime();
        disjointSet.union(arr[i], arr[j]);
        totalTime += System.nanoTime() - startTime;
        if (disjointSet.find(arr[i]) == disjointSet.find(arr[j])) {
            pairs++;
        }
    }

    System.out.println("Total time taken: " + totalTime + " ns");
    return pairs;
}

public static class DisjointSet {
    private int[] id;

    public DisjointSet() {
        id = new int[30000]; // Assuming the array size is known and within the limit
        for (int i = 0; i < id.length; i++) {
            id[i] = i;
        }
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            id[rootX] = rootY;
        }
    }

    public int find(int x) {
        int root = x;
        while (root != id[root]) {
            root = id[root];
        }
        id[x] = root;
        return root;
    }
