    public RectF cropDrawable(RectF drawableBounds, RectF viewport) {
        float drawableAspectRatio = drawableBounds.width() / drawableBounds.height();
        float viewportAspectRatio = viewport.width() / viewport.height();

        RectF maxCrop = new RectF();
        if (drawableAspectRatio > viewportAspectRatio) {
            float r = drawableBounds.height() / viewport.height() * viewport.width();
            float b = drawableBounds.height();
            maxCrop.set(0, 0, r, b);
