import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.SocketChannel;

public class ConnectionHandler {
    private SocketChannel socketChannel;
    private SelectionKey selectionKey;

    public void establishConnection(InetSocketAddress remoteAddress) throws IOException {
        socketChannel = Sockets.channel();
        socketChannel.configureBlocking(false);
        selectionKey = socketChannel.register(SelectorProvider.provider().openSelector(), SelectionKey.OP_CONNECT);

        try {
            boolean connected = socketChannel.connect(remoteAddress);
            if (!connected) {
                selectionKey.interestOps(selectionKey.interestOps() | SelectionKey.OP_CONNECT);
            }
        } catch (IOException e) {
            closeChannel();
            throw e;
        }
    }

    public void handleConnectionStateChanges() throws IOException {
        Selector selector = selectorProvider.provider().openSelector();
        selector.select();

        for (SelectionKey key : selector.selectedKeys()) {
            if (key == selectionKey) {
                if (key.isConnectable()) {
                    socketChannel.finishConnect();
                    key.interestOps(SelectionKey.OP_READ | SelectionKey.OP_WRITE);
                }
            }
            selector.selectedKeys().clear();
        }
    }

    private void closeChannel() throws IOException {
        if (socketChannel != null) {
            socketChannel.close();
            selectionKey.cancel();
            socketChannel = null;
        }
    }
}
```

