import java.util.ArrayList;
import java.util.List;

public class GeoPointComparator {

    public static void compareGeoPointSets(Object set1, Object set2, double distanceTolerance) throws Exception {
        if (set1 instanceof List && set2 instanceof List) {
            List<GeoPoint> list1 = (List<GeoPoint>) set1;
            List<GeoPoint> list2 = (List<GeoPoint>) set2;

            if (list1.size() != list2.size()) {
                throw new Exception("Number of points is not equal in both sets.");
            }

            for (int i = 0; i < list1.size(); i++) {
                GeoPoint point1 = list1.get(i);
                GeoPoint point2 = list2.get(i);

                if (point1.getLat() != point2.getLat() || point1.getLon() != point2.getLon()) {
                    throw new Exception("Point at index " + i + " is not equal in both sets.");
                }

                if (i > 0 && point1.compareTo(point2) < 0) {
                    throw new Exception("Points are not in increasing order in one of the sets.");
                }
            }
        } else {
            throw new Exception("Both sets must be of List type.");
        }
    }

    public static class GeoPoint implements Comparable<GeoPoint> {
        private double lat;
        private double lon;

        public GeoPoint(double lat, double lon) {
            this.lat = lat;
            this.lon = lon;
        }

        public double getLat() {
            return lat;
        }

        public double getLon() {
            return lon;
        }

        @Override
        public int compareTo(GeoPoint o) {
            if (this.lat < o.lat) {
                return -1;
            } else if (this.lat > o.lat) {
                return 1;
            } else {
                if (this.lon < o.lon) {
                    return -1;
                } else if (this.lon > o.lon) {
                    return 1;
                } else {
                    return 0;
                }
            }
        }
    }
}
