public class EmailSender {

    private EmailSender(Activity activity, String subject) {
        mActivityRef = new WeakReference<>(activity);
        mSubject = subject;
    }

    public static void sendEmail(final boolean success, final Activity activity, final String subject) {
        new Handler(Looper.getMainLooper()).post(new Runnable() {
            @Override
            public void run() {
                Activity activity = mActivityRef.get();
                if (activity == null) {
                    return;
                }

