import org.apache.hadoop.security.UserGroupInformation;
import org.apache.hadoop.security.token.DelegationToken;
import org.apache.hadoop.security.token.TokenIdentifier;
import org.apache.hadoop.util.StringUtils;
import org.apache.hadoop.util.Time;

public class DelegationTokenManagerUtil {

  public static boolean createOrRenewToken(String userName, String tokenId, DelegationTokenManagerService delegationTokenManagerService) {
    try {
      UserGroupInformation ugi = UserGroupInformation.createRemoteUser(userName);
      DelegationToken token = null;
      if (tokenId == null) {
        token = delegationTokenManagerService.createToken(ugi, null);
      } else {
        token = delegationTokenManagerService.renewToken(new TokenIdentifier(tokenId), ugi);
      }
      if (token != null) {
        long renewedTokenExpiry = token.getRenewUntil();
        if (renewedTokenExpiry > Time.now().getTime()) {
          return true;
        }
      }
    } catch (Exception e) {
      // Handle exceptions
    }
    return false;
  }

  public static boolean verifyToken(String userName, String tokenId, DelegationTokenManagerService delegationTokenManagerService) {
    try {
      UserGroupInformation ugi = UserGroupInformation.createRemoteUser(userName);
      DelegationToken token = delegationTokenManagerService.getToken(new TokenIdentifier(tokenId), ugi);
      if (token != null) {
        return true;
      }
    } catch (Exception e) {
      // Handle exceptions
    }
    return false;
  }

  public static boolean cancelToken(String userName, String tokenId, DelegationTokenManagerService delegationTokenManagerService) {
    try {
      UserGroupInformation ugi = UserGroupInformation.createRemoteUser(userName);
      delegationTokenManagerService.cancelToken(new TokenIdentifier(tokenId), ugi);
      return true;
    } catch (Exception e) {
      // Handle exceptions
    }
    return false;
  }
}
