public void createAndPopulateGraphDatabase(GraphDatabase graphDatabase, ExecutorService executorService, int iterationCount) {
    VertexLabel vertexLabel = graphDatabase.getGraph().getTopology().ensureVertexLabelExist("vertex", new HashMap<>() {{
        put("test", PropertyDefinition.of(PropertyType.LONG));
        put("blah", PropertyDefinition.of(PropertyType.DOUBLE));
    }});
    vertexLabel.ensureEdgeLabelExist("friend", vertexLabel, new HashMap<>() {{
        put("bloop", PropertyDefinition.of(PropertyType.INTEGER));
    }});

    for (int i = 0; i < iterationCount; i++) {
        executorService.submit(() -> {
            try {
                final Random random = new Random();
                Vertex a = graphDatabase.addVertex();
                Vertex b = graphDatabase.addVertex();
                Edge e = a.addEdge("friend", b);

                a.property("test", Thread.currentThread().getId());
                b.property("blah", random.nextDouble());
                e.property("bloop", random.nextInt());

                graphDatabase.tx().commit();
            } catch (Exception e) {
                graphDatabase.tx().rollback();
            }
        });
    }

    try {
        executorService.shutdown();
        executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.MILLISECONDS);
    } catch (InterruptedException e) {
        e.printStackTrace();
    }
}
