List<SensorData> generateSensorData(List<LocationTime> locationTimeList, List<Double[]> accStds, double stepPerSec) {
    List<SensorData> sensorDataList = new ArrayList<>();

    Random rand = new Random();

    for (LocationTime locTime : locationTimeList) {
        long timestamp = locTime.getTimestamp();
        double[] accData = new double[3];

        for (int i = 0; i < 3; i++) {
            accData[i] = 0.0 + accStds.get(i)[0] * rand.nextGaussian();
        }

        double az = (stepPerSec * (timestamp % (1000 / stepPerSec))) / 9.81 + accStds.get(2)[0] * rand.nextGaussian();

        SensorData sensorData = new SensorData();
        sensorData.setTimestamp(timestamp);
        sensorData.setType("ACC");
        sensorData.setData(accData);
        sensorData.setZData(az);

        sensorDataList.add(sensorData);
    }

    return sensorDataList;
}
