import org.ietf.jgss.GSSContext;
import org.ietf.jgss.GSSException;
import org.ietf.jgss.Oid;
import org.ietf.jgss.OidFactory;
import org.ietf.jgss.Subject;
import org.ietf.jgss.GSSName;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.URL;
import java.security.PrivilegedExceptionAction;
import java.util.EnumSet;

public class KerberosDelegation {

    public static Text getDelegationToken(String kdcUrl, int kdcPort) {
        boolean hasToken = false;
        Text dtService = null;

        try {
            SunProvider sunProvider = new SunProvider();
            GSSContext gssContext = sunProvider.initSecContext(
                    null, null, null,
                    Oid.KRB5_NT_INITIATE, null,
                    null, null,
                    EnumSet.of(EnumSet.of(GSSContext.AllowDelegation, GSSContext.DisableOidCheck),
                            EnumSet.allOf(GSSContext.class)),
                    null);

            GSSName me = gssContext.getSourceName();
            GSSName service = OidFactory.getInstance().newName(
                    "1.2.840.113554.1.2.2", "krb5int_as_req");

            gssContext.requestOneway(service, me, null, null, null);

            byte[] asRep = gssContext.getToken(0).getRepresentation();
            Subject delegatedSubject = gssContext.getSourceName().getSubject();

            if (delegatedSubject != null && delegatedSubject.isEmpty()) {
                hasToken = true;
                dtService = new Text(new String(asRep));
            }

            gssContext.dispose();

        } catch (GSSException | IOException e) {
            e.printStackTrace();
        }

        return new Text(dtService != null ? dtService.toString() : "No delegation token found");
    }

    static class SunProvider extends sun.security.krb5.Krb5Config {
        @Override
        public PrivilegedExceptionAction<Void> initKrb5() {
            return super.initKrb5();
        }
    }

    public static void main(String[] args) {
        Text token = getDelegationToken("localhost:88", 88);
        System.out.println(token);
    }
}
```

