import java.net.*;

public class ProxyServer {
    private Proxy proxy1;
    private Proxy proxy2;

    public ProxyServer(String proxy1Host, int proxy1Port, String proxy2Host, int proxy2Port) {
        this.proxy1 = new Proxy(Proxy.Type.HTTP, new InetSocketAddress(proxy1Host, proxy1Port));
        this.proxy2 = new Proxy(Proxy.Type.HTTP, new InetSocketAddress(proxy2Host, proxy2Port));
    }

    public URL makeHttpRequest(String targetHost, String targetPort) throws IOException {
        HttpURLConnection connection = (HttpURLConnection) new URL("http://" + targetHost + ":" + targetPort).openConnection();
        connection.setRequestProperty("proxy-authenticate", "Basic Realm=\"Proxy\"");
        connection.setRequestProperty("proxy-authorization", "Basic " + new String(Base64.getEncoder().encode("username:password".getBytes()))); // replace "username:password" with actual credentials
        connection.setRequestProperty("proxy-server", "Proxy1: " + this.proxy1.toString() + "; Proxy2: " + this.proxy2.toString());
        connection.setRequestProperty("proxy-select", "Proxy1"); // choose which proxy to use first
        connection.setDoOutput(true);
        connection.setConnectTimeout(5000);
        connection.connect();
        return connection.getURL();
    }
}
