import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Pattern;
import java.util.regex.Matcher;

public class Main {
    private static final String PATTERN_TO_FIND = "your_pattern_here";
    private static final int SLEEP_TIME_MS = 1000; // in milliseconds

    public static boolean checkPatternInOutput(String command) throws InterruptedException, IOException {
        Process process = Runtime.getRuntime().exec(command);
        process.waitFor();

        InputStream inputStream = process.getInputStream();
        InputStreamReader inputStreamReader = new InputStreamReader(inputStream);
        BufferedReader bufferedReader = new BufferedReader(inputStreamReader);

        String line;
        Pattern pattern = Pattern.compile(PATTERN_TO_FIND);
        while ((line = bufferedReader.readLine()) != null) {
            Matcher matcher = pattern.matcher(line);
            if (matcher.find()) {
                Thread.sleep(SLEEP_TIME_MS);
                System.out.println("Pattern found. Waiting before checking again...");
                return false;
            }
        }

        System.out.println("Pattern not found.");
        return true;
    }

    public static void main(String[] args) {
        String command = "your_command_here";
        try {
            boolean patternFound = checkPatternInOutput(command);
            System.out.println("Pattern found: " + patternFound);
        } catch (InterruptedException | IOException e) {
            e.printStackTrace();
        }
    }
}
```

