            byte[] bytes = new byte[1024];

            while ((read = conn.getInputStream().read(bytes)) != -1) {
                fileOutputStream.write(bytes, 0, read);
            }

            fileOutputStream.close();
            conn.disconnect();

            return file.toURI();

        } catch (IOException e) {
            System.out.println("Error downloading file: " + e.getMessage());
            return null;
        }
    }
}
