import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.stream.Collectors;

public class CommandExecutor {
    private static final String ERROR_MESSAGE = "Error message to exit on";

    public static void main(String[] args) {
        String command = "command-line-application.jar"; // replace with your command-line application

        Runtime runtime = Runtime.getRuntime();
        Process process;

        try {
            process = runtime.exec(command);
        } catch (Exception e) {
            System.err.println("Error executing command: " + e.getMessage());
            return;
        }

        Thread outputThread = new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
                String output = reader.lines().collect(Collectors.joining("\n"));
                System.out.println("Output:");
                System.out.println(output);
            } catch (Exception e) {
                System.err.println("Error reading output stream: " + e.getMessage());
            }
        });

        Thread errorThread = new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream(), StandardCharsets.UTF_8))) {
                String error = reader.lines().collect(Collectors.joining("\n"));
                System.out.println("Error:");
                System.out.println(error);

                if (error.contains(ERROR_MESSAGE)) {
                    System.out.println("Error message found. Exiting...");
                    process.destroy();
                    System.exit(1);
                }
            } catch (Exception e) {
                System.err.println("Error reading error stream: " + e.getMessage());
            }
        });

        outputThread.start();
        errorThread.start();

        try {
            process.waitFor();
        } catch (InterruptedException e) {
            System.err.println("Interrupted while waiting for process to finish: " + e.getMessage());
        }
    }
}
