import java.io.*;
import java.util.ArrayList;
import java.util.Hashtable;

public class FileFilter {
    public static void main(String[] args) {
        String directoryPath = "path/to/directory";
        String dataType = "YourSpecificDataType";
        ArrayList<File> filesWithData = new ArrayList<>();

        File directoryFile = new File(directoryPath);
        File[] files = directoryFile.listFiles();

        Hashtable<String, Object> dataTable = new Hashtable<>();

        for (File file : files) {
            try {
                FileInputStream fileInputStream = new FileInputStream(file);
                ObjectInputStream objectInputStream = new ObjectInputStream(fileInputStream);

                try {
                    Object object = objectInputStream.readObject();
                    if (object != null && object.getClass().getName().equals(dataType)) {
                        filesWithData.add(file);
                        dataTable.put(file.getName(), object);
                    }
                } catch (ClassNotFoundException e) {
                    e.printStackTrace();
                } finally {
                    objectInputStream.close();
                    fileInputStream.close();
                }
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        System.out.println("Files containing the specified data type:");
        for (String fileName : dataTable.keySet()) {
            System.out.println(fileName);
        }

        System.out.println("Files with the specified data:");
        for (File file : filesWithData) {
            System.out.println(file.getAbsolutePath());
        }
    }
}
