                throw new IllegalArgumentException("Invalid port number in url: " + url);
            } catch (UnknownHostException e) {
                throw new IllegalArgumentException("Unknown host in url: " + url);
            }
        }
    }

    if (addresses.isEmpty()) {
        throw new IllegalArgumentException("No resolvable addresses given in urls");
    }

