@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(ServerHttpSecurity http) {
        return http.authorizeExchange()
                .pathMatchers("/admin/**").hasRole("ADMIN")
                .pathMatchers("/user/**").hasRole("USER")
                .anyExact("/", "/css/**", "/js/**", "/images/**")
                .permitAll()
                .and()
                .cacheControl()
                .and()
                .oauth2Login()
                .and()
                .formLogin().disable()
                .csrf().disable()
                .build();
    }

    @Bean
    public ReactiveSecurityContextRepository contextRepository() {
        return SecurityContextRepositories.cacheAndSession();
    }

    @Bean
    public ReactiveRedisCacheManager cacheManager(ReactiveRedisConnectionFactory connectionFactory) {
        return new ReactiveRedisCacheManager(connectionFactory);
    }

    @Bean
    public CacheManager cacheManager() {
        return new ConcurrentMapCacheManager("requestCache");
    }

    @Bean
    public RequestCache requestCache() {
        return new HttpSessionRequestCacheManager();
    }

    @Bean
    public SecurityWebFilterChain securityWebFilterChain(ServerHttpSecurity http) {
        return http.securityContexts(context -> context.setRequestCache(requestCache()))
                .authorizeExchange()
                .pathMatchers("/admin/**").hasRole("ADMIN")
                .pathMatchers("/user/**").hasRole("USER")
                .anyExact("/", "/css/**", "/js/**", "/images/**")
                .permitAll()
                .and()
                .cacheControl()
                .and()
                .oauth2Login()
                .and()
                .formLogin().disable()
                .csrf().disable()
                .build();
    }
}
