import java.io.*;
import java.util.Map;
import java.util.HashMap;

public class MapSerialization {

    public static void serializeMap(Map<String, Object> map, File file) throws IOException {
        try (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(file))) {
            out.writeObject(map);
        }
    }

    public static Map<String, Object> deserializeMap(File file) throws IOException, ClassNotFoundException {
        try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(file))) {
            return (Map<String, Object>) in.readObject();
        }
    }

