import org.apache.mina.common.IoFilter;
import org.apache.mina.common.IoSessionConfig;
import org.apache.mina.filter.executor.ExecutorFilter;
import org.apache.mina.transport.socket.NioSocketConnector;

import java.net.URI;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.ThreadPoolExecutor;

public void setupSocketConnection(URI uri) throws Exception {
    boolean minaLogger = true; // set to true if logging is required
    long timeout = 5000; // set desired timeout in milliseconds
    List<IoFilter> filters = null; // set filters if needed

    String host = uri.getHost();
    int port = uri.getPort();

    final int processorCount = Runtime.getRuntime().availableProcessors() + 1;
    NioSocketConnector connector = new NioSocketConnector(processorCount);

    IoSessionConfig connectorConfig = connector.getSessionConfig();
    ExecutorService workerPool;
    if (minaLogger) {
        workerPool = new OrderedThreadPoolExecutor(configuration.getMaximumPoolSize());
        connector.getFilterChain().addLast("threadPool", new ExecutorFilter(workerPool));
        connector.getFilterChain().addLast("logger", new LoggingFilter());
    } else {
        workerPool = new OrderedThreadPoolExecutor(configuration.getMaximumPoolSize());
        connector.getFilterChain().addLast("threadPool", new ExecutorFilter(workerPool));
    }

    InetSocketAddress address = new InetSocketAddress(host, port);
    connector.getFilterChain().addLast("threadPool", new ExecutorFilter(workerPool));

    if (filters != null) {
        appendIoFiltersToChain(filters, connector.getFilterChain());
    }

    if (minaLogger) {
        connector.getFilterChain().addLast("logger", new LoggingFilter());
    }

    SslContextParameters sslContextParameters = null; // set if SSL is required
    if (sslContextParameters != null) {
        SslFilter sslFilter = new SslFilter(
                sslContextParameters.createSSLContext(getEndpoint().getCamelContext()),
                configuration.isAutoStartTls());
        sslFilter.setUseClientMode(true);
        connector.getFilterChain().addFirst("sslFilter", sslFilter);
    }

    configureCodecFactory("MinaProducer", connector);
    connector.setConnectTimeoutMillis(timeout);
}

private void appendIoFiltersToChain(List<IoFilter> filters, IoFilterChain filterChain) {
    for (IoFilter filter : filters) {
        filterChain.addLast(filter);
    }
}
