import java.io.File;
import java.security.SecureRandom;

public class KeystoreGenerator {
    private static final String KEYTOOL_COMMAND = "keytool";

    public static void main(String[] args) {
        String hostname = args[0];
        int validityDays = Integer.parseInt(args[1]);

        File tempDirectory = new File("temp");
        if (!tempDirectory.exists()) {
            tempDirectory.mkdir();
        }

        File keystoreFile = new File(tempDirectory, "keystore.jks");

        try {
            generateKeystore(hostname, keystoreFile, validityDays);
            System.out.println("Keystore generated successfully at " + keystoreFile.getAbsolutePath());
        } catch (Exception e) {
            System.err.println("Error generating keystore: " + e.getMessage());
        } finally {
            if (tempDirectory.exists()) {
                File[] files = tempDirectory.listFiles();
                for (File file : files) {
                    file.delete();
                }
                tempDirectory.delete();
            }
        }
    }

    private static void generateKeystore(String hostname, File keystoreFile, int validityDays) throws Exception {
        String keyPassword = generateRandomPassword();

        ProcessBuilder pb = new ProcessBuilder(KEYTOOL_COMMAND,
                "-keystore", keystoreFile.getAbsolutePath(),
                "-storepass", keyPassword,
                "-genkeypair",
                "-alias", hostname,
                "-keyalg", "RSA",
                "-validity", validityDays + "",
                "-dname", "CN=" + hostname
        );
        pb.redirectErrorStream(true);
        Process process = pb.start();
        process.waitFor();
    }

    private static String generateRandomPassword() {
        SecureRandom random = new SecureRandom();
        byte[] passwordBytes = new byte[16];
        random.nextBytes(passwordBytes);
        return new String(passwordBytes);
    }
}
```

