import java.io.*;
import java.util.HashMap;
import java.util.Map;
import edu.stanford.nlp.ling.CoreAnnotations.*;
import edu.stanford.nlp.pipeline.*;
import edu.stanford.nlp.util.CoreMap;
import edu.stanford.nlp.ie.crf.*;
import edu.stanford.nlp.ie.*;
import edu.stanford.nlp.util.Pair;

public class POSTagger {
    private SerializableSequenceModel<TagSequenceLabel> model;
    private CRFClassifier<TagSequenceLabel> classifier;

    public POSTagger(String modelFile) throws IOException, ClassNotFoundException {
        FileInputStream fileIn = new FileInputStream(modelFile);
        ObjectInputStream objIn = new ObjectInputStream(fileIn);
        this.model = (SerializableSequenceModel<TagSequenceLabel>) objIn.readObject();
        this.classifier = new CRFClassifier<TagSequenceLabel>(this.model);
        Streams.closeInputStream(objIn);
    }

    public Map<String, String> tagText(String text) {
        Map<String, String> taggedWords = new HashMap<>();
        Annotation document = new Annotation(text);
        new StanfordCoreNLP(Properties.builder()
                .annotators("tokenize, ssplit, pos")
                .build())
                .annotate(document);

        for (CoreMap sentence : document.get(SentencesAnnotation.class)) {
            for (CoreLabel token : sentence.get(TokensAnnotation.class)) {
                String word = token.get(TextAnnotation.class);
                String tag = token.get(PartOfSpeechAnnotation.class);
                taggedWords.put(word, tag);
            }
        }

        return taggedWords;
    }

    public static void main(String[] args) throws IOException, ClassNotFoundException {
        String modelFile = "path/to/model.ser.gz";
        POSTagger tagger = new POSTagger(modelFile);
        String text = "The quick brown fox jumps over the lazy dog.";
        Map<String, String> taggedWords = tagger.tagText(text);
        for (Map.Entry<String, String> entry : taggedWords.entrySet()) {
            System.out.println(entry.getKey() + " : " + entry.getValue());
        }
    }
}
