```java import java.io.BufferedInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.net.URL;

public class DictionaryDownloader {

    public static String downloadDictionary(String url) {
        String tempFileName = "tempDictionary.txt";

        try {
            URL dictionaryUrl = new URL(url);
            BufferedInputStream in = new BufferedInputStream(dictionaryUrl.openStream());
            FileOutputStream out = new FileOutputStream(tempFileName);

            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = in.read(buffer, 0, buffer.length)) != -1) {
                out.write(buffer, 0, bytesRead);
            }

            out.close();
            in.close();

            // Replace the existing dictionary file with the downloaded one
            replaceExistingFile(tempFileName, "dictionary.txt");

        } catch (IOException e) {
            System.err.println("Error downloading dictionary from URL: " + url);
            e.printStackTrace();
        }

        return "Dictionary downloaded and saved to dictionary.txt";
    }

    private static void replaceExistingFile(String tempFileName, String existingFileName) {
        try {
            java.nio.file.Files.copy(java.nio.file.Paths.get(tempFileName), java.nio.file.Paths.get(existingFileName), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            System.err.println("Error replacing existing file: " + existingFileName);
            e.printStackTrace();
        }
    }
}
