import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;

public class HashFunction {
    private static final Map<String, MessageDigest> ALGORITHMS = new HashMap<>();

    static {
        ALGORITHMS.put("MD5", MessageDigest.getInstance("MD5"));
        ALGORITHMS.put("SHA1", MessageDigest.getInstance("SHA-1"));
        ALGORITHMS.put("SHA-256", MessageDigest.getInstance("SHA-256"));
        ALGORITHMS.put("SHA-384", MessageDigest.getInstance("SHA-384"));
        ALGORITHMS.put("SHA-512", MessageDigest.getInstance("SHA-512"));
