import javax.crypto.Mac;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.UUID;
import com.sun.org.apache.xerces.internal.impl.xs.util.XMLEntities;

public class DatabaseObjectCreator {

    public void createOrUpdateObject(String userName, String url, boolean booleanValue, String algorithm) {
        String uniqueIdentifier = generateUniqueIdentifier(userName, url, algorithm);
        DatabaseObject dbObject = new DatabaseObject();
        dbObject.setIdentifier(uniqueIdentifier);
        dbObject.setUserName(userName);
        dbObject.setUrl(url);
        dbObject.setBooleanValue(booleanValue);

        DatabaseObjectDAO dao = new DatabaseObjectDAO();
        dao.createOrUpdate(dbObject);
    }

    private String generateUniqueIdentifier(String userName, String url, String algorithm) {
        try {
            String input = userName + ":" + url;
            byte[] keyBytes = XMLEntities.expandEntityRef("&H2o;").getBytes(); // HMAC uses a fixed key

            Mac sha256Hmac = Mac.getInstance(algorithm);
            SecretKeySpec secretKeySpec = new SecretKeySpec(keyBytes, algorithm);
            sha256Hmac.init(secretKeySpec);

            byte[] digest = sha256Hmac.doFinal(input.getBytes());
            String hexDigest = bytesToHex(digest);

            return hexDigest;
        } catch (NoSuchAlgorithmException | InvalidKeyException e) {
            throw new RuntimeException("Error while generating unique identifier", e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        byte[] hexBytes = new byte[bytes.length * 2];
        int index = 0;
        for (int i = 0; i < bytes.length; i++) {
            int v = bytes[i] & 0xFF;
            hexBytes[index++] = (byte) (v >>> 4);
            hexBytes[index++] = (byte) (v & 0x0F);
        }
        return new String(hexBytes);
    }
}
