import java.io.*;
import java.net.Socket;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.util.UUID;
import java.io.Serializable;

public class RemoteServerCaller {
    private String serverAddress;
    private int serverPort;

    public Object callRemoteMethod(String methodName, Object[] args) throws IOException {
        Socket socket = new Socket(serverAddress, serverPort);

        ObjectOutputStream outputStream = new ObjectOutputStream(socket.getOutputStream());
        ObjectInputStream inputStream = new ObjectInputStream(socket.getInputStream());

        UUID requestId = UUID.randomUUID();
        CallRequest request = new CallRequest(methodName, args, requestId);

        outputStream.writeObject(request);
        outputStream.flush();

        Object result = null;
        try {
            Object response = inputStream.readObject();
            if (response instanceof CallResponse) {
                CallResponse callResponse = (CallResponse) response;
                if (callResponse.getId().equals(requestId)) {
                    result = callResponse.getResult();
                }
            }
        } catch (ClassNotFoundException e) {
            e.printStackTrace();
        }

        outputStream.close();
        inputStream.close();
        socket.close();

        return result;
    }

    private static class CallRequest implements Serializable {
        private String methodName;
        private Object[] args;
        private UUID id;

        public CallRequest(String methodName, Object[] args, UUID id) {
            this.methodName = methodName;
            this.args = args;
            this.id = id;
        }
    }

    private static class CallResponse implements Serializable {
        private String methodName;
        private Object result;
        private UUID id;

        public CallResponse(String methodName, Object result, UUID id) {
            this.methodName = methodName;
            this.result = result;
            this.id = id;
        }

        public UUID getId() {
            return id;
        }

        public Object getResult() {
            return result;
        }
    }
}

