import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;

public class SocketConnection {
    private SocketChannel socketChannel;
    private ByteBuffer messageBuffer;
    private int port;
    private String host;

    public SocketConnection(String host, int port) {
        this.host = host;
        this.port = port;
        this.messageBuffer = ByteBuffer.allocateDirect(1024);
    }

    public void connectAndSendMessage(String message) throws IOException {
        openSocket();
        messageBuffer.clear();
        messageBuffer.put(message.getBytes());
        messageBuffer.flip();

        try {
            socketChannel.write(messageBuffer);
            socketChannel.setOption(StandardSocketOptions.SO_KEEPALIVE, true);
        } catch (IOException e) {
            if (e.getMessage().contains("Connection reset by peer")) {
                System.out.println("Connection lost, trying to reconnect...");
                this.socketChannel.close();
                try {
                    openSocket();
                    connectAndSendMessage(message);
                } catch (IOException ex) {
                    throw new RuntimeException("Failed to reconnect", ex);
                }
            } else {
                throw e;
            }
        }
    }

    private void openSocket() throws IOException {
        this.socketChannel = SocketChannel.open();
        this.socketChannel.connect(new InetSocketAddress(host, port));
        this.socketChannel.setOption(StandardSocketOptions.SO_KEEPALIVE, true);
    }

    public void handleFlush() throws IOException {
        messageBuffer.clear();
        messageBuffer.put(messageBuffer);
        messageBuffer.flip();
        try {
            socketChannel.write(messageBuffer);
        } catch (IOException e) {
            System.out.println("Flush failed, trying to re-send message...");
            connectAndSendMessage(new String(messageBuffer.array(), 0, messageBuffer.limit()));
        }
    }
}
