import org.jupsiedge.nio.datagram.DatagramConnector;
import org.jupsiedge.nio.datagram.NioDatagramChannel;
import org.jupsiedge.nio.ssl.SslContextParameters;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.util.List;

public class DatagramConnectionSetup {

    public DatagramConnector setupDatagramConnection(String uri) throws IllegalArgumentException {
        if (Boolean.parseBoolean(uri.split(":")[0])) {
            throw new IllegalArgumentException("Transfer exchange should not be set to true.");
        }

        boolean logger = false; // set to true if logging is required
        long timeout = 5000; // set the connection timeout in milliseconds
        List<ThreadPoolExecutor> filters = null; // set up thread pool executors if needed

        String[] parts = uri.split(":");
        int port = Integer.parseInt(parts[1]);
        String host = parts[2];

        InetSocketAddress address = new InetSocketAddress(host, port);

        int processorCount = Runtime.getRuntime().availableProcessors() + 1;
        DatagramConnector connector = new DatagramConnector(processorCount);

        connector.getSessionConfig().setSoTimeout(timeout);

        if (logger) {
            connector.getFilterChain().addLast("logger", new LoggingFilter());
        }

        if (filters != null) {
            for (ThreadPoolExecutor filter : filters) {
                connector.getFilterChain().addLast("threadPool", new ExecutorFilter(filter));
            }
        }

        if (uri.startsWith("ssl:")) {
            String[] sslParts = uri.split(":")[1].split("/");
            SslContextParameters sslContextParameters = new SslContextParameters(sslParts[0], sslParts[1]);
            NioDatagramChannel sslFilter = new NioDatagramChannel(connector.getSessionConfig(), sslContextParameters.createSSLContext(null), true);
            connector.getFilterChain().addFirst("sslFilter", sslFilter);
        }

        return connector;
    }
}
