import lzo.LZOCompressor;
import lzo.LZOException;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.math.BigInteger;
import java.security.MessageDigest;

public static String compressAndGetMD5(String filePath, int compressionLevel) {
    try {
        File file = new File(filePath);
        byte[] input = new byte[(int) file.length()];
        FileInputStream fis = new FileInputStream(file);
        fis.read(input);
        fis.close();

        byte[] output = new byte[input.length + LZOCompressor.COMPRESSED_OVERHEAD];
        int compressedSize = LZOCompressor.compress(input, 0, input.length, output, 0, output.length, compressionLevel);

        File compressedFile = new File(filePath + ".lzo");
        FileOutputStream fos = new FileOutputStream(compressedFile);
        fos.write(output, 0, compressedSize);
        fos.close();

        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] md5hash = md.digest(output, 0, compressedSize);

        return new BigInteger(1, md5hash).toString(16);

    } catch (Exception e) {
        throw new RuntimeException("Error compressing file: " + e.getMessage());
    }
}
```

