import akka.actor.ActorRef;
import akka.actor.ActorSystem;
import akka.actor.Props;
import akka.net.tcp.Tcp;
import akka.net.tcp.TcpMessage;
import akka.pattern.After;
import akka.util.Timeout;

public class DiscoveryActor {
    private final ActorRef self;
    private final ActorRef listener;
    private final int port;
    private final InetSocketAddress remote;

    public DiscoveryActor(ActorRef listener, int port) {
        this.self = this;
        this.listener = listener;
        this.port = port;
        this.remote = new InetSocketAddress("192.168.1.1", 44444); // Replace with the remote address

        final ActorSystem system = ActorSystem.create("DiscoverySystem");
        final ActorRef tcp = Tcp.get(system).manager();
        final List<Inet.SocketOption> options = new ArrayList<>();

        tcp.tell(TcpMessage.connect(remote, null, options, new FiniteDuration(CONNECT_TIMEOUT, TimeUnit.SECONDS), false), self);

        After.create(system.scheduler().schedule(Duration.Zero(), Duration.Inf(), self, new DiscoveryMessage()), Duration.Inf())
                .onComplete(() -> system.terminate(), system.dispatcher());
    }

    public static Props props(ActorRef listener, int port) {
        return Props.create(DiscoveryActor.class, () -> new DiscoveryActor(listener, port));
    }

    private record DiscoveryMessage() {}
}
