import java.io.*;

public class ProcessInstanceSerializer {

    private long id;
    private ProcessInstance processInstance;

    public ProcessInstanceSerializer(ProcessInstance processInstance, long id) {
        this.processInstance = processInstance;
        this.id = id;
    }

    public void serialize(OutputStream outputStream) throws IOException {
        ObjectOutputStream output = new ObjectOutputStream(outputStream);
        output.writeLong(id);
        output.writeObject(processInstance);
        output.close();
    }

    public ProcessInstance deserialize(InputStream inputStream) throws IOException, ClassNotFoundException {
        ObjectInputStream input = new ObjectInputStream(inputStream);
        long deserializedId = input.readLong();
        ProcessInstance deserializedProcessInstance = (ProcessInstance) input.readObject();

        if (deserializedId != id) {
            throw new RuntimeException("Deserialized object's ID does not match the original object's ID.");
        }

        input.close();
        return deserializedProcessInstance;
    }
}
