import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.lang.reflect.InvocationTargetException;
import java.util.List;

public class Runner {
    public static class RunResults {
        public StringBuilder output = new StringBuilder();
        public StringBuilder error = new StringBuilder();
        public Throwable runException;
        public int exitCode;
    }

    public static RunResults executeCommand(List<String> command, String workingDirectory) {
        RunResults runResults = new RunResults();
        ProcessBuilder processBuilder = new ProcessBuilder();
        try {
            processBuilder.command(command);
            processBuilder.directory(new File(workingDirectory));
            processBuilder.redirectErrorStream(true);

            Process process = processBuilder.start();
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            String errorLine;
            while ((errorLine = errorReader.readLine()) != null) {
                runResults.error.append(errorLine).append("\n");
            }

            int exitValue = process.waitFor().exitValue();
            runResults.exitCode = exitValue;

            if (exitValue != 0) {
                throw new RuntimeException("Process failed with exit code: " + exitValue);
            }
        } catch (IOException | InterruptedException | InstantiationException
                | IllegalAccessException | InvocationTargetException e) {
            runResults.runException = e;
        }

        return runResults;
    }

    public static void main(String[] args) {
        List<String> command = List.of("cmd", "/c", "echo", "Hello, World!");
        RunResults result = executeCommand(command, null);
        System.out.println("Output: " + result.output);
        System.out.println("Error: " + result.error);
        if (result.runException != null) {
            System.err.println("Error: " + result.runException.getMessage());
        }
    }
}

public class Watchdog implements Runnable {
    private final Process process;

    public Watchdog(Process process) {
        this.process = process;
    }

    @Override
    public void run() {
        try {
            process.exitValue();
        } catch (IllegalThreadStateException e) {
            System.err.println("Process is still running. Exiting...");
            process.destroy();
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        List<String> command = List.of("cmd", "/c", "java", "Runner");
        Process process = Runtime.getRuntime().exec(command.toArray(String[]::new), null, null);
        new Thread(new Watchdog(process)).start();
        Runner.executeCommand(command, null).join();
    }
}
