import java.io.IOException;
import java.io.ObjectInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public static WalkMap readFileAndCreateMap(String filePath) {
    File file = new File(filePath);
    String extension = getFileExtension(filePath);

    WalkMap map = null;

    if (!file.exists()) {
        System.err.println("File does not exist: " + filePath);
        return null;
    }

    try {
        if (extension.equalsIgnoreCase(".objv")) {
            map = new ViewMap();
        } else if (extension.equalsIgnoreCase(".objp")) {
            map = new PathsMap();
        } else if (extension.equalsIgnoreCase(".jrd3m")) {
            FileInputStream inputStream = new FileInputStream(file);
            ObjectInputStream objectInputStream = new ObjectInputStream(inputStream);
            map = (WalkMap) objectInputStream.readObject();
            objectInputStream.close();
            inputStream.close();
        } else {
            System.err.println("Invalid file extension: " + filePath);
            return null;
        }

        byte[] fileContent = Files.readAllBytes(Paths.get(filePath));
        // Add file content processing here if needed

    } catch (IOException | ClassNotFoundException e) {
        System.err.println("Error reading file or creating WalkMap: " + filePath);
        e.printStackTrace();
        return null;
    }

    return map;
}

private static String getFileExtension(String filePath) {
