import java.io.*;

public static <T> T[] readObjectsFromFile(String path, Class<T> clazz) {
    ObjectInputStream ois = null;
    try {
        FileInputStream fis = new FileInputStream(path);
        ois = new ObjectInputStream(fis);
        int size = ((DataInputStream) new BufferedDataInputStream(new FileInputStream(path))).readInt();
        T[] array = (T[]) Array.newInstance(clazz, size);
        for (int i = 0; i < size; i++) {
            array[i] = (T) ois.readObject();
        }
        ois.close();
        return array;
    } catch (IOException | ClassNotFoundException e) {
        logger.warning("在从" + path + "读取对象数组时发生异常" + e);
    }

    return null;
}
