import javax.xml.parsers.ParserConfigurationException;
import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;

public class DataExtractor {

    public static void main(String[] args) {
        try {
            for (String file : args) {
                if (file.endsWith(".xml")) {
                    extractXmlData(file);
                } else if (file.endsWith(".db")) {
                    extractSqlData(file);
                } else {
                    System.err.println("Invalid file format: " + file);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void extractXmlData(String file) throws IOException, ParserConfigurationException, SAXException {
        SAXParserFactory spf = SAXParserFactory.newInstance();
        SAXParser p = spf.newSAXParser();

        XmlHandler fh = new XmlHandler();
        p.parse(new File(file), fh);

        System.out.println("XML Data:");
        fh.printData();
    }

    private static void extractSqlData(String file) throws SQLException, IOException {
        String url = "jdbc:file:" + file;
        Connection conn = DriverManager.getConnection(url);

        Statement stmt = conn.createStatement();
        ResultSet rs = stmt.executeQuery("SELECT * FROM data");

        System.out.println("SQL Data:");
        while (rs.next()) {
            for (int i = 1; i <= rs.getMetaData().getColumnCount(); i++) {
                System.out.print(rs.getMetaData().getColumnName(i) + ": " + rs.getObject(i) + "\t");
            }
            System.out.println();
        }

        conn.close();
    }
}

