import org.xml.sax.Attributes;
import org.xml.sax.SAXException;
import org.xml.sax.helpers.DefaultHandler;

import java.io.File;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class SaxParserPrefixExtractor {

    public static void main(String[] args) throws Exception {
        SAXParserFactory factory = SAXParserFactory.newInstance();
        SAXParser saxParser = factory.newSAXParser();
        FrequencyHandler handler = new FrequencyHandler();

        for (String file : args) {
            saxParser.parse(new File(file), handler);
        }

        handler.printPrefixesAndFrequencies();
    }

    static class FrequencyHandler extends DefaultHandler {
        private Map<String, Integer> prefixFrequencies = new HashMap<>();
        private List<String> prefixes = new ArrayList<>();

        @Override
        public void startElement(String uri, String localName, String qName, Attributes attributes) throws SAXException {
            String prefix = "";
            if (qName != null && qName.indexOf(":") > -1) {
                prefix = qName.substring(0, qName.indexOf(":"));
            }
            if (prefix.length() > 0) {
                prefixes.add(prefix);
                Integer currentFrequency = prefixFrequencies.get(prefix);
                if (currentFrequency == null) {
                    prefixFrequencies.put(prefix, 1);
                } else {
                    prefixFrequencies.put(prefix, currentFrequency + 1);
                }
            }
        }

        public void printPrefixesAndFrequencies() {
            System.out.println("Prefixes and their frequencies:");
            for (Map.Entry<String, Integer> entry : prefixFrequencies.entrySet()) {
                System.out.println(entry.getKey() + " : " + entry.getValue());
            }
        }
    }
}
