            if (responseCode != 200) {
                throw new RuntimeException("Failed to send device data to server: HTTP error code " + responseCode);
            }

            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String response = reader.readLine();
            reader.close();

