import java.io.*;

public Object serializeAndDeserialize(Object objectToSerialize, Object parentObject) throws IOException, ClassNotFoundException {
    ByteArrayOutputStream bos = new ByteArrayOutputStream();
    ObjectOutputStream oos = new ObjectOutputStream(bos);

    try {
        oos.writeObject(objectToSerialize);
        oos.flush();
        oos.reset(); // Reset the output stream

        ByteArrayInputStream bis = new ByteArrayInputStream(bos.toByteArray());
        Object deserializedObject = new ObjectInputStream(bis).readObject();

        return deserializedObject;
    } catch (IOException e) {
        System.out.println("IOException while trying to serialize and deserialize object: " + parentObject);
        e.printStackTrace();
    } catch (ClassNotFoundException e) {
        System.out.println("ClassNotFoundException while trying to deserialize object: " + parentObject);
        e.printStackTrace();
    } finally {
        oos.close();
        bos.close();
        bis.close();
    }
}
