import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.encoding.Base64Encoder;
import java.security.SecureRandom;
import java.security.NoSuchAlgorithmException;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.InvalidAlgorithmParameterException;
import java.security.InvalidKeyException;
import java.security.UnsupportedEncodingException;
import java.security.Key;
import java.util.Random;

public class EncryptionUtil {
    private Cipher cipher;
    private Base64Encoder base64;

    public String encryptBlowfish(String data, String secretKey, String iv) {
        try {
            if (base64 == null) {
                KeyGenerator keyGen = KeyGenerator.getInstance("Blowfish");
                keyGen.init(128);
                SecretKey secret = keyGen.generateKey();

                if (secretKey != null && !secretKey.isEmpty()) {
                    secret = new SecretKeySpec(secretKey.getBytes(), "Blowfish");
                }

                cipher = Cipher.getInstance("Blowfish/CBC/PKCS5Padding");

                if (iv == null || iv.isEmpty()) {
                    iv = generateRandomIV();
                }

                cipher.init(Cipher.ENCRYPT_MODE, secret, new IvParameterSpec(iv.getBytes()));

                base64 = new Base64Encoder();
            }

            return base64.encodeToString(cipher.doFinal(data.getBytes()));
        } catch (NoSuchAlgorithmException | NoSuchPaddingException | InvalidKeyException
                | InvalidAlgorithmParameterException | UnsupportedEncodingException ex) {
            throw new RuntimeException(ex);
        }
    }

    private String generateRandomIV() {
        byte[] iv = new byte[Cipher.getBlockSize("Blowfish")];
        new SecureRandom().nextBytes(iv);
        return bytesToHex(iv);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            result.append(String.format("%02x", b));
        }
        return result.toString();
    }
}
