import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.InvocationTargetException;
import java.time.ZonedDateTime;
import java.util.Optional;
import java.util.TimeUnit;
import java.util.concurrent.TimeUnit;

public int executeCommand(String[] cmdArray, InputStream input, OutputStream output, Optional<Long> timeout) {
    Process process;
    try {
        process = Runtime.getRuntime().exec(cmdArray);
    } catch (IOException e) {
        logger.warn("An error occurred while executing command: {}", e.getMessage());
        return -1;
    }

    int exitValue = 0;
    try {
        if (input != null) {
            input.transferTo(process.getInputStream());
        }

        if (output != null) {
            process.redirectErrorStream(output);
        }

        if (timeout.isPresent()) {
            boolean processFinished = process.waitFor((int) timeout.get(), TimeUnit.MILLISECONDS);
            if (!processFinished) {
                process.destroy();
                return -2;
            }
        }

        exitValue = process.exitValue();
    } catch (InterruptedException | IOException e) {
        logger.warn("An error occurred while executing command: {}", e.getMessage());
        process.destroy();
        return -3;
    } catch (InvocationTargetException e) {
        logger.warn("An error occurred while executing command: {}", e.getCause().getMessage());
        process.destroy();
        return -4;
    }

    return exitValue;
}
