import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5Filter implements FilterInterface {
    private int frequency;
    private byte[] filteredData;

    public MD5Filter(int frequency) {
        this.frequency = frequency;
    }

    @Override
    public byte[] filter(byte[] inputData) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            md.update(inputData);
            byte[] digest = md.digest();
            int hashCode = bytesToInt(digest);
            if ((hashCode % frequency) == 0) {
                this.filteredData = digest;
            }
            return this.filteredData;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private int bytesToInt(byte[] bytes) {
        int result = 0;
        for (byte b : bytes) {
            result = (result << 8) | (b & 0xFF);
        }
        return result;
    }
}

