import java.io.File;
import java.nio.file.Paths;
import javax.swing.tree.TreePath;
import javax.swing.JOptionPane;

public class FileOpener {

    public static void openFileOrDirectory(TreePath[] paths) {
        if (paths == null) {
            return;
        }

        for (TreePath path : paths) {
            Object lastPathComponent = path.getLastPathComponent();
            if (lastPathComponent instanceof File) {
                File file = (File) lastPathComponent;
                if (file.isFile()) {
                    String osName = System.getProperty("os.name").toLowerCase();
                    if (osName.contains("windows")) {
                        String cmd = "rundll32.exe url.dll,FileProtocolHandler " + file.getCanonicalPath();
                        try {
                            Runtime.getRuntime().exec(cmd);
                        } catch (Exception e) {
                            showErrorMessage("Error opening file: " + e.getMessage());
                        }
                    } else if (osName.contains("mac") || osName.contains("linux")) {
                        try {
                            Desktop.getDesktop().open(Paths.get(file.getCanonicalPath()).toFile());
                        } catch (Exception e) {
                            showErrorMessage("Error opening file: " + e.getMessage());
                        }
                    }
                } else if (file.isDirectory()) {
                    if (osName.contains("windows")) {
                        String cmd = "explorer " + file.getCanonicalPath();
                        try {
                            Runtime.getRuntime().exec(cmd);
                        } catch (Exception e) {
                            showErrorMessage("Error opening directory: " + e.getMessage());
                        }
                    } else {
                        try {
                            Desktop.getDesktop().open(Paths.get(file.getCanonicalPath()).toFile());
                        } catch (Exception e) {
                            showErrorMessage("Error opening directory: " + e.getMessage());
                        }
                    }
                }
            }
        }
    }

    private static void showErrorMessage(String message) {
        JOptionPane.showMessageDialog(null, message, "Error", JOptionPane.ERROR_MESSAGE);
    }
}
