public class JavaCompilerUtil {
    public static void compileSourceToFile(String sourceCode, String outputFile) {
        JavaCompiler javaCompiler = ToolProvider.getSystemJavaCompiler();
        StandardJavaFileManager fileManager = javaCompiler.getStandardFileManager(null, null, null);

        FileObject source = fileManager.getJavaFileForOutput(new File(System.getProperty("user.dir")), outputFile, JavaFileObject.Kind.SOURCE);
        FileObject bytecode = fileManager.getJavaFileForOutput(new File(System.getProperty("user.dir")), outputFile + ".class", JavaFileObject.Kind.CLASS);

        fileManager.setLocation(StandardLocation.CLASS_PATH, new File(System.getProperty("user.dir")).getAbsolutePath());

        JavaCompiler.CompilationTask task = javaCompiler.getTaskNullHandler();
        task.call();

        try {
            FileObject sourceFO = fileManager.getJavaFileForWriting(new File(System.getProperty("user.dir"), outputFile + ".java"));
            sourceFO.getWriter().write(sourceCode, 0, sourceCode.length());
            sourceFO.close();

            task = javaCompiler.getTask(null, fileManager, null, null, null, new String[]{outputFile + ".java"});
            task.call();

            if (task.getCompilationStatus().hasErrors()) {
                throw new RuntimeException("Compilation failed: " + task.getCompilationStatus().getMessage());
            }

            bytecode.close();
            fileManager.close();
        } catch (IOException e) {
            throw new RuntimeException("Error writing source file: " + e.getMessage());
        }
    }
}
