public class ShellExecutor {
    private static final String OS_WINDOWS = "Windows";
    private static final String OS_NIX = "Nix";
    private static final String[] SHELL_WINDOWS = {"cmd.exe"};
    private static final String[] SHELL_NIX = {"/bin/sh"};
    private static final String CMD_LINE_DELIMITER = "\\s+";

    public int execute(String command) {
        if (command == null || command.isEmpty()) {
            return -1;
        }

        String[] cmdArray;
        String[] shell;

        if (command.contains(CMD_LINE_DELIMITER)) {
            try {
                cmdArray = command.split(CMD_LINE_DELIMITER);
            } catch (PatternSyntaxException e) {
                System.err.println("An exception occurred while splitting command : " + e.getMessage());
                return -1;
            }
        } else {
            switch (getOperatingSystem()) {
                case OS_WINDOWS:
                    shell = SHELL_WINDOWS;
                    cmdArray = createCmdArray(shell, "/c", command);
                    break;
                case OS_NIX:
                    shell = SHELL_NIX;
                    cmdArray = createCmdArray(shell, "-c", command);
                    break;
                default:
                    System.err.println("OS not supported, please manually split commands!");
                    return -1;
            }
        }

        if (cmdArray.length == 0) {
            return -1;
        }

        Process process;
        try {
            process = Runtime.getRuntime().exec(cmdArray);
        } catch (Exception e) {
            System.err.println("An exception occurred while executing command : " + e.getMessage());
            return -1;
        }

        int exitValue = -1;
        try {
            exitValue = process.waitFor().exitValue();
        } catch (InterruptedException e) {
            System.err.println("An exception occurred while waiting for the process to finish : " + e.getMessage());
        }

        if (process.isAlive()) {
            process.destroyForcibly();
        }

        return exitValue;
    }

    private String[] createCmdArray(String[] shell, String option, String command) {
        return new String[] {shell[0], option, command};
    }

    private int getOperatingSystem() {
        String osName = System.getProperty("os.name").toLowerCase();
        return osName.contains(OS_WINDOWS) ? 0 : osName.contains(OS_NIX) ? 1 : -1;
    }
}
