import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.FileEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

public static String uploadFile(String serverUrl, String filePath) {
    CloseableHttpClient httpClient = HttpClients.createDefault();
    HttpPost httpPost = new HttpPost(serverUrl);
    FileEntity fileEntity = new FileEntity(new File(filePath), ContentType.create("application/octet-stream"));

    int retries = 0;
    while (retries < 3) {
        try {
            httpPost.setEntity(fileEntity);
            httpPost.setHeader("Accept", "application/json");
            httpPost.setHeader("Connection", "keep-alive");

            HttpResponse response = httpClient.execute(httpPost);
            if (response.getStatusLine().getStatusCode() == 200) {
                EntityUtils.consume(response.getEntity());
                return "File uploaded successfully.";
            } else {
                String errorMessage = EntityUtils.toString(response.getEntity());
                System.out.println("Upload failed with status code " + response.getStatusLine().getStatusCode() + ". Error message: " + errorMessage);
                retries++;
                if (retries < 3) {
                    Thread.sleep(1000 * 5); // wait 5 seconds before retrying
                }
            }
        } catch (IOException e) {
            System.out.println("Error during file upload: " + e.getMessage());
            retries++;
            if (retries < 3) {
                Thread.sleep(1000 * 5); // wait 5 seconds before retrying
            }
        } finally {
            try {
                httpPost.releaseConnection();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    return "File upload failed after 3 attempts.";
}
