import org.apache.http.client.CredentialsProvider;
import org.apache.http.client.config.RequestConfig;
import org.apache.http.conn.socket.ConnectionSocketFactory;
import org.apache.http.conn.socket.PlainConnectionSocketFactory;
import org.apache.http.conn.socket.SSLConnectionSocketFactory;
import org.apache.http.impl.client.BasicCredentialsProvider;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClientBuilder;
import org.apache.http.impl.conn.SystemDefaultProxyRoutePlanner;
import org.apache.http.util.EntityUtils;

public class JavaHttpClientProxyExample {

    public static void main(String[] args) throws Exception {
        String url = "http://example.com";
        String proxyHost = "proxy.example.com";
        int proxyPort = 8080;
        String username = "proxy_user";
        String password = "proxy_password";

        // Create a custom RequestConfig
        RequestConfig requestConfig = RequestConfig.custom()
                .setProxy(new HttpRoute(new HttpHost(proxyHost, proxyPort)))
                .build();

        // Create a Registry and register the factories
        Registry registry = RegistryBuilder.newInstance()
                .register("http", PlainConnectionSocketFactory.getSocketFactory())
                .register("https", SSLConnectionSocketFactory.getSocketFactory())
                .build();

        // Create a CredentialsProvider
        CredentialsProvider credentialsProvider = new BasicCredentialsProvider();
        credentialsProvider.setCredentials(new AuthScope(proxyHost, proxyPort), new UsernamePasswordCredentials(username, password));

        // Create an HttpClientBuilder and configure it
        HttpClientBuilder httpClientBuilder = HttpClientBuilder.create()
                .setDefaultProxy(new HttpHost(proxyHost, proxyPort))
                .setDefaultCredentialsProvider(credentialsProvider)
                .setRegistry(registry)
                .setRequestConfig(requestConfig)
                .setSSLHostnameVerifier(NoopHostnameVerifier.INSTANCE);

        // Create a CloseableHttpClient
        CloseableHttpClient httpClient = httpClientBuilder.build();

        // Create a GET request
        HttpGet httpGet = new HttpGet(url);

        // Execute the GET request and retrieve the response entity
        try (CloseableHttpResponse response = httpClient.execute(httpGet)) {
            if (response.getStatusLine().getStatusCode() == 200) {
                String responseBody = EntityUtils.toString(response.getEntity());
                System.out.println(responseBody);
            }
        }

        // Close the resources
        httpClient.close();
    }
}
