public class CommandExecutor {

    private static final String WINDOWS_SHELL = "cmd.exe";

    public static Process executeCommand(String command) throws IOException {
        List<String> args = new ArrayList<>();
        args.add(WINDOWS_SHELL);
        args.add("/c");
        args.add(escapeShellCommand(command));

        Process process = Runtime.getRuntime().exec(args.toArray(new String[0]));

        return process;
    }

    private static String escapeShellCommand(String command) {
        StringBuilder sb = new StringBuilder();
        int index = 0;

        while (index < command.length()) {
            char c = command.charAt(index);

            if (c == '^') {
                if (index + 1 < command.length()) {
                    char next = command.charAt(index + 1);
                    switch (next) {
                        case '(':
                        case ')':
                        case '&':
                        case '|':
                        case '<':
                        case '>':
                        case '`':
                            sb.append("^");
                            sb.append(next);
                            index++;
                            break;
                        default:
                            throw new IllegalArgumentException("Invalid shell escape character: " + next);
                    }
                    index++;
                } else {
                    throw new IllegalArgumentException("Invalid shell escape sequence: '^'");
                }
            } else {
                switch (c) {
                    case '"':
                        sb.append("\\");
                        sb.append(c);
                        break;
                    case '\\':
                        sb.append("\\");
                        sb.append(c);
                        break;
                    default:
                        sb.append(c);
                }
            }

            index++;
        }

        return sb.toString();
    }

