import java.util.HashMap;
import java.util.List;

public class Graph {
    private int numVertices;
    private int numEdges;
    private List<VertexBuilder> vertexBuilders;
    private HashMap<Edge, Integer> edgeHash; // Edge caching

    public Graph(List<VertexBuilder> vertexBuilders) {
        this.vertexBuilders = vertexBuilders;
        this.numVertices = getNumVertices();
        this.numEdges = 0;
        this.edgeHash = new HashMap<>();
    }

    private int getNumVertices() {
        int numVertices = 0;
        for (VertexBuilder vertexBuilder : vertexBuilders) {
            numVertices += vertexBuilder.build().getId();
        }
        return numVertices;
    }

    public void addEdges() {
        for (int i = 0; i < vertexBuilders.size(); i++) {
            VertexBuilder vertexBuilder1 = vertexBuilders.get(i);
            Vertex vertex1 = vertexBuilder1.build();

            for (int j = i + 1; j < vertexBuilders.size(); j++) {
                VertexBuilder vertexBuilder2 = vertexBuilders.get(j);
                Vertex vertex2 = vertexBuilder2.build();

                if (!edgeExists(vertex1, vertex2)) {
                    addEdge(vertex1, vertex2);
                }
            }
        }
    }

    private boolean edgeExists(Vertex vertex1, Vertex vertex2) {
        Edge edge = new Edge(vertex1, vertex2);
        return edgeHash.containsKey(edge);
    }

    private void addEdge(Vertex vertex1, Vertex vertex2) {
        Edge edge = new Edge(vertex1, vertex2);
        this.numEdges++;
        edgeHash.put(edge, this.numEdges);
        // Add edge to the adjacency list here
    }

    private static class Vertex {
        private int id;

        public Vertex(int id) {
            this.id = id;
        }

        public int getId() {
            return id;
        }
    }

    private static class Edge {
        private Vertex vertex1;
        private Vertex vertex2;

        public Edge(Vertex vertex1, Vertex vertex2) {
            this.vertex1 = vertex1;
            this.vertex2 = vertex2;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Edge)) return false;
            Edge edge = (Edge) o;
            return vertex1.equals(edge.vertex1) && vertex2.equals(edge.vertex2);
        }

        @Override
        public int hashCode() {
            int result = vertex1.hashCode();
            result = 31 * result + vertex2.hashCode();
            return result;
        }
    }
}
