import org.apache.commons.codec.digest.DigestUtils;
import java.util.ArrayList;
import java.util.List;

public class MD5HashGenerator {

    public static String generateMD5Hash(List<String> inputStrings, List<String> serverGroups) {
        String concatenatedStrings = String.join("", inputStrings);
        String md5Hash = DigestUtils.md5Hex(concatenatedStrings.getBytes());
        boolean serverGroupExists = false;
