import java.time.DateTimeException;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

public class MergedInterval {
    public static String mergeSegments(List<LocalDateTime> segments) {
        if (segments == null || segments.isEmpty()) {
            throw new IllegalArgumentException("List cannot be empty");
        }

        LocalDateTime start = segments.get(0);
        LocalDateTime end = start;

        for (LocalDateTime segment : segments.subList(1, segments.size())) {
            if (end.isAfter(segment)) {
                end = end.plus(LocalDateTime.of(0, 1, 0).until(segment));
            } else {
                start = segment;
            }
        }

        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
        return formatter.format(start) + "-" + formatter.format(end);
    }
}
