public byte[] generateAESKey(int keySize, String paddingScheme) {
    KeyGenerator keygen = null;
    try {
        keygen = KeyGenerator.getInstance("AES");
        keygen.init(keySize);
        byte[] aesKey = keygen.generateKey().getEncoded();

        Cipher cipher = null;
