import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.spec.KeySpec;
import java.util.Arrays;

public class MGF1 {

    private Mac mac;

    public MGF1(String algorithm) throws NoSuchAlgorithmException {
        KeySpec keySpec = new SecretKeySpec("seed".getBytes(), algorithm);
        this.mac = Mac.getInstance(algorithm);
        this.mac.init(keySpec);
    }

    public byte[] generateMask(byte[] seed, int maskLength) throws NoSuchAlgorithmException, InvalidKeyException {
        byte[] mask = new byte[maskLength];
        byte[] paddedSeed = Arrays.copyOf(seed, seed.length + 1);
        paddedSeed[seed.length] = (byte) maskLength;

        for (int i = 0; i < maskLength; i++) {
            mac.update(paddedSeed);
            mask[i] = mac.doFinal()[0];
            mac.reset();
        }

        return mask;
    }
}
```

