    public static string GetHashedString(string input, string namespaceName)
    {
        // Hash the input string using SHA-1
        using (SHA1 sha = SHA1.Create())
        {
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hash = sha.ComputeHash(inputBytes);

            // Hash the namespace name using SHA-1
            using (SHA1 shaForNamespace = SHA1.Create())
            {
                byte[] namespaceBytes = Encoding.ASCII.GetBytes(namespaceName);
                byte[] namespaceHash = shaForNamespace.ComputeHash(namespaceBytes);

