                Buffer.BlockCopy(namespaceHash, 0, combinedHash, 0, namespaceHash.Length);
                Buffer.BlockCopy(hash, 0, combinedHash, namespaceHash.Length, hash.Length);

                // Convert the combined hash to a string
                string hashedString = BitConverter.ToString(combinedHash).Replace("-", "");

                return $"prefix:{namespaceName}:{hashedString}";
