import java.io.IOException;
import java.io.PrintWriter;

import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

@WebServlet("/FileReaderServlet")
public class FileReaderServlet extends HttpServlet {

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String configFilePath = "path/to/config/file.properties";
        String contentType = "text/plain";

        try (PrintWriter out = response.getWriter()) {
            File configFile = new File(configFilePath);
            if (configFile.exists()) {
                FileInputStream fis = new FileInputStream(configFile);
                byte[] buffer = new byte[8192];
                int count;

                response.setContentType(contentType);

                while ((count = fis.read(buffer)) > 0) {
                    out.write(buffer, 0, count);
                }

                out.flush();
                fis.close();
            } else {
                response.sendError(404);
                out.println("Error: Configuration file not found.");
                logError("Configuration file not found.", request);
            }
        } catch (FileNotFoundException e) {
            response.sendError(500);
            response.getWriter().println("Error: Failed to read configuration file.");
            logError("Error reading configuration file: " + e.getMessage(), request);
        } catch (IOException e) {
            response.sendError(500);
            response.getWriter().println("Error: Failed to read configuration file.");
            logError("Error reading configuration file: " + e.getMessage(), request);
        }
