function checkFilesAndDirsExist() {
  const fs = require("fs");

  function checkFileOrDir(path) {
    try {
      return fs.statSync(path).isDirectory();
    } catch (error) {
      if (error.code === "ENOENT") {
        return false;
      }
      throw error;
    }
  }

  function checkFilesAndDirsExistRecursive(dirPath, filesToCheck, dirsToCheck) {
    const files = fs.readdirSync(dirPath);
    for (const file of files) {
      if (filesToCheck.includes(file)) {
        return false;
      }

      if (!checkFileOrDir(path.join(dirPath, file))) {
