function traverseDirectoryTree(fileSystemObject, directoryPath, options) {
  const { createDirectories } = options;

  function validateFileAndDirectory(path) {
    try {
      const stats = fs.lstatSync(path);
      if (stats.isDirectory()) {
        return true;
      }
    } catch (err) {
      if (createDirectories && err.code === 'ENOENT') {
        const parentDir = path.split('/').slice(0, -1).join('/');
        fs.mkdirSync(parentDir, { recursive: true });
        return true;
      }
    }

    return false;
  }

  function traverseDirectoryTreeRecursive(path) {
    if (!validateFileAndDirectory(path)) {
      throw new Error(`Invalid directory or file: ${path}`);
    }

    const files = fs.readdirSync(path);
    for (const file of files) {
      const filePath = path + '/' + file;
      validateFileAndDirectory(filePath);
      if (fs.lstatSync(filePath).isDirectory()) {
        traverseDirectoryTreeRecursive(filePath);
      }
    }
  }

  try {
    const stats = fs.lstatSync(directoryPath);
    if (!stats.isDirectory()) {
      throw new Error(`Invalid directory: ${directoryPath}`);
    }

    traverseDirectoryTreeRecursive(directoryPath);
    return true;
  } catch (err) {
    console.error(err);
    return false;
  }
}
