function compileLess(dir) {
  // Check if dir is a directory and skip it if it is
  if (fs.lstatSync(dir).isDirectory()) return;

  // Compile Less files to CSS files using the file path and name
  var compiledCssFiles = {};
  fs.readdirSync(dir).forEach(function(file) {
    var lessFilePath = dir + "/" + file;
    if (fs.lstatSync(lessFilePath).isDirectory()) return;

    var cssFilePath = lessFilePath.replace(".less", ".css");
    compiledCssFiles[cssFilePath] = [lessFilePath];
  });

  // Return an object with the compiled CSS files as keys and the Less file paths as values
  return compiledCssFiles;
}

