function existsInDirTree(dirPath, fileNames) {
  const fs = require('fs');
  
  function recurseDirectory(path, fileNames) {
    const files = fs.readdirSync(path);
    for (const fileName of files) {
      if (fileNames.includes(fileName)) return true;
    }
    for (const subDir of files) {
      if (recurseDirectory(`${path}/${subDir}`, fileNames)) return true;
    }
  }

  const result = recurseDirectory(dirPath, fileNames);
  return result ? true : false;
}
