function reformatString(str) {
  // Collapse multiple white space (' ' and '\n') to one.
  str = str.replace(/[\s\n]+/g, " ");

  // Remove trailing space.
  str = str.trim();

  // Optimize format of numbers:
  const regex = /(\d+\.\d+|\d+)/g;
  let matches;
  while ((matches = regex.exec(str)) !== null) {
    const match = matches[0];
    if (match.includes(".")) {
      // Remove trailing zeros and decimal point.
      str = str.replace(new RegExp(`${match}\\.?0+`), `${match}`);
    }
  }

  // Collapse '-0' to '0'.
  str = str.replace(/-0/g, "");

  return str;
}
