function checkCSSFile(filePath) {
  const fse = require('fse');
  let css;
  try {
    css = fse.readFileSync(filePath).toString();
  } catch (err) {
    console.error("Error reading CSS file: " + err.message);
    return false;
  }
  if (!css.includes("<%=")) {
    lintCSS(css);
  }
  return true;
}

function checkJavaScriptFile(filePath) {
  const fse = require('fse');
  try {
    let js = fse.readFileSync(filePath).toString();
    if (!js.includes("sprite.png")) {
      return false;
    }
  } catch (err) {
    console.error("Error reading JavaScript file: " + err.message);
    return false;
  }
  return true;
}

