function decodeActiveSyncCodepage(wbxmlString) {
  const wbxml = require('wbxml');
  const activeSyncCodepages = require('activesync/codepages');

  // Parse the WBXML document using the activeSyncCodepages library
  const parsedWbxml = wbxml.parse(wbxmlString, { codepages: activeSyncCodepages });

  // Extract the data from the decoded WBXML document
  const data = {};
  for (const tag of parsedWbxml) {
    if (tag.tagName === 'data') {
      const key = tag.attributes['key'];
      const value = tag.textContent;
      data[key] = value;
    }
  }

  return data;
}
