function prepareResponse(directoryPath, fileName, callback) {
  // Check if file exists
  if (fileExists(fileName)) {
    // Fill template with data from file
    var data = getDataFromFile(fileName);
    var template = getTemplate(directoryPath + "/" + fileName);
    var renderedTemplate = fillTemplateWithData(template, data);
    // Send response to client
    sendResponse(renderedTemplate, callback);
  } else {
    // Callback with error message if file does not exist
    callback("File does not exist.");
  }
}

function fileExists(fileName) {
  return fs.existsSync(fileName);
}

function getDataFromFile(fileName) {
  var data = JSON.parse(fs.readFileSync(fileName));
  return data;
}

function getTemplate(templatePath) {
  var template = fs.readFileSync(templatePath, "utf8");
  return template;
}

function fillTemplateWithData(template, data) {
  var renderedTemplate = Mustache.render(template, data);
  return renderedTemplate;
}

function sendResponse(response, callback) {
  // Send response to client
  callback(null, response);
}

