const fs = require('fs');

function removeFileIfExistsAndWait(filePath) {
  return new Promise((resolve, reject) => {
    fs.access(filePath, (err) => {
      if (err) {
        // file doesn't exist, resolve immediately
        resolve();
      } else {
        // file exists, remove it and wait for the operation to complete
        fs.unlink(filePath, (err) => {
          if (err) {
            reject(err);
          } else {
            resolve();
          }
        });
      }
    });
  });
}
