#!/usr/bin/env node

const fs = require('fs-extra');
const child_process = require('child_process');

const pkgName = process.argv[2];

if (!pkgName) {
  console.log("Please provide a package name");
  return;
}

// create the directory structure
const distDir = `./dist/${pkgName}`;
fs.ensureDirSync(distDir);
fs.mkdirsSync(`${distDir}/DEBIAN`);

// write the debian control file
copyAndReplace('./packaging/DEBIAN/control', `${distDir}/DEBIAN/control`, pkgName, '{{arch}}');

// build .deb packages
console.log(`Building ${pkgName}.deb`);
child_process.execSync(`dpkg-deb --build ${pkgName}`, { cwd: './dist' });

// can we make rpm packages?
child_process.exec('which rpmbuild', function(err, stdout, stderr) {
  if (err || stdout == '') {
    console.log("Cannot find rpmbuild, skipping building Red Hat package");
    return;
  }

  // write the spec file
  copyAndReplace('./packaging/rpmbuild/${pkgName}.spec', `${distDir}/${pkgName}.spec`, pkgName);

  // build .rpm packages
  console.log(`Building ${pkgName}.rpm`);
  child_process.execSync(`rpmbuild -bb ${pkgName}.spec`, { cwd: './dist' });
});

function copyAndReplace(src, dest, pkgName, arch) {
  const content = fs.readFileSync(src).toString();
  const replacedContent = content.replace('{{pkgname}}', pkgName).replace('{{arch}}', arch);
  fs.writeFileSync(dest, replacedContent);
}

