function getTimeZoneRegex(pattern, timeZone) {
    // Check if pattern is a valid time zone format
    if (!isValidTimeZoneFormat(pattern)) {
        throw new Error("Invalid time zone format");
    }
    
    // Parse the pattern and extract the time zone name
    var genericTzName = dateGetTimeZoneName(length, "generic", timeZone, cldr);
    if (!genericTzName) {
        throw new Error("Invalid time zone");
    }
    
    // Return a regular expression that matches the time zone name
    return new RegExp("^" + regexpEscape(looseMatching(genericTzName)));
}

function isValidTimeZoneFormat(pattern) {
    // Check if pattern is in the format "Pacific Time" or "America/Los_Angeles"
    return /^(Pacific|America)\/[A-Za-z]+(_[A-Za-z]+)?$/.test(pattern);
}

function dateGetTimeZoneName(length, type, timeZone, cldr) {
    // Get the time zone name from the CLDR data
    var tzNames = cldr.get("supplemental", "timezoneData", "metaZones");
    return tzNames[type][timeZone];
}

function looseMatching(str) {
    // Replace any non-word characters with a wildcard character
    return str.replace(/[^A-Za-z]+/g, "*");
}

