  // Define a dispatch function that can update the list
  list.dispatch = function(stringParameter) {
    switch (stringParameter) {
      case 'add':
        list.items.push('newItem');
        break;
      case 'remove':
        list.items.pop();
        break;
      default:
        console.log(`Invalid operation "${stringParameter}"`);
    }
  };

  return list;
}
