function traverseTree(tree, parentNode) {
  // If there are no nodes in the tree, return an empty array
  if (!tree || !tree.length) return [];

  // Create a new array to store the sub-indices of the current node
  const subIndices = [];

  // Iterate over each node in the tree and check if it has a reference to its parent node
  for (const node of tree) {
    // If the current node has a reference to its parent node, push its index into the sub-indices array
    if (node.parentNode === parentNode) {
      subIndices.push(node.index);
    }
  }

  // If there are no sub-indices for the current node, load them from a separate script file and recursively call this function with the loaded sub-indices and the relative path to the current node
  if (!subIndices.length) {
    const loadedSubIndices = loadSubIndices(parentNode);
