function liveStream(db, options = {}) {
  var keys = [];
  function generateKey() {
    var key = Math.random().toString();
    while (keys.includes(key)) {
      key = Math.random().toString();
    }
    return key;
  }
  function deleteRandomKey() {
    if (keys.length > 0) {
      var index = Math.floor(Math.random() * keys.length);
      db.del(keys[index], function (err) {
        assert(err == undefined);
      });
      keys.splice(index, 1);
    }
  }

  setInterval(deleteRandomKey, options.interval || 60 * 1000);

  return {
    on: function (event, callback) {
      if (event === "data") {
        var key = generateKey();
        while (keys.includes(key)) {
          key = generateKey();
        }
        keys.push(key);
        callback({ type: "put", key: key });
      } else if (event === "error") {
        callback("Error!");
      }
    },
  };
}
module.exports = liveStream;

