    const toml = require('toml');
    const util = require('util');
    const global = {};

    // Load TOML configuration file
    let root = toml.parse(configFile);

    // Extract configuration values from the TOML file
    let defaultUrls = join(find_if_exist(root, "common", "default_url"), "|");
    let insertUrls = join(find_if_exist(root, "common", "insert_url"), "|");

    // Set global variables based on the configuration values
    global.defaultUrls = defaultUrls;
    global.insertUrls = insertUrls;

    // Extract tags from the TOML file and store them in a list
