const fs = require('fs');
const child_process = require('child_process');

function copyFolder(src, dest) {
  try {
    fs.copySync(src, dest);
  } catch (err) {
    console.log(`Error during copying: ${err}`);
    return;
  }
}

function codesignFile(filePath, signingIdentity) {
  try {
    child_process.exec(`codesign --force --deep --verify --verbose --sign "${signingIdentity}" ${filePath}`, { cwd: './dist' });
  } catch (err) {
    console.log('Error during codesigning', err);
    return;
  }
}

function buildPackage(appFile, signingIdentityInstaller) {
  try {
    child_process.exec(`productbuild --component ${appFile} /Applications Passphrases.pkg --sign "${signingIdentityInstaller}"`, { cwd: './dist' });
  } catch (err) {
    console.log('Error during productbuild', err);
    return;
  }
}

function main(options) {
  const src = options.src || '.';
  const dest = options.dest || './dist';
  const signingIdentityApp = options.signingIdentityApp || '';
  const signingIdentityInstaller = options.signingIdentityInstaller || '';

  copyFolder(src, dest);

  if (signingIdentityApp) {
    codesignFile('Passphrases.app', signingIdentityApp);
  }

  if (signingIdentityInstaller) {
    buildPackage('Passphrases.app', signingIdentityInstaller);
  }
}
