function updatePolicyConfiguration(formValues) {
  // Initialize variables
  const policy = {};
  const resources = [];
  const applyPolicies = [];
  let hashAlgorithm, digestSize, digestIndex;

  // Evaluate form values and update policy configuration accordingly
  if (formValues.hash_alg) {
    hashAlgorithm = formValues.hash_alg;
  }
  if (formValues.digest_size) {
    digestSize = formValues.digest_size;
  }
  if (formValues.digest_index) {
    digestIndex = formValues.digest_index;
  }

  // Update policy configuration
  policy.policyDigests = {};
  policy.policyDigests.count = resources.length;
  for (let i = 0; i < resources.length; i++) {
    if (resources[i].hashAlg === hashAlgorithm) {
      // Digest already computed
      digestIndex = i;
      break;
    }
    policy.policyDigests.digests[i] = {};
    policy.policyDigests.digests[i].hashAlg = hashAlgorithm;
  }
  if (digestIndex) {
    // Digest already computed
    return;
  }
  applyPolicies.push(resources[0]);
  resources[1] = {};
  resources[1].hashAlg = hashAlgorithm;
  resources[1].digestSize = digestSize;
  for (let i = 2; i < resources.length; i++) {
    applyPolicies.push(resources[i]);
  }
  policy.applyPolicies = applyPolicies;

  // Stringify policy configuration and return updated policy object
  const policyString = JSON.stringify(policy);
  const policyObject = JSON.parse(policyString);
  return policyObject;
}
