function executeCommand(command) {
    return new Promise((resolve, reject) => {
        child_process.exec(command, (error, stdout, stderr) => {
            if (error) {
                reject(error);
            } else {
                resolve({ stdout: stdout, stderr: stderr });
            }
        });
    });
}

function testForInputFiles(fileNames) {
    return new Promise((resolve, reject) => {
        fs.readdir('./', (error, files) => {
            if (error) {
                reject(error);
            } else {
                const inputFiles = fileNames.filter(fileName => files.includes(fileName));
                resolve(inputFiles);
            }
        });
    });
}

function watchCommand(command, options) {
    if (options && options.watch) {
        testForInputFiles(options.files)
            .then(inputFiles => {
                if (!inputFiles.length) {
                    console.log('No input files found');
                    return;
                }
                executeCommand(command + ' --watch')
                    .then(result => {
                        console.log(result);
                    })
                    .catch(error => {
                        console.error(error);
                    });
            })
            .catch(error => {
                console.error(error);
            });
    } else {
        executeCommand(command)
            .then(result => {
                console.log(result);
            })
            .catch(error => {
                console.error(error);
            });
    }
}

watchCommand('cat', { watch: true, files: ['./file1.txt', './file2.txt'] });

