static int truncateTable(string $tableName)
{
    global $conn;

    // Truncate the table
    $sql = "TRUNCATE TABLE $tableName";
    $result = mysqli_query($conn, $sql);
    if (!$result) {
        return null;
    }

    // Reset the auto-incrementing ID column
    $sql = "ALTER TABLE $tableName AUTO_INCREMENT = 1";
    $result = mysqli_query($conn, $sql);
    if (!$result) {
        return null;
    }

    // Disable foreign key checks
    $sql = "SET FOREIGN_KEY_CHECKS = 0";
    $result = mysqli_query($conn, $sql);
    if (!$result) {
        return null;
    }

    return true;
}
[/PHP]
