public List<Method> getMockableMethods(List<Class<?>> classes) {
  Set<String> whitelist = new HashSet<>(Arrays.asList("getsimpleName", "isarray", "isassignablefrom", "isenum", "isinstance", "isinterface", "islocalclass", "ismemberclass", "isprimitive", "issynthetic", "getenumconstants"));
