function run_command($cmd, $log_output=false) {
  $exitcode = null;
  $output = "";

  if (is_array($cmd)) {
    $cmd = implode(" ", array_map(function ($c) { return escapeshellarg($c); }, $cmd));
  } else {
    $cmd = escapeshellarg($cmd);
  }

  $logfile = fopen("/path/to/log.txt", "a");
  if (!$logfile) {
    throw new Exception("Could not open log file for writing.");
  }

  $process = proc_open(
    $cmd,
    array(
      0 => array("pipe", "r"), // stdin
      1 => array("pipe", "w"), // stdout
      2 => array("pipe", "w")  // stderr
    ),
    $pipes,
    getcwd(),
    array()
  );

  if (!is_resource($process)) {
    throw new Exception("Could not open process for execution.");
  }

  while (true) {
    $status = proc_get_status($process);
    if ($status["running"]) {
      break;
    } elseif ($status["signaled"]) {
      $exitcode = $status["termsig"];
      break;
    } else {
      $exitcode = $status["exitcode"];
      break;
    }
  }

  fclose($logfile);

  if ($exitcode !== 0) {
    throw new Exception("Command failed with exit code " . $exitcode);
  } else {
    return $output;
  }
}
