function createRecord($url, $trackId, $userId, $createTime, $createDate, $hour, $site, $shortUrl, $httpClientIp, $httpXForwardedFor, $remoteAddr) {
    global $db;

    // Create a unique hash for the record
    $hash = md5($url . $trackId . $userId . $createTime . $createDate . $hour . $site . $shortUrl . $httpClientIp . $httpXForwardedFor . $remoteAddr);

    // Check if a record with the same hash already exists
