<?php
function processRequest($request) {
    // Get the client IP address and user agent from the request headers
    $clientIP = $request->getClientIp();
    $userAgent = $request->headers->get("User-Agent");

    // If the request is behind a reverse proxy, get the remote IP address
    if ($request->isFromTrustedProxy()) {
        $remoteIP = $request->getRemoteIp();
    } else {
        $remoteIP = "None";
    }

    // Log the client IP address and user agent along with the current timestamp
    logRequest($clientIP, $userAgent, $remoteIP);
}

function logRequest($clientIP, $userAgent, $remoteIP) {
    // Connect to the database or file where the logs will be stored
    $connection = connectToDatabase();

    // Create a new entry in the logs table with the client IP address, user agent, and remote IP address
    $query = "INSERT INTO logs (client_ip, user_agent, remote_ip) VALUES (:clientIP, :userAgent, :remoteIP)";
    $statement = $connection->prepare($query);
    $statement->bindParam(":clientIP", $clientIP);
    $statement->bindParam(":userAgent", $userAgent);
    $statement->bindParam(":remoteIP", $remoteIP);

    // Execute the query and close the database connection
    $statement->execute();
    $connection = null;
}

function connectToDatabase() {
    // Connect to the database using PDO
    $dsn = "mysql:host=localhost;dbname=mydatabase";
    $username = "root";
    $password = "";

    try {
        $connection = new PDO($dsn, $username, $password);
        $connection->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        return $connection;
    } catch (PDOException $e) {
        echo "Connection failed: " . $e->getMessage();
    }
}
?>
