function shuffle(list, seed) {
  var random = Math.random();

  if (seed != null && seed > 0) {
    random = new Random(seed);
  } else {
    random = new Random();
  }

  for (var i = 0; i < list.length * 4; i++) {
    var a = (random.nextInt(list.length)).floor();
    var b = (random.nextInt(list.length)).floor();

    if (a != b) {
      list.swap(a, b);
    }
  }

  return list;
}
