def take_sample(population, num_samples=1, with_replacement=False):
    """
    Take a random sample from a given population.

    Parameters:
        population (list or tuple): The population to draw samples from.
        num_samples (int): The number of samples to draw. Default is 1.
        with_replacement (bool): Whether to draw samples with replacement. Default is False.

    Returns:
        list: A random sample of the requested size from the population.
    """
    if num_samples < 0:
        raise ValueError("num_samples must be a non-negative integer.")
    elif len(population) == 0:
        return []

    if with_replacement:
        sample = random.sample(population, num_samples)
    else:
        sample = random.choices(population, k=num_samples)

    return list(sample)

