class Quantity:
    def __init__(self, amount, unit, error_bounds):
        self.amount = amount
        self.unit = unit
        self.error_bounds = error_bounds

    @classmethod
    def from_json(cls, json):
        """Create a Quantity from the JSON data given by the Wikibase API."""
        amount = eval(json['amount'])
        upper_bound = eval(json['upperBound'])
        lower_bound = eval(json['lowerBound'])
        error = (upper_bound - amount, amount - lower_bound)
        return cls(amount, json['unit'], error)

    def to_json(self):
        """Convert the Quantity to a JSON object."""
        return {
            'amount': self.amount,
            'unit': self.unit,
            'upperBound': self.error_bounds[0],
            'lowerBound': self.error_bounds[1]
        }

    def __str__(self):
        return json.dumps(self.to_json(), indent=4, sort_keys=True,
                          separators=(',', ': '))

    def __eq__(self, other):
        if not isinstance(other, Quantity):
            return False
        return (self.amount == other.amount and self.unit == other.unit
                and self.error_bounds == other.error_bounds)
