def get_job_exit_code(job_id):
    # Use subprocess to execute a command that retrieves the job's exit code
    args = ["bjobs", "-l", str(job_id)]
    process = subprocess.Popen(" ".join(args), shell=True, stdout = subprocess.PIPE, stderr = subprocess.STDOUT)

    # Parse the output of the command to extract the exit code
    for line in process.stdout:
        if line.find("Completed <exit>") > -1:
            return 1
        elif line.find("Completed <done>") > -1:
            return 0

