def get_table_rows(tables):
    conn = sqlite3.connect('mydatabase')
    cursor = conn.cursor()

    for table in tables:
        cursor.execute("SELECT COUNT(*) FROM {}".format(table))
        rows = cursor.fetchall()

        if len(rows) == 0:
            raise ValueError("Table '{}' has no rows".format(table))

    return [row[0] for row in rows]

