    forwardIndex = {}
    idToUrl = {}

    for filepath in os.listdir(directory):
        with open(os.path.join(directory, filepath), "r") as f:
            text = f.read()
            tokens = text.split()
            for token in tokens:
                stemmed_token = stemmer.stem(token)
                if stemmed_token not in invertedIndex:
                    invertedIndex[stemmed_token] = []
                invertedIndex[stemmed_token].append(filepath)
            forwardIndex[filepath] = text
            idToUrl[filepath] = os.path.join(directory, filepath)

