from secrets import token_hex

class UserAccount:
    def __init__(self, username, password):
        self.username = username
        self.password = password
        self.phone_number = None
        self.emergency_contact = None

    @property
    def password(self):
        return self._password

    @password.setter
    def password(self, value):
        salt = token_hex(16)
        hashed_value = hashlib.sha256(value + salt).hexdigest()
        self._password = (hashed_value, salt)

    @property
    def password_hash(self):
        return self._password[0]

    @property
    def salt(self):
        return self._password[1]

    def verify_password(self, password):
        hashed_value = hashlib.sha256(password + self.salt).hexdigest()
