def image_similarity(image, features):
    max_local_similarity = 0
    max_global_similarity = 0
    similarity_vector = np.zeros((len(features),))

    for i, feature in enumerate(features):
        local_similarity = np.absolute((feature['llfeature'] - image['llfeature']).sum())
        global_similarity = np.logical_xor(feature['glfeature'], image['glfeature']).sum()

        similarity_vector[i] = local_similarity + global_similarity

        if local_similarity > max_local_similarity:
            max_local_similarity = local_similarity

        if global_similarity > max_global_similarity:
            max_global_similarity = global_similarity

    return (max_local_similarity, max_global_similarity, similarity_vector)

