import os

def copy_dir(source_dir, dest_dir):
    # Check if source directory exists and is a directory
    if not os.path.isdir(source_dir):
        raise ValueError("Source directory does not exist or is not a directory")

    # Create destination directory if it does not exist
    if not os.path.exists(dest_dir):
        os.makedirs(dest_dir)

    # Copy files and directories inside source directory to destination directory
    for entry in os.scandir(source_dir):
        src = os.path.join(source_dir, entry.name)
        dst = os.path.join(dest_dir, entry.name)
        if entry.is_file():
            shutil.copy(src, dst)
        elif entry.is_dir():
            copy_dir(src, dst)

    return None
