CREATE FUNCTION rename_and_add_column(table_name VARCHAR, old_column_name VARCHAR, new_column_name VARCHAR, new_field_object OBJECT) RETURNS VOID AS $$
DECLARE
  temp_column_name VARCHAR;
BEGIN
  -- Rename the old column to a temporary name to avoid conflicts with the new column
  temp_column_name := _generate_temp_name(old_column_name);
  EXECUTE 'ALTER TABLE' || table_name || 'RENAME COLUMN' || old_column_name || 'TO' || temp_column_name;

  -- Add the new column with the specified data type and constraints
  ADD COLUMN new_column_name new_field_object;

  -- Update any foreign key references to the renamed column
  UPDATE table_name SET new_column_name = temp_column_name WHERE old_column_name = temp_column_name;

  -- Drop the temporary column and constraints
  DROP COLUMN temp_column_name;
END;
$$ LANGUAGE plpgsql;
