        form = ResetForm(request.POST)
        if form.is_valid():
            # Force creating new session
            request.session.create()
            if request.user.is_authenticated():
                logout(request)

            token = generate_token(request)
            url = reverse('password-reset', args=[token])
            send_mail(_('Password reset'), _('Click on the link below to reset your password: {url}').format(url=url), from_address='your-email@example.com', to_address=request.user.email)
