def get_md5_hashes(directory_path):
    import hashlib
    file_list = []
    for root, dirs, files in os.walk(directory_path):
        for file in files:
            file_list.append(os.path.join(root, file))
    md5_hashes = {}
    for file in file_list:
        with open(file, "rb") as f:
            the_hash = hashlib.md5()
            for line in f.readlines():
                the_hash.update(line)
            md5_hashes[os.path.basename(file)] = the_hash.hexdigest()
    return {"number of test cases": len(file_list), "map of file names to MD5 hashes": md5_hashes}

