import hashlib

def generate_message(nonce, nc, cnonce, qop, uri, realm, cred_info, method):
    if cred_info.data_type == PJSIP_CRED_DATA_PLAIN_PASSWD:
        ha1 = hashlib.sha256(cred_info.username + ":" + realm + ":" + cred_info.data).hexdigest()
    elif cred_info.data_type == PJSIP_CRED_DATA_DIGEST:
        ha1 = cred_info.data[:64]
    else:
        raise ValueError("Invalid data type")

    ha2 = hashlib.sha256(method + ":" + uri).hexdigest()

    if qop is not None and qop != 0:
        response = hashlib.sha256(ha1 + ":" + nonce + ":" + nc + ":" + cnonce + ":" + qop + ":" + ha2).hexdigest()
    else:
        response = hashlib.sha256(ha1 + ":" + nonce + ":" + ha2).hexdigest()

    return response
