impl JoystickState {
    pub fn new(button_caps: Vec<HIDP_BUTTON_CAPS>, value_caps: Vec<HIDP_VALUE_CAPS>) -> JoystickState {
        let mut axis_states = HashMap::new();
        let hat_switches = vec![];

        for value_cap in value_caps.iter() {
            let usage_id = value_cap.u.Range().UsageMin;
            let value_range = value_cap.u.Range();
            axis_states.insert(usage_id, (value_range.LogicalMin as f64)..(value_range.LogicalMax as f64));
