use std::intrinsics;

fn handle_stack_exhaustion() {
    let mut stack_limit = intrinsics::record_sp_limit(0);
    let new_stack_limit = (stack_limit - BASIC_STACK_SIZE).max(LUAI_MAXSTACK);
    if new_stack_limit < stack_limit {
