use wasmtime::{Engine, Module, Store, Linker, Instance};

fn link_module(path: &str, bytecode_file: &str) {
    let mut file = File::open(path).unwrap();
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer).unwrap();

    let engine = Engine::default();
    let module = Module::from_buffer(&engine, &buffer).unwrap();
    let store = Store::new(&engine);
    let linker = Linker::new(&store);

    let mut bytecode_file = File::open(bytecode_file).unwrap();
    let mut bytecode_buffer = Vec::new();
    bytecode_file.read_to_end(&mut bytecode_buffer).unwrap();

    let mut linker = Linker::new(&store);
    linker.module("", &module, bytecode_buffer.as_slice()).unwrap();
}
