fn read_file_append_args(args: Vec<String>, file_path: &str) -> String {
    let mut output = String::new();

    // Check if the file exists and is a regular file.
    let path = Path::new(file_path);
    if !path.is_file() {
        panic!("Supplied file does not exist");
    }

    // Read the contents of the file into a buffered reader.
    let reader = io::BufReader::new(fs::File::open(path).unwrap()).bytes();

    // Append the contents of the file to the output string.
    for byte in reader {
        if let Ok(byte) = byte {
            output.push(byte as char);
        }
    }

    // Append the remaining command line arguments to the output string.
    if !args.is_empty() {
        output += " ";
        for arg in args {
            output += &arg;
            output += " ";
        }
    }

    output
}

