fn compile_strings(sources: &[String], closure: impl FnOnce() -> i32) -> i32 {
	let mut op_array = vec![];
	for source in sources {
		let mut lexical_state = LexicalState::default();
		let mut active_op_array = CG(active_op_array);
		let mut original_in_compilation = CG(in_compilation);
		CG(in_compilation) = 1;

