		if zend_prepare_string_for_scanning(source, filename TSRMLS_CC) == FAILURE {
			continue;
		} else {
			let mut orig_interactive = CG(interactive);
			CG(interactive) = 0;
			init_op_array(&mut op_array, ZEND_EVAL_CODE, INITIAL_OP_ARRAY_SIZE TSRMLS_CC);
			CG(interactive) = orig_interactive;
			CG(active_op_array) = &op_array;
			zend_stack_push(&mut CG(context_stack), (void *) &CG(context), sizeof(CG(context)));
			zend_init_compiler_context(TSRMLS_C);
			BEGIN(ST_IN_SCRIPTING);
			let compiler_result = zendparse(TSRMLS_C);

			if SCNG(script_filtered) != NULL {
				efree(SCNG(script_filtered));
