use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

fn main() {
    let filename = String::from("input.txt");
    let num_lines = get_num_letter_only_lines(filename);
    println!("{}", num_lines);
}

fn get_num_letter_only_lines(filename: String) -> i32 {
    // Open the file in read-only mode with buffered I/O.
    let file = File::open(Path::new(&filename)).unwrap();
    let reader = BufReader::new(file);

    // Iterate over each line of the file.
    let mut num_lines = 0;
    for line in reader.lines() {
        if is_line_letter_only(line.as_ref().unwrap()) {
            num_lines += 1;
        }
    }
    return num_lines;
}

fn is_line_letter_only(line: &str) -> bool {
    let line = line.trim();
    if line.is_empty() {
        // Empty lines are not letter-only lines.
        return false;
    }
    for c in line.chars() {
        if !c.is_alphabetic() {
            return false;
        }
    }
    true
}

