use std::thread;
use flate2::write::GzEncoder;

fn main() {
    // Parse our CLI arguments and prepare the reactor.
    let addr = env::args().nth(1).unwrap_or("127.0.0.1:8080".to_string());
    let addr = addr.parse::<SocketAddr>().unwrap();
    let mut core = Core::new().unwrap();
    let handle = core.handle();
    let socket = TcpListener::bind(&addr, &handle).unwrap();
    println!("Listening on: {}", addr);

    // Accept incoming connections and create a thread pool for each one using the number of available CPUs.
    for stream in socket.incoming() {
        match stream {
            Ok(stream) => {
                let handle = handle.clone();
                let mut core = core.clone();
                thread::spawn(move || {
                    // Create a GzEncoder and use it to compress the incoming data.
                    let encoder = GzEncoder::new();
                    let mut bytes = Vec::new();
                    stream.read_to_end(&mut bytes).unwrap();
                    let compressed_data = encoder.encode_all(&bytes);

                    // Send the compressed data back to the client over the TCP connection.
                    let mut writer = stream.write_only(handle, core.get_reactor());
                    writer.write_all(compressed_data).unwrap();
                });
            }
            Err(_) => {}
        }
    }
}
