#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <dirent.h>
#include <unistd.h>

void copy_files(const char *source_dir, const char *dest_dir, const char *library_path, const char *compiler_path) {
	// Open the source directory and read its contents
	DIR *source = opendir(source_dir);
	struct dirent *entry;
	while ((entry = readdir(source)) != NULL) {
		char path[PATH_MAX];
		snprintf(path, sizeof(path), "%s/%s", source_dir, entry->d_name);

		// Check if the file is a directory and recurse if it is
		if (entry->d_type == DT_DIR) {
			char dest[PATH_MAX];
			snprintf(dest, sizeof(dest), "%s/%s", dest_dir, entry->d_name);
			copy_files(path, dest, library_path, compiler_path);
		} else {
			// Check if the file is in the library path and skip it if it is
			if (strcmp(library_path, path) == 0) {
				continue;
			}

			// Copy the file to the destination directory
			char dest[PATH_MAX];
			snprintf(dest, sizeof(dest), "%s/%s", dest_dir, entry->d_name);
			copy_file(path, dest);

			// Set the executable bit for the file if it has the same name as a file in the library path
			if (strcmp(library_path, dest) == 0) {
				set_executable_bit(dest);
			}
		}
	}
}

void copy_file(const char *source, const char *dest) {
	FILE *in = fopen(source, "r");
	if (!in) {
		fprintf(stderr, "Error opening file %s\n", source);
		return;
	}

	FILE *out = fopen(dest, "w");
	if (!out) {
		fclose(in);
		fprintf(stderr, "Error creating file %s\n", dest);
		return;
	}

	char buf[BUFSIZ];
	while (fgets(buf, sizeof(buf), in)) {
		fputs(buf, out);
	}

	fclose(in);
	fclose(out);
}

void set_executable_bit(const char *path) {
	struct stat st;
	if (stat(path, &st)) {
		fprintf(stderr, "Error setting executable bit for file %s\n", path);
		return;
	}

	mode_t mode = S_IRUSR | S_IWUSR | S_IXUSR;
	if (chmod(path, st.st_mode | mode)) {
		fprintf(stderr, "Error setting executable bit for file %s\n", path);
	}
}

int main(int argc, char *argv[]) {
	// Check the number of arguments
	if (argc < 4) {
		fprintf(stderr, "Usage: %s source_dir dest_dir library_path compiler_path\n", argv[0]);
		return 1;
	}

	// Copy the files
	copy_files(argv[1], argv[2], argv[3], argv[4]);

	return 0;
}

