fn realpath(path: &str) -> String {
    let mut base = "";
    for part in path.split(std::path::MAIN_SEPARATOR) {
        if base != "" {
            try {
                // Need to use salt.utils.path.readlink as it handles junctions
                part = salt.utils.path.readlink(&format!("{}{}", base, part));
                base = std::path::abspath(part);
            } catch OSError {
                base = std::path::abspath(&format!("{}{}", base, part));
            }
        } else {
            base = part;
        }
    }
    // Python 3.8 added support for directory junctions which prefixes the
    // return with `\\?\`. We need to strip that off.
    // https://docs.python.org/3/library/os.html#os.readlink
    if base.starts_with("\\\\?\\") {
        base = &base[4..];
    }
    return base;
}
