use rocket::Rocket;
use rocket::fairing::AdHoc;
use rocket::http::Status;
use rocket::request::Request;
use rocket::response::Response;
use rocket_contrib::json::JsonValue;
use hmac::{Mac, NewMac};
use sha1::Sha1;

#[post("/", data = "<data>")]
fn post(req: &Request<'_>, config: AdHoc<Config>) -> Result<Response<'static>> {
    let header_value = req.headers().get("X-Hub-Signature").map(|h| h.to_str()).unwrap();
    if header_value == "" {
        return Ok(Response::with((status::BadRequest, "Missing Github Header.")));
    }

    let mut hmac = Mac::new(&Sha1::new());
    hmac.input(config.secret.as_bytes());
    hmac.input(req.body().unwrap().as_bytes());
    let result = hmac.result();

    if result != header_value {
        return Ok(Response::with((status::BadRequest, "Invalid Request Body.")));
    }

    Ok(Response::with((status::Ok, req.body())))
}
