use process_execution::{CommandRunner, ProcessMetadata};
use process_execution::local::CommandRunner;
use nailgun::CommandRunner;
use std::path::PathBuf;

pub fn create_process(metadata: &ProcessMetadata) -> Box<dyn CommandRunner> {
    let command = metadata.command();
    let args = metadata.args();
    let working_dir = metadata.working_directory();

    if command.is_empty() {
        panic!("Executable name not specified");
    }

    let mut command_line = vec![command];
    for arg in args {
        command_line.push(arg);
    }

    let local_command_runner = CommandRunner::new(working_dir);
    let mut process = local_command_runner.run(&command_line, &[]).unwrap();

    if process_execution_local_enable_nailgun() {
        let nailgun_command_runner = NailgunCommandRunner::new(local_command_runner, metadata);
        process = nailgun_command_runner.run(&command_line, &[]).unwrap();
    }

    Box::new(process)
}

