fn realpath(path: &str) -> String {
    let mut path_parts = path.split("/");
    let mut current_directory = std::env::current_dir().unwrap();
    for part in path_parts {
        if !part.is_empty() {
            try {
                // Need to use salt.utils.path.readlink as it handles junctions
                let new_part = salt::utils::path::readlink(format!("{}/{}", current_directory, part));
                current_directory = std::fs::canonicalize(new_part).unwrap();
            } catch OSError {
                current_directory = format!("{}/{}", current_directory, part);
            }
        } else {
            break;
        }
    }
    return String::from(current_directory.to_str().unwrap());
}
