use std::fs;
use std::path::PathBuf;

pub fn generate_gitignore(templates: Vec<&str>, repository: &str) -> Result<(), Error> {
    let destination = temp_dir().join("my-project/.gitignore");
    let mut file = File::create(&destination)?;

    for template in templates {
        let template_path = PathBuf::from(repository).join(template);
        let content = read_to_string(template_path)?;

        file.write_all(format!("### {}\n", template).as_bytes())?;
        file.write_all(content.as_bytes())?;

        if !template.ends_with("/") {
            file.write_all(b"\n")?;
        }
    }

    file.sync_all()?;

    Ok(destination)
}
