let params = [
("callback", "jsonp"),
("action", "login"),
("username", self.username.as_str()),
("password", password_encoded.as_str()),
("chksum", &chksum.as_str()),
("info", &info.as_str()),
("ac_id", self.ac_id.as_str()),
("ip", &self.ip.to_string()),
("type", SRUN_TYPE),
("n", SRUN_N),
];
let url = format!("{}/cgi-bin/srun_portal", SRUN_PORTAL);

