md5.input(if is_server {
kServerSigningKeyMagic
} else {
kClientSigningKeyMagic
});

let mut hash = vec![0u8; 16];
md5.result(&mut hash);

Some(SignKey::from_iter(hash.into_iter()))
} else {
None
}
}

