int createTempFile(char *prefix, char *postfix, int flags) {
    // Create a temporary file with the given prefix and postfix.
    // The file will be automatically deleted when it is closed or the program terminates.
    // If the 'flags' argument is non-zero, it specifies additional flags to pass to open().

    // Get the base directory for temporary files.
    char *baseDir = getenv("TMPDIR");
    if (baseDir == NULL) {
        baseDir = "/tmp";
    }

    // Generate a unique name for the file.
    char filename[256];
    sprintf(filename, "%s%d", prefix, rand());

    // Open the file and return the file descriptor.
    int fd = open(filename, O_RDWR | O_CREAT | O_EXCL | flags, 0600);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Delete the file when it is closed or the program terminates.
    unlink(filename);

    return fd;
}

