fn open_file_with_browser(path: &str) -> Result<(), String> {
    // Try to use the environment variable $BROWSER first
    let browser = match std::env::var("BROWSER") {
        Ok(b) => b,
        Err(_) => return Err("Browser not found".to_string()),
    };

    // If that fails, try a list of alternative programs (xdg-open, gnome-open, kde-open)
    let alternatives = vec!["xdg-open", "gnome-open", "kde-open"];

    for alt in &alternatives {
        match std::process::Command::new(alt).arg(path).spawn() {
            Ok(_) => return Ok(()),
            Err(_) => continue,
        }
    }

    // If none of the programs work, return an error message containing the list of methods that were tried
    let mut msg = "Tried ".to_string();
    for alt in &alternatives {
        msg.push_str(alt);
        if alt != alternatives.last().unwrap() {
            msg.push_str(", ");
        }
    }
    Err(msg)
}
