#[cfg(feature = "arg-parser")]
use lazy_static::lazy_static;

pub struct ServerArgs {
    pub server_port: u16,
    pub user_data_path: String,
    pub rally_point_port: u16,
}

impl Default for ServerArgs {
    fn default() -> Self {
        Self {
            server_port: 8080,
            user_data_path: "".to_string(),
            rally_point_port: 8081,
        }
    }
}

lazy_static! {
    static ref SERVER_ARGS: ServerArgs = ServerArgs::default();
}

pub fn parse_server_args(args: &[String]) -> Option<ServerArgs> {
    for arg in args.iter() {
        if let Some(key) = arg.strip_prefix("--") {
            match key {
                "port" => SERVER_ARGS.server_port = parse_port(arg)?,
                "user-data-path" => SERVER_ARGS.user_data_path = parse_string(arg)?,
                "rally-point-port" => SERVER_ARGS.rally_point_port = parse_port(arg)?,
                _ => return None,
            }
        } else if let Some(key) = arg.strip_prefix("-") {
            match key {
                "p" | "port" => SERVER_ARGS.server_port = parse_port(arg)?,
                "u" | "user-data-path" => SERVER_ARGS.user_data_path = parse_string(arg)?,
                "r" | "rally-point-port" => SERVER_ARGS.rally_point_port = parse_port(arg)?,
                _ => return None,
            }
        } else {
            return None;
        }
    }

    Some(SERVER_ARGS.clone())
}

fn parse_string(s: &str) -> Option<String> {
    let mut iter = s.split('=');
    iter.next()?;
    Some(iter.next()?.to_string())
}

fn parse_port(s: &str) -> Option<u16> {
    let mut iter = s.split('=');
    iter.next()?;
    Some(iter.next()?.parse::<u16>()?)
}
