fn get_binary_name(path: &Path) -> Result<String, std::io::Error> {
    let filename = path.file_name().ok_or("Could not determine file name")?;
    let mut name = String::new();
    for c in filename.to_string_lossy().chars() {
        if !c.is_numeric() && !c.is_alphabetic() && !c.is_whitespace() {
            break;
        }
        name.push(c);
    }
    Ok(name)
