use std::env;
use std::fs;

pub struct TempDir {
    path: String,
}

impl Drop for TempDir {
    fn drop(&mut self) {
        fs::remove_dir_all(self.path).unwrap();
    }
}

fn create_temp_dir() -> TempDir {
    let base_dir = env::temp_dir().unwrap();
    let mut base_name = format!("{}-", SystemTime::now().duration_since(UNIX_EPOCH).expect("Failed to get system time").as_millis());

    for counter in 0..TEMP_DIR_ATTEMPTS {
        let temp_dir = base_dir.join(&base_name + &counter);
        if fs::create_dir(temp_dir).is_ok() {
            return TempDir { path: temp_dir };
        }
    }

    panic!("Failed to create directory within {} attempts (tried {}0 to {})", TEMP_DIR_ATTEMPTS, base_name + "0", base_name + &(TEMP_DIR_ATTEMPTS - 1));
}
```
