#[derive(Deserialize)]
struct Config {
    #[serde(default)]
    access_key: String,
    secret_key: String,
}

fn read_config(path: &str) -> HashMap<String, Config> {
    let mut config = HashMap::new();
    if let Ok(contents) = std::fs::read_to_string(path) {
        for line in contents.lines() {
            let parts: Vec<&str> = line.split('=').collect();
            if parts.len() == 2 {
                config.insert(parts[0].trim().to_owned(), Config { access_key: parts[1].trim().to_owned(), secret_key: "" });
            }
        }
    }
    config
}

async fn get_access_token() -> String {
    let path = std::env::args().nth(2).unwrap();
    let mut token = read_config(&path);
    if token.contains_key("access_token") {
        token["access_token"].access_key
    } else {
        "".to_owned()
    }
}

async fn get_bot_config(path: &str) -> BotConfig {
    let mut config = read_config(&path);
    if !config.contains_key("irc") || !config["irc"].contains_key("servers") {
        return BotConfig::default();
    }
    let servers = config["irc"]["servers"];
    let mut irc_config = IrcConfig::new(servers);
    irc_config.nickname = config["irc"]["nickname"].to_owned();
    irc_config.user = config["irc"]["user"].to_owned();
    irc_config.realname = config["irc"]["realname"].to_owned();
    BotConfig::new(irc_config)
}

async fn main() {
    let access_token = get_access_token().await;
    let bot_config = get_bot_config("bot.toml").await;
    println!("Access token: {}", access_token);
    println!("Bot config: {:?}", bot_config);
}
